-- Functions
CREATE OR REPLACE FUNCTION private.accounting_contract_terms_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  flag_key text;
  flag_val jsonb;
  basis text;
  allowed text[];
  old_j jsonb;
  new_j jsonb;
  ch jsonb := '[]'::jsonb;
begin
  if new.posture is distinct from 'estimate' then
    raise exception 'Contract figures stay an estimate.' using errcode = 'P0001';
  end if;
  if new.field_flags is null or jsonb_typeof(new.field_flags) <> 'object' then
    raise exception 'Contract figure markers must be an object.' using errcode = 'P0001';
  end if;
  for flag_key, flag_val in select key, value from jsonb_each(new.field_flags) loop
    if flag_key not in (
      'salePrice','listingPrice','loanAmount','loanRate','downPayment','sellerCreditAmount','buyerBrokerAmount',
      'listingCommissionAmount','warrantyCap','hoaMonthly','hoaCertificateBalance','condoMonthly','condoCertificateBalance',
      'transferFeeEach','deferredAmount','taxLevy','taxAssessment','taxPayable','emdAmount'
    ) then
      raise exception 'Unknown contract figure marker.' using errcode = 'P0001';
    end if;
    if jsonb_typeof(flag_val) <> 'object' then
      raise exception 'A contract figure marker is incomplete.' using errcode = 'P0001';
    end if;
    if (select count(*) from jsonb_object_keys(flag_val) k where k not in ('basis', 'provisional', 'source')) > 0 then
      raise exception 'A contract figure marker has an unknown part.' using errcode = 'P0001';
    end if;
    if coalesce(flag_val->>'provisional', 'true') is distinct from 'true' then
      raise exception 'Contract figures stay provisional.' using errcode = 'P0001';
    end if;
    basis := flag_val->>'basis';
    allowed := case
      when flag_key = 'loanRate' then array['quoted','locked']
      when flag_key in ('hoaCertificateBalance','condoCertificateBalance','taxLevy','taxAssessment') then array['historical','explicit']
      when flag_key = 'hoaMonthly' or flag_key = 'condoMonthly' or flag_key = 'transferFeeEach' then array['explicit','historical']
      when flag_key = 'taxPayable' then array['explicit']
      else array['explicit','derived','calculated']
    end;
    if basis is null or not (basis = any (allowed)) then
      raise exception 'Contract figure marker is not an allowed kind.' using errcode = 'P0001';
    end if;
    if coalesce(char_length(flag_val->>'source'), 0) > 500 then
      raise exception 'Contract figure source is too long.' using errcode = 'P0001';
    end if;
    if (case flag_key
      when 'salePrice' then new.sale_price is null
      when 'listingPrice' then new.listing_price is null
      when 'loanAmount' then new.loan_amount is null
      when 'loanRate' then new.loan_rate is null
      when 'downPayment' then new.down_payment is null
      when 'sellerCreditAmount' then new.seller_credit_amount is null
      when 'buyerBrokerAmount' then new.buyer_broker_amount is null
      when 'listingCommissionAmount' then new.listing_commission_amount is null
      when 'warrantyCap' then new.warranty_cap is null
      when 'hoaMonthly' then new.hoa_monthly is null
      when 'hoaCertificateBalance' then new.hoa_certificate_balance is null
      when 'condoMonthly' then new.condo_monthly is null
      when 'condoCertificateBalance' then new.condo_certificate_balance is null
      when 'transferFeeEach' then new.transfer_fee_each is null
      when 'deferredAmount' then new.deferred_amount is null
      when 'taxLevy' then new.tax_levy is null
      when 'taxAssessment' then new.tax_assessment is null
      when 'taxPayable' then new.tax_payable is null
      when 'emdAmount' then new.emd_amount is null
      else true
    end) then
      raise exception 'A contract figure marker needs a figure. Blank is unknown, not zero.' using errcode = 'P0001';
    end if;
  end loop;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
  else
    new.deal_id := old.deal_id;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
  end if;
  new.updated_by := auth.uid();
  new.updated_at := now();
  old_j := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  new_j := to_jsonb(new);
  select coalesce(jsonb_agg(jsonb_build_object('field', e.key, 'old', old_j->e.key, 'new', e.value)), '[]'::jsonb)
    into ch
  from jsonb_each(new_j) e
  where e.key not in ('created_at', 'updated_at', 'created_by', 'updated_by')
    and (old_j is null or (old_j->e.key) is distinct from e.value);
  insert into public.accounting_contract_terms_log (deal_id, action, changed_by, old_row, new_row, changes)
  values (new.deal_id, case when tg_op = 'INSERT' then 'added' else 'edited' end, auth.uid(), old_j, new_j, ch);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.acct_calc_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_now jsonb;
begin
  if tg_op = 'UPDATE' and old.calc_source is not null and (new.calc_source is distinct from old.calc_source or new.calc_key is distinct from old.calc_key) then
    raise exception 'A fee calculated from CLA rates keeps its tag and key.' using errcode = 'P0001'; end if;
  if new.calc_source is null then new.overridden := false; return new; end if;
  v_now := jsonb_build_object('description', new.description, 'altaSection', new.alta_section, 'cdSection', new.cd_section, 'cdLine', new.cd_line, 'payee', new.payee,
    'amount', new.amount, 'paidBy', new.paid_by, 'split', jsonb_build_object('buyer', new.split_buyer, 'seller', new.split_seller, 'lender', new.split_lender, 'other', new.split_other),
    'titlePrefix', new.title_prefix, 'timing', new.timing, 'poc', new.poc);
  new.overridden := exists (select 1 from jsonb_each(v_now) e where (new.calc_fields -> e.key) is distinct from e.value);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.acct_cd_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare k text;
begin
  if tg_op = 'DELETE' then raise exception 'Closing Disclosure details are never deleted.' using errcode = 'P0001'; end if;
  if jsonb_typeof(new.data) <> 'object' then raise exception 'Closing Disclosure details must be a set of named fields.' using errcode = '23514'; end if;
  for k in select jsonb_object_keys(new.data) loop
    if k !~ '^[a-z]{1,8}[0-9]?\.[A-Za-z0-9]{1,30}$' then raise exception 'Unknown Closing Disclosure field: %', k using errcode = '23514'; end if;
    if jsonb_typeof(new.data -> k) not in ('string', 'number') then raise exception 'Closing Disclosure field % must be text or a number.', k using errcode = '23514'; end if;
  end loop;
  if tg_op = 'INSERT' then new.created_by := coalesce(private.effective_uid(), new.created_by); new.updated_by := new.created_by; new.created_at := now(); new.updated_at := now(); return new; end if;
  if new.deal_id <> old.deal_id then raise exception 'Closing Disclosure details cannot move to another order.' using errcode = 'P0001'; end if;
  if new.created_by is distinct from old.created_by or new.created_at <> old.created_at then raise exception 'Who created them never changes.' using errcode = 'P0001'; end if;
  new.updated_by := private.effective_uid(); new.updated_at := now(); return new;
end $function$

CREATE OR REPLACE FUNCTION private.acct_cd_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_old jsonb := case when tg_op = 'UPDATE' then old.data else '{}'::jsonb end; v_changes jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('field', k, 'old', v_old -> k, 'new', new.data -> k) order by k), '[]'::jsonb) into v_changes
    from (select jsonb_object_keys(v_old) k union select jsonb_object_keys(new.data)) keys where (v_old -> k) is distinct from (new.data -> k);
  if tg_op = 'UPDATE' and v_changes = '[]'::jsonb then return null; end if;
  insert into public.accounting_cd_log (deal_id, action, changed_by, old_data, new_data, changes)
    values (new.deal_id, case when tg_op = 'INSERT' then 'added' else 'edited' end, private.effective_uid(), case when tg_op = 'UPDATE' then old.data else null end, new.data, v_changes);
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.acct_editor(d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.acct_on() and coalesce((select p.is_admin or (p.role in ('Processor', 'Preprocessor')
      and coalesce((select r.allowed from public.role_module_access r where r.role = p.role and r.module = 'accounting'), false))
    from public.profiles p where p.id = private.effective_uid() and p.status = 'active'), false) and private.can_access_deal(d) $function$

CREATE OR REPLACE FUNCTION private.acct_fee_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_type text;
begin
  if tg_op = 'DELETE' then raise exception 'Fees are never deleted. Retire it instead.' using errcode = 'P0001'; end if;
  select transaction_type into v_type from public.deals where id = new.deal_id;
  if v_type = 'Refinance' and (new.split_seller > 0 or new.credit_from = 'seller' or new.credit_to = 'seller') then
    raise exception 'A refinance has no seller side.' using errcode = '23514'; end if;
  if tg_op = 'INSERT' then
    new.created_by := coalesce(private.effective_uid(), new.created_by); new.updated_by := new.created_by; new.created_at := now(); new.updated_at := now();
    new.retired_at := null; new.retired_by := null; return new; end if;
  if new.deal_id <> old.deal_id then raise exception 'A fee cannot move to another order.' using errcode = 'P0001'; end if;
  if new.created_by is distinct from old.created_by or new.created_at <> old.created_at then raise exception 'Who created a fee never changes.' using errcode = 'P0001'; end if;
  if old.retired_at is not null and new.retired_at is not null and (to_jsonb(new) - array['updated_at', 'updated_by', 'retired_at', 'retired_by']) <> (to_jsonb(old) - array['updated_at', 'updated_by', 'retired_at', 'retired_by']) then
    raise exception 'This fee is retired. Restore it before editing.' using errcode = 'P0001'; end if;
  if old.retired_at is null and new.retired_at is not null then new.retired_by := private.effective_uid(); new.retired_at := now(); end if;
  if new.retired_at is null then new.retired_by := null; end if;
  new.updated_by := private.effective_uid(); new.updated_at := now(); return new;
end $function$

CREATE OR REPLACE FUNCTION private.acct_fee_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else null end; v_new jsonb := to_jsonb(new); v_changes jsonb; v_action text;
begin
  select coalesce(jsonb_agg(jsonb_build_object('field', k, 'old', v_old -> k, 'new', v_new -> k) order by k), '[]'::jsonb) into v_changes
    from jsonb_object_keys(v_new) k where k not in ('updated_at', 'updated_by', 'created_at', 'created_by', 'retired_by', 'id', 'deal_id') and (v_old is null or v_old -> k is distinct from v_new -> k);
  v_action := case when tg_op = 'INSERT' then 'added' when old.retired_at is null and new.retired_at is not null then 'retired' when old.retired_at is not null and new.retired_at is null then 'restored' else 'edited' end;
  if tg_op = 'UPDATE' and v_changes = '[]'::jsonb then return null; end if;
  insert into public.accounting_fee_log (deal_id, fee_id, action, changed_by, old_row, new_row, changes) values (new.deal_id, new.id, v_action, private.effective_uid(), v_old, v_new, v_changes);
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.acct_log_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin raise exception 'The accounting edit history is never changed or deleted.' using errcode = 'P0001'; end $function$

CREATE OR REPLACE FUNCTION private.acct_meta_ok(m jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare p jsonb; k text;
begin
  if m is null then return true; end if;
  if jsonb_typeof(m) <> 'object' or pg_column_size(m) > 8000 then return false; end if;
  for k in select jsonb_object_keys(m) loop if k not in ('payments', 'loanPct', 'months', 'perDiem', 'perMonth', 'recType', 'paidTo', 'group') then return false; end if; end loop;
  if m ? 'paidTo' and not (jsonb_typeof(m -> 'paidTo') = 'string' and char_length(m ->> 'paidTo') <= 120) then return false; end if;
  if m ? 'group' and not coalesce(m ->> 'group' in ('hoaGr'), false) then return false; end if;
  if m ? 'loanPct' and not (jsonb_typeof(m -> 'loanPct') = 'number' and (m ->> 'loanPct')::numeric between 0 and 100) then return false; end if;
  if m ? 'months' and not (jsonb_typeof(m -> 'months') = 'number' and (m ->> 'months')::numeric between 0 and 360 and (m ->> 'months')::numeric = trunc((m ->> 'months')::numeric)) then return false; end if;
  if m ? 'perMonth' and not (jsonb_typeof(m -> 'perMonth') = 'number' and (m ->> 'perMonth')::numeric between 0 and 100000000) then return false; end if;
  if m ? 'recType' and not coalesce(m ->> 'recType' in ('Deed', 'Mortgage', 'Release', 'Assignment', 'Power of Attorney', 'Other'), false) then return false; end if;
  if m ? 'perDiem' then
    if jsonb_typeof(m -> 'perDiem') <> 'object' then return false; end if;
    for k in select jsonb_object_keys(m -> 'perDiem') loop if k not in ('from', 'to', 'perDiem', 'rate', 'daysPerYear', 'decimals', 'paidBy') then return false; end if; end loop;
    if (m -> 'perDiem') ? 'from' and not coalesce(m -> 'perDiem' ->> 'from' ~ '^\d{4}-\d{2}-\d{2}$', false) then return false; end if;
    if (m -> 'perDiem') ? 'to' and not coalesce(m -> 'perDiem' ->> 'to' ~ '^\d{4}-\d{2}-\d{2}$', false) then return false; end if;
    if (m -> 'perDiem') ? 'daysPerYear' and not coalesce(m -> 'perDiem' ->> 'daysPerYear' in ('360', '365', '366'), false) then return false; end if;
    if (m -> 'perDiem') ? 'paidBy' and not coalesce(m -> 'perDiem' ->> 'paidBy' in ('buyer', 'seller'), false) then return false; end if;
  end if;
  if m ? 'payments' then
    if jsonb_typeof(m -> 'payments') <> 'array' or jsonb_array_length(m -> 'payments') > 8 then return false; end if;
    for p in select jsonb_array_elements(m -> 'payments') loop
      if jsonb_typeof(p) <> 'object' then return false; end if;
      for k in select jsonb_object_keys(p) loop
        if k not in ('payee', 'method', 'label', 'memo', 'amount', 'street', 'unit', 'intl', 'transferOrder', 'forBenefitOf', 'releaseNote', 'releaseDate', 'aggregatePayee') then return false; end if; end loop;
      if not coalesce(p ->> 'method' in ('check', 'wire', 'netFunded', 'aggregate', 'transfer', 'holdback'), false) then return false; end if;
      if p ? 'amount' and not (jsonb_typeof(p -> 'amount') = 'number' and (p ->> 'amount')::numeric between 0 and 100000000) then return false; end if;
      if p ? 'releaseDate' and not coalesce(p ->> 'releaseDate' ~ '^\d{4}-\d{2}-\d{2}$', false) then return false; end if;
      if p ? 'forBenefitOf' and not coalesce(p ->> 'forBenefitOf' in ('buyer', 'seller', 'lender', 'other'), false) then return false; end if;
      if char_length(coalesce(p ->> 'payee', '')) > 120 or char_length(coalesce(p ->> 'memo', '')) > 200 or char_length(coalesce(p ->> 'releaseNote', '')) > 300 then return false; end if;
    end loop;
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.acct_on()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce((select enabled from private.features where name = 'accounting'), false) $function$

CREATE OR REPLACE FUNCTION private.acct_reader(d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.acct_on() and coalesce((select p.is_admin or (p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator')
      and coalesce((select r.allowed from public.role_module_access r where r.role = p.role and r.module = 'accounting'), false))
    from public.profiles p where p.id = private.effective_uid() and p.status = 'active'), false) and private.can_access_deal(d) $function$

CREATE OR REPLACE FUNCTION private.actor_is_super_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'Super admin' and p.is_admin and p.status = 'active')
$function$

CREATE OR REPLACE FUNCTION private.agent_answers_visible(t tasks)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select t.owner_profile_id = private.effective_uid() or private.is_manager() or private.is_admin() $function$

CREATE OR REPLACE FUNCTION private.agent_can_fill(p_task uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce((
    select private.deal_role(t.deal_id) in ('Buyer Agent', 'Listing Agent') and t.kind = 'form' and t.status <> 'cancelled' and t.owner_profile_id is not null
      and t.assigned_role in ('Client-Buyer', 'Client-Seller') and private.side_of(t.assigned_role) = private.side_of(private.deal_role(t.deal_id))
      and private.deal_role(t.deal_id) = any (tp.agent_roles) and not private.template_locked(tp.client_only, tp.fields)
      and exists (select 1 from public.deal_participants p where p.deal_id = t.deal_id and p.contact_id = private.my_contact_id() and p.role = private.deal_role(t.deal_id))
    from public.tasks t join public.task_templates tp on tp.id = t.template_id where t.id = p_task), false) $function$

CREATE OR REPLACE FUNCTION private.agent_fee_actor(d uuid, p_side text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_uid uuid := private.effective_uid(); v_roles text[];
begin
  if v_uid is null or not private.can_access_deal(d) then return null; end if;
  if private.can_run_deal(d) then return 'staff'; end if;
  v_roles := private.file_roles_of(v_uid, d);
  if (p_side = 'buyer' and 'Buyer Agent' = any (v_roles)) or (p_side = 'listing' and 'Listing Agent' = any (v_roles)) then return 'agent'; end if;
  if private.me_role() = 'Transaction Coordinator' and (
       exists (select 1 from public.deals x where x.id = d and x.tc_user_id = v_uid)
       or exists (select 1 from public.deal_participants p join public.contacts c on c.id = p.contact_id
                    join public.team_members ag on ag.profile_id = c.profile_id and ag.member_role = 'agent'
                    join public.team_members co on co.team_id = ag.team_id and co.member_role = 'coordinator' and co.profile_id = v_uid
                   where p.deal_id = d and p.role = case p_side when 'buyer' then 'Buyer Agent' else 'Listing Agent' end)) then
    return 'tc';
  end if;
  if private.is_staffish() and private.me_role() <> 'Transaction Coordinator' then return 'reader'; end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_default_payer(p_side text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$ select case p_side when 'buyer' then 'buyer' else 'seller' end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_json(f deal_agent_fees)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select case when f.id is null then null else jsonb_strip_nulls(jsonb_build_object(
    'side', f.side, 'kind', f.kind, 'slot', f.slot, 'basis', f.basis, 'percent', f.pct, 'amount', f.amount, 'payer', f.payer,
    'description', f.description, 'paidTo', f.paid_to,
    'base', f.base_amount,
    'additional', case when coalesce(f.additional_amount, 0) = 0 then null else f.additional_amount end,
    'splitBuyer', f.split_buyer, 'splitSeller', f.split_seller)) end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_label(p_kind text, p_slot integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case p_kind when 'commission' then 'Commission' when 'admin' then 'Admin fee' else 'Other fee ' || p_slot end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_ledger_shape(f accounting_fees)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select jsonb_build_object('description', f.description, 'payee', f.payee, 'amount', f.amount, 'paidBy', f.paid_by,
    'split', jsonb_build_object('buyer', f.split_buyer, 'seller', f.split_seller, 'lender', f.split_lender, 'other', f.split_other),
    'altaSection', f.alta_section, 'cdSection', f.cd_section) $function$

CREATE OR REPLACE FUNCTION private.agent_fee_ledger_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  r public.deal_agent_fees := case when tg_op = 'DELETE' then old else new end;
  v_key text := 'agent_fee:' || r.side || ':' || r.kind || ':' || r.slot;
  v_link public.deal_agent_fee_ledger; v_line public.accounting_fees; v_company text; v_side text; v_payer text;
  v_desc text; v_payee text; v_live boolean := tg_op <> 'DELETE' and r.amount > 0;
  v_buyer numeric; v_seller numeric;
begin
  select * into v_link from public.deal_agent_fee_ledger where deal_id = r.deal_id and preset_key = v_key;
  if v_link.fee_id is not null then select * into v_line from public.accounting_fees where id = v_link.fee_id; end if;
  if v_line.id is not null and private.agent_fee_ledger_shape(v_line) is distinct from v_link.posted then return null; end if;
  if not v_live then
    if v_line.id is not null and v_line.retired_at is null then update public.accounting_fees set retired_at = now() where id = v_line.id; end if;
    if v_line.id is not null then
      select * into v_line from public.accounting_fees where id = v_line.id;
      update public.deal_agent_fee_ledger set posted = private.agent_fee_ledger_shape(v_line), posted_at = now() where deal_id = r.deal_id and preset_key = v_key;
    end if;
    return null;
  end if;
  v_side := case r.side when 'buyer' then 'buyer''s agent' else 'listing agent' end;
  v_payer := coalesce(r.payer, private.agent_fee_default_payer(r.side));
  v_buyer := case when v_payer = 'buyer' then r.amount when v_payer = 'split' then coalesce(r.split_buyer, 0) else 0 end;
  v_seller := case when v_payer = 'seller' then r.amount when v_payer = 'split' then coalesce(r.split_seller, 0) else 0 end;
  if (select transaction_type from public.deals where id = r.deal_id) = 'Refinance' then return null; end if;
  select nullif(btrim(coalesce(c.company, '')), '') into v_company from public.deal_participants p join public.contacts c on c.id = p.contact_id
   where p.deal_id = r.deal_id and p.role = case r.side when 'buyer' then 'Buyer Agent' else 'Listing Agent' end order by p.created_at limit 1;
  v_desc := case r.kind when 'commission' then 'Real estate commission - ' || v_side || ' (' || trim(to_char(r.pct, 'FM999990.9999'), '.') || '%)'
                        when 'admin' then 'Admin fee - ' || v_side
                        else left(r.description, 170) || ' - ' || v_side end;
  v_payee := left(coalesce(case when r.kind = 'other' then r.paid_to end, v_company, initcap(v_side)), 120);
  if v_line.id is null then
    insert into public.accounting_fees (deal_id, kind, description, alta_section, cd_section, cd_line, payee, amount, paid_by,
        split_buyer, split_seller, split_lender, split_other, timing, note, preset_key)
      values (r.deal_id, 'charge', v_desc, 'commission', 'H', '', v_payee, r.amount, v_payer, v_buyer, v_seller, 0, 0, 'at',
        'From Agent fees on the file overview. Change it there; a change made here stops the automatic updates for this line.', v_key)
      returning * into v_line;
  else
    update public.accounting_fees set retired_at = null, description = v_desc, payee = v_payee, amount = r.amount, paid_by = v_payer,
        split_buyer = v_buyer, split_seller = v_seller, split_lender = 0, split_other = 0, alta_section = 'commission', cd_section = 'H'
      where id = v_line.id returning * into v_line;
  end if;
  insert into public.deal_agent_fee_ledger (deal_id, preset_key, fee_id, posted, posted_at)
    values (r.deal_id, v_key, v_line.id, private.agent_fee_ledger_shape(v_line), now())
    on conflict (deal_id, preset_key) do update set fee_id = excluded.fee_id, posted = excluded.posted, posted_at = excluded.posted_at;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_notify(p_deal uuid, p_side text, p_actor text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_uid uuid := private.effective_uid(); v_lines text[]; v_changed int; v_file text; v_name text; v_side text; v_title text; v_body text;
  v_ids uuid[]; v_agents uuid[];
begin
  if p_actor not in ('agent', 'tc', 'staff') then return; end if;
  select array_agg(private.agent_fee_label(l.kind, l.slot) || ': ' ||
           case when l.old_value is not distinct from l.new_value then 'confirmed ' || private.agent_fee_text(l.new_value)
                else private.agent_fee_text(l.old_value) || ' → ' || private.agent_fee_text(l.new_value) end order by l.id),
         count(*) filter (where l.old_value is distinct from l.new_value)
    into v_lines, v_changed
  from public.deal_agent_fee_log l
  where l.deal_id = p_deal and l.side = p_side and l.source = p_actor and l.changed_by is not distinct from v_uid and l.changed_at = now();
  if v_lines is null then return; end if;
  select file_number, array_remove(array[processor_id, preprocessor_user_id, tc_user_id], null) into v_file, v_ids from public.deals where id = p_deal;
  select coalesce(array_agg(distinct c.profile_id), '{}') into v_agents from public.deal_participants p join public.contacts c on c.id = p.contact_id
   where p.deal_id = p_deal and c.profile_id is not null and p.role = case p_side when 'buyer' then 'Buyer Agent' else 'Listing Agent' end;
  if p_actor = 'tc' then v_ids := v_ids || v_agents; end if;
  -- AF-4: a staff change to fees the agent (or TC) confirmed tells the agent only (old, new, reason, who). No re-approval.
  if p_actor = 'staff' then
    if v_changed = 0 or not (p_reason is not null or exists (select 1 from public.deal_agent_fees f where f.deal_id = p_deal and f.side = p_side and f.confirmed_at is not null)) then return; end if;
    v_ids := v_agents;
  end if;
  v_name := private.person_name(v_uid) || case when p_actor = 'tc' then ' (TC)' when p_actor = 'staff' then ' (CLA Title)' else '' end;
  v_side := case p_side when 'buyer' then 'buyer''s agent' else 'listing agent' end;
  v_title := v_name || case when v_changed = 0 then ' confirmed the ' || v_side || ' fees on ' else ' changed the ' || v_side || ' fees on ' end || coalesce(v_file, 'a file')
    || case when v_changed > 0 then ': ' || v_lines[1] || case when array_length(v_lines, 1) > 1 then ' (+' || (array_length(v_lines, 1) - 1) || ' more)' else '' end else '' end
    || case when p_actor = 'staff' and p_reason is not null then '. Reason: ' || p_reason else '' end;
  perform private.notify(v_ids, 'agent_fee', p_deal, v_title, '#/deals/' || p_deal);
  v_body := v_name || case when v_changed = 0 then ' confirmed ' else ' changed ' end || 'the ' || v_side || ' fees on file ' || coalesce(v_file, '') || E'.\n\n'
    || array_to_string(v_lines, E'\n') || case when p_reason is not null then E'\n\nReason: ' || p_reason else '' end
    || case when p_actor = 'staff' then E'\n\nYou don''t need to approve this change. If something is wrong, open the file in the portal and change your fees, or reply to your processor.' else '' end
    || E'\n\nOpen the file in the CLA Title portal to see the fees and their history.\n\nTEST PORTAL: queued only; never sent.';
  insert into public.outbox (channel, status, sent_at, to_profile_id, to_email, to_name, subject, body, deal_id, created_by, kind, sender_type)
  select 'email', 'queued', null, p.id, p.email, private.person_name(p.id), left('Agent fees ' || case when v_changed = 0 then 'confirmed' else 'changed' end || ' on ' || coalesce(v_file, 'a file'), 500),
         left(v_body, 4000), p_deal, v_uid, 'agent_fee', 'portal'
  from public.profiles p
  where p.id = any (v_ids) and p.id is distinct from v_uid and p.status = 'active' and coalesce(p.email, '') like '%@%';
end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_num(p text, p_label text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if p is null or btrim(p) = '' then return null; end if;
  return replace(replace(replace(btrim(p), ',', ''), '$', ''), '%', '')::numeric;
exception when others then
  raise exception '% must be a number.', p_label using errcode = 'P0001';
end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_price_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare f public.deal_agent_fees; v_sync record; v_reason text; v_basis text;
begin
  if new.purchase_price is not distinct from old.purchase_price or new.purchase_price is null or new.purchase_price <= 0 then return null; end if;
  v_reason := 'Sales price changed from ' || coalesce(to_char(old.purchase_price, 'FM$999,999,999,990.00'), 'blank') || ' to ' || to_char(new.purchase_price, 'FM$999,999,999,990.00');
  -- A typed base, or a Split with its own dollar amounts, stays until someone edits the panel.
  for f in select * from public.deal_agent_fees x where x.deal_id = new.id and x.kind = 'commission' and x.base_amount is null and x.payer is distinct from 'split' loop
    v_basis := case when f.basis = 'amount' and (f.amount - coalesce(f.additional_amount, 0)) > new.purchase_price then 'percent' else f.basis end;
    select * into v_sync from private.agent_fee_sync(new.purchase_price, v_basis, f.pct, f.amount, null, coalesce(f.additional_amount, 0));
    if v_sync.pct is distinct from f.pct or v_sync.amount is distinct from f.amount or v_basis is distinct from f.basis then
      update public.deal_agent_fees set pct = v_sync.pct, amount = v_sync.amount, basis = v_basis, updated_at = now() where id = f.id;
      insert into public.deal_agent_fee_log (deal_id, side, kind, slot, old_value, new_value, reason, source, changed_by)
        values (new.id, f.side, f.kind, f.slot, private.agent_fee_json(f),
                private.agent_fee_json(f) || jsonb_build_object('percent', v_sync.pct, 'amount', v_sync.amount, 'basis', v_basis), v_reason, 'system', private.effective_uid());
    end if;
  end loop;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_sync(p_price numeric, p_basis text, p_pct numeric, p_amount numeric, p_base numeric DEFAULT NULL::numeric, p_additional numeric DEFAULT 0, OUT pct numeric, OUT amount numeric)
 RETURNS record
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare v_base numeric; v_add numeric; v_from numeric;
begin
  v_add := coalesce(p_additional, 0);
  if v_add < 0 then raise exception 'Additional amount must be a dollar amount of 0 or more.' using errcode = 'P0001'; end if;
  if p_base is null and (p_price is null or p_price <= 0) then
    raise exception 'Add the sales price before entering a commission, so the %% and $ stay in step.' using errcode = 'P0001'; end if;
  v_base := coalesce(p_base, p_price);
  if v_base is null or v_base <= 0 then raise exception 'Commission base must be more than 0.' using errcode = 'P0001'; end if;
  if p_basis = 'percent' then
    if p_pct is null or p_pct < 0 or p_pct > 100 then raise exception 'Commission %% must be a number from 0 to 100.' using errcode = 'P0001'; end if;
    pct := round(p_pct, 8);
    amount := round(round(v_base * pct / 100, 2) + v_add, 2);
  elsif p_basis = 'amount' then
    if p_amount is null or p_amount < 0 then raise exception 'Commission $ must be a dollar amount of 0 or more.' using errcode = 'P0001'; end if;
    if p_amount < v_add then raise exception 'Commission amount must be at least the additional amount. The additional amount is added on top of the percent.' using errcode = 'P0001'; end if;
    v_from := round(p_amount - v_add, 2);
    if v_from > v_base then
      if v_add = 0 and p_base is null then raise exception 'The commission $ can''t be more than the sales price.' using errcode = 'P0001'; end if;
      raise exception 'The commission from the base can''t be more than the commission base.' using errcode = 'P0001';
    end if;
    amount := round(p_amount, 2);
    pct := round(v_from * 100 / v_base, 8);
  else
    raise exception 'Enter the commission as a %% or a $ amount.' using errcode = 'P0001';
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.agent_fee_text(v jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case when v is null then 'none'
    when v ->> 'kind' = 'commission' then trim(to_char((v ->> 'percent')::numeric, 'FM999990.9999'), '.') || '% / ' || to_char((v ->> 'amount')::numeric, 'FM$999,999,990.00')
    when v ->> 'kind' = 'other' then coalesce(v ->> 'description', 'Other fee') || ' ' || to_char((v ->> 'amount')::numeric, 'FM$999,999,990.00') || ' to ' || coalesce(v ->> 'paidTo', '')
    else to_char((v ->> 'amount')::numeric, 'FM$999,999,990.00') end
  || case when v ->> 'payer' is not null then ' (paid by ' || initcap(v ->> 'payer') || ')' else '' end $function$

CREATE OR REPLACE FUNCTION private.agent_invites_no_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin raise exception 'Invites are never deleted (Revoke retires them).' using errcode = '42501'; end $function$

CREATE OR REPLACE FUNCTION private.agent_person_ok(p jsonb, need_email boolean, need_phone boolean)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(trim(p->>'firstName'), '') <> '' and coalesce(trim(p->>'lastName'), '') <> ''
     and (case when coalesce(p->>'email', '') = '' then not need_email else (p->>'email') ~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' end)
     and (case when coalesce(p->>'phone', '') = '' then not need_phone else regexp_replace(p->>'phone', '\D', '', 'g') ~ '^\d{10}$' end) $function$

CREATE OR REPLACE FUNCTION private.agent_photo_visible(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce((storage.foldername(p_name))[1] = private.effective_uid()::text, false) or private.can_invite_agents()
    or exists (select 1 from public.my_agents() m join public.agent_profiles a on a.photo_path = p_name where m.photo_path = p_name) $function$

CREATE OR REPLACE FUNCTION private.agent_profile_write(pid uuid, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare cell text := coalesce(p ->> 'cellPhone', ''); off text := coalesce(p ->> 'officePhone', ''); bm int := nullif(p ->> 'birthMonth', '')::int; bd int := nullif(p ->> 'birthDay', '')::int;
begin
  if p ? 'cellPhone' and length(regexp_replace(cell, '\D', '', 'g')) <> 10 then raise exception 'Cell phone must be a 10-digit phone number.' using errcode = '22023'; end if;
  if off <> '' and length(regexp_replace(off, '\D', '', 'g')) <> 10 then raise exception 'Office phone must be a 10-digit phone number.' using errcode = '22023'; end if;
  if (p ? 'birthMonth' or p ? 'birthDay') and not private.month_day_ok(bm, bd) then raise exception 'Date of birth must be a real month and day.' using errcode = '22023'; end if;
  insert into public.agent_profiles (profile_id) values (pid) on conflict (profile_id) do nothing;
  update public.agent_profiles set cell_phone = case when p ? 'cellPhone' then cell else cell_phone end, office_phone = case when p ? 'officePhone' then off else office_phone end,
    brokerage = coalesce(p ->> 'brokerage', brokerage), license_number = coalesce(p ->> 'licenseNumber', license_number), street = coalesce(p ->> 'street', street), city = coalesce(p ->> 'city', city),
    state = upper(coalesce(p ->> 'state', state)), zip = coalesce(p ->> 'zip', zip), other_contact = coalesce(p ->> 'otherContact', other_contact),
    photo_path = case when p ? 'photoPath' then nullif(p ->> 'photoPath', '') else photo_path end, photo_shape = coalesce(p ->> 'photoShape', photo_shape), updated_at = now() where profile_id = pid;
  if p ? 'birthMonth' or p ? 'birthDay' then insert into public.agent_private (profile_id, birth_month, birth_day, updated_by) values (pid, bm, bd, pid)
    on conflict (profile_id) do update set birth_month = excluded.birth_month, birth_day = excluded.birth_day, updated_at = now(), updated_by = excluded.updated_by; end if;
end $function$

CREATE OR REPLACE FUNCTION private.agent_task_defs()
 RETURNS TABLE(code text, title text, about text, due_days integer)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  values ('agent_client_contacts', 'Confirm Client Contact Information', 'Tell us which of the clients on this order you represent and confirm how to reach them (and their spouse, if married). Add anyone we are missing.', 3),
         ('agent_transaction_info', 'Confirm Your Transaction Information', 'Check the closing date and price we have, give your commission split, any fees or credits for the settlement statement, the earnest money, and the people on your team.', 3),
         ('agent_home_warranty', 'Confirm Home Warranty Information', 'Let us know whether you or someone else will be purchasing a home warranty for this property.', 5) $function$

CREATE OR REPLACE FUNCTION private.agent_validate(p_code text, a jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare c jsonb; begin
  if p_code = 'agent_client_contacts' then
    for c in select * from jsonb_array_elements(coalesce(a->'clients', '[]')) loop
      if coalesce(c->>'represent', '') not in ('Yes', 'No') then raise exception 'Do you represent each client? Choose Yes or No.' using errcode = 'P0001'; end if;
      if c->>'represent' = 'Yes' then
        if not private.agent_person_ok(c, true, true) then raise exception 'Client first name, last name, email and 10-digit phone are required.' using errcode = 'P0001'; end if;
        if coalesce(c->>'maritalStatus', '') not in ('Single', 'Married', 'Divorced', 'Widowed') then raise exception 'Choose a marital status.' using errcode = 'P0001'; end if;
        if c->>'maritalStatus' = 'Married' and not private.agent_person_ok(coalesce(c->'spouse', '{}'), false, false) then raise exception 'Spouse first and last name are required.' using errcode = 'P0001'; end if;
      end if; end loop;
    for c in select * from jsonb_array_elements(coalesce(a->'added', '[]')) loop
      if not private.agent_person_ok(c, true, false) then raise exception 'An added client needs a first name, last name and email.' using errcode = 'P0001'; end if; end loop;
  elsif p_code = 'agent_transaction_info' then
    if coalesce(a->>'closingDate', '') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Estimated closing date is required.' using errcode = 'P0001'; end if;
    perform (a->>'closingDate')::date;
    if coalesce(a->>'purchasePrice', '') !~ '^\d+(\.\d+)?$' then raise exception 'Purchase price is required.' using errcode = 'P0001'; end if;
    if coalesce(a->>'emdAmount', '') !~ '^\d+(\.\d+)?$' then raise exception 'Earnest deposit amount is required (0 if none).' using errcode = 'P0001'; end if;
    if coalesce(a->>'holdingEmd', '') not in ('Yes', 'No') then raise exception 'Are you holding earnest money given to you by the buyer?' using errcode = 'P0001'; end if;
    if jsonb_array_length(coalesce(a->'commissions', '[]')) = 0 then raise exception 'Add your commission (percent or amount).' using errcode = 'P0001'; end if;
    for c in select * from jsonb_array_elements(coalesce(a->'fees', '[]')) loop
      if coalesce(trim(c->>'name'), '') = '' or coalesce(c->>'type', '') not in ('Fee', 'Credit') or coalesce(c->>'paidBy', '') not in ('Buyer', 'Seller') or coalesce(c->>'amount', '') !~ '^\d+(\.\d+)?$' then
        raise exception 'Each fee or credit needs a name, Fee / Credit, an amount and who pays it.' using errcode = 'P0001'; end if; end loop;
    for c in select * from jsonb_array_elements(coalesce(a->'team', '[]')) loop
      if not private.agent_person_ok(c, true, false) then raise exception 'Each team member needs a first name, last name and email.' using errcode = 'P0001'; end if; end loop;
  elsif p_code = 'agent_home_warranty' then
    if coalesce(a->>'willPurchase', '') not in ('Yes', 'No') then raise exception 'Will you or someone else be purchasing a home warranty? Choose Yes or No.' using errcode = 'P0001'; end if;
    if a->>'willPurchase' = 'Yes' and coalesce(a->>'purchaser', '') not in ('Me', 'Someone else') then raise exception 'Who is purchasing it?' using errcode = 'P0001'; end if;
  else raise exception 'Unknown agent task' using errcode = 'P0001'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.apply_processor_party(p_deal uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_proc uuid; cid uuid;
begin
  perform set_config('cla.processor_sync', 'on', true);
  select processor_id into v_proc from public.deals where id = p_deal;
  if v_proc is null then
    delete from public.deal_participants dp
     using public.contacts c
     where dp.deal_id = p_deal and dp.role = 'Processor' and c.id = dp.contact_id and c.profile_id is not null;
  else
    cid := private.processor_party_contact(v_proc);
    delete from public.deal_participants dp
     using public.contacts c
     where dp.deal_id = p_deal and dp.role = 'Processor' and dp.contact_id is distinct from cid
       and c.id = dp.contact_id and c.profile_id is not null;
    insert into public.deal_participants (id, deal_id, contact_id, role)
    select gen_random_uuid(), p_deal, cid, 'Processor'
     where not exists (
       select 1 from public.deal_participants
        where deal_id = p_deal and contact_id = cid and role = 'Processor');
  end if;
  perform set_config('cla.processor_sync', 'off', true);
end $function$

CREATE OR REPLACE FUNCTION private.assert_invite_service()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare jwt_role text := coalesce(auth.jwt() ->> 'role', '');
begin
  if jwt_role is distinct from 'service_role' and not (jwt_role = '' and session_user in ('postgres', 'supabase_admin')) then
    raise exception 'This invite link is not valid or has expired.' using errcode = '42501';
  end if;
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claim.role', 'service_role', true);
  perform set_config('request.jwt.claims', '{"role":"service_role"}', true);
end $function$

CREATE OR REPLACE FUNCTION private.board_owner_names(p_deals uuid[])
 RETURNS TABLE(deal_id uuid, participant_id uuid, owner_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET jit TO 'off'
AS $function$
begin
  if (select private.is_staffish()) then
    return query
    with g as materialized (
      select * from private.reader_gate()
    ),
    ids as (
      select distinct u.id
      from unnest(coalesce(p_deals, '{}'::uuid[])) u(id)
      where u.id is not null
    )
    select dp.deal_id, dp.id, trim(c.first_name || ' ' || c.last_name)
    from ids
    cross join g
    join public.deal_participants dp on dp.deal_id = ids.id
    join public.contacts c on c.id = dp.contact_id
    where dp.id is not null
      and private.reader_can_deal(ids.id, g.uid, g.role, g.is_admin, g.contact_id, g.active);
    return;
  end if;

  return query
  with ids as (
    select distinct u.id
    from unnest(coalesce(p_deals, '{}'::uuid[])) u(id)
    where u.id is not null
  ),
  flags as (
    select i.id as deal_id,
           private.can_access_deal(i.id) as can_access,
           private.deal_role(i.id) as deal_role,
           private.is_pure_buyer(i.id) as pure_buyer,
           private.is_pure_seller(i.id) as pure_seller
    from ids i
  )
  select dp.deal_id, dp.id, trim(c.first_name || ' ' || c.last_name)
  from flags f
  join public.deal_participants dp on dp.deal_id = f.deal_id
  join public.contacts c on c.id = dp.contact_id
  where f.can_access
    and dp.id is not null
    and not (f.deal_role in ('Client-Buyer', 'Client-Seller') and dp.role like 'Client-%' and dp.role <> f.deal_role)
    and not (dp.role = 'Listing Agent' and f.pure_buyer)
    and not (dp.role = 'Buyer Agent' and f.pure_seller);
end
$function$

CREATE OR REPLACE FUNCTION private.bootstrap_first_admin(p_user uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare em text; fn text; ln text;
begin
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'Bootstrap is operator-only.' using errcode = '42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(8742100197);
  if p_user is null then raise exception 'Pass the auth.users id to bootstrap. No owner is assumed.' using errcode = '22023'; end if;
  if exists (select 1 from public.profiles p where p.role = 'Super admin' and p.status <> 'removed') then
    raise exception 'A Super admin already exists. Bootstrap is closed.' using errcode = '42501'; end if;
  if exists (select 1 from public.profiles p where p.id = p_user) then
    raise exception 'That user already has a profile.' using errcode = '42501'; end if;
  select pg_catalog.lower(pg_catalog.btrim(coalesce(u.email, ''::text))),
         coalesce(nullif(pg_catalog.btrim(u.raw_app_meta_data->>'first_name'), ''::text), 'Administrator'::text),
         coalesce(pg_catalog.btrim(u.raw_app_meta_data->>'last_name'), ''::text)
    into em, fn, ln from auth.users u where u.id = p_user;
  if em is null or em = '' then raise exception 'That auth user does not exist or has no email. Create the user in the dashboard first. No email is sent.' using errcode = '22023'; end if;
  perform pg_catalog.set_config('cla.bootstrap_admin', 'on', true);
  insert into public.profiles (id, email, first_name, last_name, phone, role, status, is_admin)
  values (p_user, em, pg_catalog.left(fn, 80), pg_catalog.left(ln, 80), '', 'Super admin', 'active', true);
  perform pg_catalog.set_config('cla.bootstrap_admin', 'off', true);
  perform private.log_activity(null, 'auth.bootstrap_admin', 'user', p_user, 'Operator bootstrap of the first Super admin. No email was sent.');
  return p_user;
end $function$

CREATE OR REPLACE FUNCTION private.business_source_label(p_source text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case split_part(btrim(coalesce(p_source, '')), ':', 1)
    when 'buyer' then 'Buyer'
    when 'seller' then 'Seller'
    when 'buyer_agent' then 'Buyer''s agent'
    when 'listing_agent' then 'Listing agent'
    when 'lender' then 'Lender'
    when 'homeowner' then 'Homeowner'
    else private.crm_option_label('leadSource', btrim(coalesce(p_source, '')))
  end
  || case
    when split_part(btrim(coalesce(p_source, '')), ':', 1) in ('buyer', 'seller', 'buyer_agent', 'listing_agent', 'lender')
     and split_part(btrim(coalesce(p_source, '')), ':', 2) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then coalesce(' — ' || nullif((select btrim(c.first_name || ' ' || c.last_name) from public.contacts c where c.id = split_part(btrim(p_source), ':', 2)::uuid), ''), '')
    else ''
  end $function$

CREATE OR REPLACE FUNCTION private.buyer_agent_blocked(kind text, doc_name text, doc_type text, wire boolean)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(wire, false)
    or coalesce(kind, '') in ('curative_lien', 'entity_document', 'prelim_cd', 'title_package', 'cpl', 'lien_certificate')
    or coalesce(doc_name, '') ~* 'payoff|cash[[:space:]-]*to[[:space:]-]*close|wire[[:space:]._-]*(instruction|info|details)'
    or coalesce(doc_type, '') ~* 'payoff|cash[[:space:]-]*to[[:space:]-]*close' $function$

CREATE OR REPLACE FUNCTION private.buyer_doc_ok(pid uuid, doc uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select exists (select 1 from public.documents d where d.id = doc and (
    d.uploaded_by = pid or private.person_side(d.uploaded_by, d.deal_id) = 'staff'
    or exists (select 1 from public.signature_requests r join public.signature_signers s on s.request_id = r.id where r.document_id = d.id and s.profile_id = pid))) $function$

CREATE OR REPLACE FUNCTION private.buyer_ssn_key()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
