CREATE OR REPLACE FUNCTION private.can_access_deal(d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.me_role() is not null and (
    private.is_admin() or private.me_role() in ('Processor', 'Sales Team', 'Transaction Coordinator')
    or (private.me_role() = 'Preprocessor' and exists (select 1 from public.deals x where x.id = d and x.preprocessor_user_id = private.effective_uid()))
    or (private.me_role() in ('Sales Person', 'Sales Team') and exists (select 1 from public.deal_sales_people s where s.deal_id = d and s.sales_id = private.effective_uid()))
    or exists (select 1 from public.deal_participants p where p.deal_id = d and p.contact_id = private.my_contact_id())) $function$

CREATE OR REPLACE FUNCTION private.can_invite_agents()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(private.is_admin() or private.me_role() in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Admin', 'Super admin'), false) $function$

CREATE OR REPLACE FUNCTION private.can_manage_closing_locations()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(private.me_role() in ('Processor', 'Preprocessor', 'Transaction Coordinator'), false) or private.is_admin() $function$

CREATE OR REPLACE FUNCTION private.can_message(pid uuid, d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.is_staffish() or private.person_side(pid, d) = 'staff' or (private.my_side(d) in ('buyer', 'seller') and private.person_side(pid, d) = private.my_side(d)) $function$

CREATE OR REPLACE FUNCTION private.can_read_closing_location(d uuid, p uuid, r text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select (private.is_staffish() and private.can_access_deal(d)) or private.owns_participant(p)
    or (private.can_access_deal(d) and ((r = 'Client-Buyer' and 'Buyer Agent' = any (private.file_roles_of(private.effective_uid(), d)))
                                     or (r = 'Client-Seller' and 'Listing Agent' = any (private.file_roles_of(private.effective_uid(), d))))) $function$

CREATE OR REPLACE FUNCTION private.can_run_deal(d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select (not private.is_preprocessor() and private.is_processor()) or (private.is_preprocessor() and exists (select 1 from public.deals x where x.id = d and x.preprocessor_user_id = private.effective_uid())) $function$

CREATE OR REPLACE FUNCTION private.can_write_closing_location(d uuid, p uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.owns_participant(p) or (private.can_manage_closing_locations() and private.can_access_deal(d))
    or private.is_side_agent(d, (select role from public.deal_participants where id = p)) $function$

CREATE OR REPLACE FUNCTION private.check_slots(p_slots timestamp without time zone[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if p_slots is null or cardinality(p_slots) not between 1 and 5 then raise exception 'Offer between 1 and 5 closing times'; end if;
  if (select count(distinct s) from unnest(p_slots) s) <> cardinality(p_slots) or array_position(p_slots, null) is not null then raise exception 'Each closing time must be different'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.client_sales_reps_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare c public.profiles; s public.profiles;
begin
  select * into c from public.profiles where id = new.client_id;
  select * into s from public.profiles where id = new.sales_id;
  if c.id is null or c.role <> 'Outside user' or c.status = 'removed' then
    raise exception 'Only an outside user (a client) can be linked to salespeople.' using errcode = 'P0001'; end if;
  if s.id is null or s.role not in ('Sales Person', 'Sales Team') then
    raise exception 'Only a Sales Person or Sales Team user can be linked to a client.' using errcode = 'P0001'; end if;
  if s.status <> 'active' then raise exception 'Only an active salesperson can be linked.' using errcode = 'P0001'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.closest_office(p_state text, p_zip text, p_lat double precision, p_lng double precision)
 RETURNS TABLE(office_id text, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  plat double precision := p_lat;
  plng double precision := p_lng;
  oid text;
  why text;
begin
  if plat is null or plng is null or plat < -90 or plat > 90 or plng < -180 or plng > 180 then
    plat := null; plng := null;
    select c.latitude, c.longitude into plat, plng
      from public.zip_centroids c where c.zip = left(btrim(coalesce(p_zip, '')), 5);
  end if;
  if plat is not null and plng is not null then
    select o.id into oid
      from public.offices o
      left join public.zip_centroids c on c.zip = left(btrim(o.zip), 5)
     where o.active
       and coalesce(o.latitude, c.latitude) is not null
       and coalesce(o.longitude, c.longitude) is not null
     order by private.haversine_miles(plat, plng, coalesce(o.latitude, c.latitude), coalesce(o.longitude, c.longitude)),
              o.sort_order, o.name
     limit 1;
    if oid is not null then why := 'distance'; end if;
  end if;
  if oid is null then
    select o.id into oid
      from public.offices o
     where o.active and o.state = upper(btrim(coalesce(p_state, '')))
     order by o.is_main_office_for_state desc, o.sort_order, o.name
     limit 1;
    if oid is not null then why := 'state'; end if;
  end if;
  if oid is null then
    select o.id into oid
      from public.offices o
     where o.active and o.is_main_office_for_state
     order by o.sort_order, o.name
     limit 1;
    if oid is null then
      select o.id into oid from public.offices o where o.active order by o.sort_order, o.name limit 1;
    end if;
    if oid is not null then why := 'main'; end if;
  end if;
  if oid is null then
    return query select null::text, 'none'::text;
    return;
  end if;
  return query select oid, why;
end;
$function$

CREATE OR REPLACE FUNCTION private.closing_location_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare dp public.deal_participants; prop text;
begin
  select * into dp from public.deal_participants where id = new.participant_id;
  if not found or dp.role not in ('Client-Buyer', 'Client-Seller') then raise exception 'Only a buyer or seller on the order answers this.' using errcode = 'P0001'; end if;
  if tg_op = 'UPDATE' and (new.participant_id <> old.participant_id or new.deal_id <> old.deal_id) then raise exception 'The party cannot change.' using errcode = 'P0001'; end if;
  new.deal_id := dp.deal_id; new.party_role := dp.role;
  new.closing_location_state := upper(nullif(btrim(coalesce(new.closing_location_state, '')), ''));
  new.closing_location_country := upper(nullif(btrim(coalesce(new.closing_location_country, '')), ''));
  select state into prop from public.deals where id = dp.deal_id;
  if new.in_state_at_closing = false and new.closing_location_state = prop then
    raise exception '% is the property''s state: answer Yes instead.', prop using errcode = 'P0001'; end if;
  if (tg_op = 'INSERT' and new.signing_method <> 'undecided') or (tg_op = 'UPDATE' and new.signing_method <> old.signing_method) then
    if not private.can_manage_closing_locations() and private.effective_uid() is not null then raise exception 'Only CLA Title sets the signing method.' using errcode = '42501'; end if; end if;
  if tg_op = 'INSERT' then new.created_at := now();
    if new.in_state_at_closing is not null then new.answered_at := now(); new.answered_by := private.effective_uid(); else new.answered_at := null; new.answered_by := null; end if;
  elsif (new.in_state_at_closing, new.closing_location_state, new.closing_location_country) is distinct from (old.in_state_at_closing, old.closing_location_state, old.closing_location_country) then
    new.answered_at := now(); new.answered_by := private.effective_uid();
  else new.answered_at := old.answered_at; new.answered_by := old.answered_by; end if;
  new.updated_at := now(); new.updated_by := coalesce(private.effective_uid(), new.updated_by);
  return new; end $function$

CREATE OR REPLACE FUNCTION private.closing_location_remind_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin perform private.remind_closing_locations(new.deal_id); return new; end $function$

CREATE OR REPLACE FUNCTION private.closing_office_for(p_deal uuid, p_location text, p_office text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare s text; c text; r text; o public.offices;
begin
  if p_location is distinct from 'CLA Title office' then
    if nullif(btrim(coalesce(p_office, '')), '') is not null then raise exception 'Only a CLA Title office closing names an office.' using errcode = 'P0001'; end if;
    return null; end if;
  if nullif(btrim(coalesce(p_office, '')), '') is not null then
    select * into o from public.offices where id = p_office;
    if not found then raise exception 'Pick one of the CLA Title offices.' using errcode = 'P0001'; end if;
    if not o.active then raise exception '% is retired: pick another office.', o.name using errcode = 'P0001'; end if;
    return p_office; end if;
  select d.state, d.county into s, c from public.deals d where d.id = p_deal;
  select n.office_id into r from private.nearest_cla_office(s, c) n; return r;
end $function$

CREATE OR REPLACE FUNCTION private.closing_place(p_location text, p_office text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce((select name from public.offices where id = p_office and p_location = 'CLA Title office'), p_location) $function$

CREATE OR REPLACE FUNCTION private.commission_task_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.template_code = 'commissions'
     and nullif(btrim(coalesce(new.form_data ->> 'commission_amount', '')), '') is not null
     and (tg_op = 'INSERT' or (new.form_data ->> 'commission_amount') is distinct from (old.form_data ->> 'commission_amount')) then
    raise exception 'Commissions are now kept in the Agent fees box on the file overview. Reload the page and enter it there. Nothing was saved.'
      using errcode = 'P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.company_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'Companies are never deleted.' using errcode = 'P0001'; end if;
  if tg_op = 'INSERT' then new.created_by := private.effective_uid(); new.created_at := now(); end if;
  if tg_op = 'UPDATE' and (new.created_by is distinct from old.created_by or new.created_at <> old.created_at or new.company_type <> old.company_type) then
    raise exception 'Who created a company, and its type, never change.' using errcode = 'P0001'; end if;
  new.updated_by := private.effective_uid(); new.updated_at := now(); return new;
end $function$

CREATE OR REPLACE FUNCTION private.contact_info_visible(c uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.is_staffish() or c = private.my_contact_id() or exists (select 1 from public.deal_participants p where p.contact_id = c and private.participant_visible(p.deal_id, p.role)
      and (private.side_of(p.role) is null or private.side_of(p.role) = private.my_side(p.deal_id))) $function$

CREATE OR REPLACE FUNCTION private.contact_type_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.contact_type is not null and exists (select 1 from public.profiles p where p.id = new.profile_id and p.role <> 'Outside user' and p.status <> 'removed') then
    raise exception 'CLA staff have no contact type.' using errcode = 'P0001'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.contact_visible(c uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.is_processor() or private.is_admin() or c = private.my_contact_id()
      or exists (select 1 from public.deal_participants p where p.contact_id = c and private.participant_visible(p.deal_id, p.role)
                 and (private.is_staffish() or private.side_of(p.role) is null or private.side_of(p.role) = private.my_side(p.deal_id))) $function$

CREATE OR REPLACE FUNCTION private.contacts_crm_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if (new.crm_owner_id, new.account_id, new.crm_stage, new.last_contacted_on, new.tags, new.crm_notes, new.crm_lead_id, new.crm_archived_at, new.role_in_company, new.title, new.mobile, new.assistant,
      new.asst_phone, new.agent_split, new.license_no, new.sales_volume_last_year, new.deals_closed_last_year, new.zillow_url, new.crm_street, new.crm_city, new.crm_state, new.crm_zip, new.crm_county,
      new.links, new.lead_source, new.relationship_status, new.custom)
     is distinct from (old.crm_owner_id, old.account_id, old.crm_stage, old.last_contacted_on, old.tags, old.crm_notes, old.crm_lead_id, old.crm_archived_at, old.role_in_company, old.title, old.mobile, old.assistant,
      old.asst_phone, old.agent_split, old.license_no, old.sales_volume_last_year, old.deals_closed_last_year, old.zillow_url, old.crm_street, old.crm_city, old.crm_state, old.crm_zip, old.crm_county,
      old.links, old.lead_source, old.relationship_status, old.custom) then
    if private.effective_uid() is not null and not private.crm_editor() then raise exception 'You cannot change CRM details.' using errcode = '42501'; end if;
    if new.crm_owner_id is distinct from old.crm_owner_id then new.crm_owner_id := private.crm_owner_check(new.crm_owner_id, old.crm_owner_id, false); end if;
    if new.last_contacted_on > private.office_today() then raise exception 'Last contacted cannot be in the future.' using errcode = 'P0001'; end if;
    if private.effective_uid() is not null and old.relationship_status is not null then   -- a CRM client keeps the required fields (CRM Settings)
      if new.relationship_status is null and private.crm_required('relationshipStatus') then raise exception 'Relationship Status is required.' using errcode = 'P0001'; end if;
      if new.role_in_company = '' and old.role_in_company <> '' and private.crm_required('roleInCompany') then raise exception 'Role in Company is required.' using errcode = 'P0001'; end if;
      if new.crm_state = '' and old.crm_state <> '' and private.crm_required('state') then raise exception 'State is required.' using errcode = 'P0001'; end if; end if;
  end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.cpl_prices_no_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin if tg_op = 'DELETE' then raise exception 'CPL prices are retired, never deleted.' using errcode = 'P0001'; end if; return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_account_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare d public.crm_accounts;
begin
  -- State: required for every write by a signed-in user (the app, CRM functions such as convert); owner-run maintenance with no caller is exempt
  if private.effective_uid() is not null and (tg_op = 'INSERT' or new.state is distinct from old.state or new.name is distinct from old.name) then
    if coalesce(new.state, '') = '' then raise exception 'State is required: pick a US state (or DC).' using errcode = '23514'; end if; end if;
  if tg_op = 'INSERT' or private.crm_company_key(new.name) <> private.crm_company_key(old.name) then
    select * into d from public.crm_accounts a where a.id <> new.id and private.crm_company_key(a.name) = private.crm_company_key(new.name) order by a.archived_at nulls first limit 1;
    if d.id is not null then
      raise exception 'Already in the CRM: % (%)%. Duplicates are not allowed.', d.name, coalesce(nullif(d.state, ''), 'no state'), case when d.archived_at is not null then ' (archived: restore it instead)' else '' end
        using errcode = '23505', detail = 'crm_account:' || d.id::text; end if; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_account_visible(p_account uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and exists (select 1 from public.crm_accounts a where a.id = p_account)
    and (private.crm_owner_ok((select owner_id from public.crm_accounts where id = p_account))
      or exists (select 1 from public.contacts c where c.account_id = p_account and private.crm_contact_visible(c.id))) $function$

CREATE OR REPLACE FUNCTION private.crm_alias_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'An alias is never deleted; retire it instead.' using errcode = 'P0001'; end if;
  if tg_op = 'UPDATE' and (new.user_id, new.email) is distinct from (old.user_id, old.email) then raise exception 'Add a new alias instead of changing one.' using errcode = 'P0001'; end if;
  if tg_op = 'INSERT' and (select count(*) from public.crm_email_aliases where user_id = new.user_id and retired_at is null) >= 5 then raise exception 'At most 5 aliases.' using errcode = 'P0001'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_all()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and coalesce((select p.is_admin or (p.role in ('Processor', 'Preprocessor')
      and coalesce((select r.allowed from public.role_module_access r where r.role = p.role and r.module = 'crm'), false))
    from public.profiles p where p.id = private.effective_uid() and p.status = 'active'), false) $function$

CREATE OR REPLACE FUNCTION private.crm_assignee_check(p_new uuid, p_old uuid, p_insert boolean, p_label text DEFAULT 'task owner'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if p_insert and p_new is null then p_new := private.effective_uid(); end if;
  if p_new is null then raise exception 'Pick a %.', p_label using errcode = 'P0001'; end if;
  if p_new is distinct from p_old and coalesce(current_setting('crm.spawn', true), '') <> '1' then
    if not exists (select 1 from public.profiles where id = p_new and status = 'active' and role in ('Sales Person', 'Sales Team', 'Admin', 'Super admin')) then
      raise exception 'The % must be an active Sales Person, Sales Team or Admin user.', p_label using errcode = 'P0001'; end if;
    if private.effective_uid() is not null and p_new <> private.effective_uid() and not private.is_admin() and coalesce(private.me_role() = 'Sales Person', false) then
      raise exception 'A Sales Person can only pick themselves as the %.', p_label using errcode = 'P0001'; end if; end if;
  return p_new; end $function$

CREATE OR REPLACE FUNCTION private.crm_autonumber_backfill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare tbl text := case new.entity when 'lead' then 'crm_leads' when 'contact' then 'contacts' when 'account' then 'crm_accounts' else 'crm_opportunities' end; m int; rid uuid; claims text;
begin
  if new.type <> 'autonumber' then return null; end if;
  m := coalesce((new.config ->> 'next')::int, 1); claims := current_setting('request.jwt.claims', true);
  perform set_config('crm.spawn', '1', true); perform set_config('request.jwt.claims', '', true);   -- system numbering: not a user edit (converted leads are numbered too)
  for rid in execute format('select id from public.%I where not (coalesce(custom, ''{}'') ? $1) order by created_at, id', tbl) using new.id::text loop
    execute format('update public.%I set custom = jsonb_set(coalesce(custom, ''{}''), array[$1], to_jsonb($2::text)) where id = $3', tbl) using new.id::text, coalesce(new.config ->> 'prefix', '') || m || coalesce(new.config ->> 'suffix', ''), rid;
    m := m + 1; end loop;
  perform set_config('crm.spawn', '', true); perform set_config('request.jwt.claims', coalesce(claims, ''), true);
  update public.crm_custom_fields set config = jsonb_set(config, '{next}', to_jsonb(m)) where id = new.id;
  return null; end $function$

CREATE OR REPLACE FUNCTION private.crm_call_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_new boolean := tg_op = 'INSERT';
begin
  if new.kind <> 'call' then return new; end if;
  -- older callers (the Nov 3 b quick log) send no call_mode: a log of a call that happened
  if new.call_mode is null then new.call_mode := 'logged'; end if;
  if new.call_status is null then new.call_status := case when new.call_mode = 'scheduled' then 'Scheduled' else 'Completed' end; end if;
  if new.call_duration_sec is null and new.call_duration is not null then new.call_duration_sec := new.call_duration * 60; end if;
  if new.call_type = 'Missed' and (v_new or new.call_type is distinct from old.call_type) and new.call_mode = 'scheduled' then
    raise exception 'Pick a call type (Outbound or Inbound).' using errcode = '23514'; end if;
  if not v_new then
    if (new.call_mode, new.entity, new.entity_id) is distinct from (old.call_mode, old.entity, old.entity_id) then raise exception 'A call cannot change its kind or its Call To record.' using errcode = 'P0001'; end if;
    if old.call_status = 'Completed' and new.call_status = 'Scheduled' then raise exception 'This call is already completed.' using errcode = 'P0001'; end if;
  end if;
  if new.call_mode = 'scheduled' then
    if v_new then
      if new.entity not in ('lead', 'contact') then raise exception 'Call To must be a client or a lead.' using errcode = '23514'; end if;
      if new.call_status <> 'Scheduled' then raise exception 'A scheduled call starts as Scheduled.' using errcode = '23514'; end if;
      if new.call_type is null then new.call_type := 'Outbound'; end if;
      if new.call_start is null then raise exception 'Call Start Time is required.' using errcode = '23514'; end if;
      new.occurred_on := least(coalesce(new.occurred_on, private.office_today()), private.office_today());
    end if;
    if new.call_status = 'Completed' and (v_new or old.call_status = 'Scheduled') then   -- Mark as Completed -> Complete
      if coalesce(new.call_duration_sec, 0) <= 0 then raise exception 'Call duration cannot be zero' using errcode = '23514'; end if;
      new.completed_at := now(); new.done_at := now(); new.occurred_on := least(coalesce(new.call_start::date, private.office_today()), private.office_today()); end if;
  else
    -- a logged call: never in the future (5 minutes clock slack); a NEW-style log (it carries seconds) needs a duration above zero
    if new.call_start is not null and (v_new or new.call_start is distinct from old.call_start) and new.call_start > now() + interval '5 minutes' then
      raise exception 'Call Start Time cannot be in the future.' using errcode = '23514'; end if;
    if v_new and new.call_duration_sec is not null and new.call_duration is null and new.call_duration_sec <= 0 then
      raise exception 'Please provide a valid call start time and duration.' using errcode = '23514'; end if;
    if new.call_start is not null and v_new then new.occurred_on := least(new.call_start::date, private.office_today()); end if;
    new.call_reminder := null; new.call_reminder_at := null;
    if v_new then new.completed_at := coalesce(new.completed_at, now()); end if;
  end if;
  if new.call_duration_sec is not null then new.call_duration := least(1440, ceil(new.call_duration_sec / 60.0)::int); end if;
  new.call_reminder_at := case when new.call_reminder is not null and new.call_start is not null and new.call_status = 'Scheduled' then new.call_start - make_interval(mins => new.call_reminder) end;
  -- Call Owner: the task-owner rule (active Sales Person / Sales Team / Admin; a Sales Person only themselves)
  if private.effective_uid() is not null and (v_new or new.owner_id is distinct from old.owner_id) then
    new.owner_id := private.crm_assignee_check(new.owner_id, case when v_new then null else old.owner_id end, v_new, 'call owner'); end if;
  -- Related To: a record (or order) the caller may see
  if new.related_id is not null and private.effective_uid() is not null and (v_new or (new.related_entity, new.related_id) is distinct from (old.related_entity, old.related_id)) then
    if not (case when new.related_entity = 'deal' then private.can_access_deal(new.related_id) else private.crm_entity_visible(new.related_entity, new.related_id) end) then
      raise exception 'Related To record not found.' using errcode = 'P0002'; end if; end if;
  -- Outbound Call Outcome: from the pick list (blank = -None-); inbound calls keep no outcome
  if coalesce(new.call_type, '') <> 'Outbound' then new.call_outcome := ''; new.reason_not_interested := ''; new.call_notes := ''; end if;
  perform private.crm_list_check('callOutcome', new.call_outcome, case when v_new then null else old.call_outcome end, null, true);
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_carry_custom()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare lf record; t record; v jsonb; c jsonb; lab text; ov text;
begin
  if new.converted_contact_id is null or old.converted_contact_id is not null then return null; end if;
  select custom into c from public.contacts where id = new.converted_contact_id; c := coalesce(c, '{}');
  for lf in select * from public.crm_custom_fields where entity = 'lead' and archived_at is null loop
    v := new.custom -> lf.id::text; if v is null then continue; end if;
    select * into t from public.crm_custom_fields where entity = 'contact' and archived_at is null and lower(label) = lower(lf.label) and type = lf.type;
    if t.id is null or c ? t.id::text then continue; end if;
    if lf.type = 'dropdown' then lab := private.crm_option_label('cf:' || lf.id::text, v #>> '{}');
      select value into ov from public.crm_picklist_options where list_key = 'cf:' || t.id::text and lower(label) = lower(lab) and not retired;
      if ov is null then continue; end if; v := to_jsonb(ov); end if;
    c := c || jsonb_build_object(t.id::text, v); end loop;
  update public.contacts set custom = c where id = new.converted_contact_id and custom is distinct from c;
  return null; end $function$

CREATE OR REPLACE FUNCTION private.crm_company_key(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare s text := lower(coalesce(p, '')); t text;
begin
  s := translate(s, 'àáâãäåçèéêëìíîïñòóôõöùúûüýÿ', 'aaaaaaceeeeiiiinooooouuuuyy');
  s := replace(s, '&', ' and ');
  s := btrim(regexp_replace(regexp_replace(s, '[^a-z0-9]+', ' ', 'g'), '\s+', ' ', 'g'));
  s := regexp_replace(s, '(^| )l l (c|p)(?= |$)', '\1ll\2', 'g');   -- "L.L.C." = "LLC"
  s := regexp_replace(s, '^the ', '');
  s := regexp_replace(s, '( (inc|incorporated|llc|l l c|llp|ltd|limited|co|corp|corporation|company|pllc|pc|lp))+$', '');
  t := btrim(regexp_replace(regexp_replace(' ' || s || ' ', ' (inc|incorporated|llc|llp|ltd|corp|corporation|pllc)(?= )', '', 'g'), '\s+', ' ', 'g'));
  return coalesce(nullif(t, ''), s); end $function$

CREATE OR REPLACE FUNCTION private.crm_contact_json(p_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select jsonb_build_object('id', c.id, 'name', btrim(c.first_name || ' ' || c.last_name), 'firstName', c.first_name, 'lastName', c.last_name, 'email', c.email, 'phone', c.phone, 'company', c.company,
    'contactType', c.contact_type, 'hasLogin', c.profile_id is not null, 'ownerId', c.crm_owner_id, 'ownerName', coalesce(private.crm_name(c.crm_owner_id), ''),
    'accountId', c.account_id, 'accountName', coalesce((select name from public.crm_accounts where id = c.account_id), ''), 'stage', c.crm_stage, 'lastContactedOn', c.last_contacted_on,
    'companyName', coalesce((select name from public.crm_accounts where id = c.account_id), c.company),
    'tags', to_jsonb(c.tags), 'notes', c.crm_notes, 'description', c.crm_notes, 'archived', c.crm_archived_at is not null, 'fromLeadId', c.crm_lead_id, 'linked', private.crm_linked(c.id), 'canEdit', private.crm_editor(),
    'leadSource', c.lead_source, 'relationshipStatus', coalesce(c.relationship_status, ''), 'custom', c.custom,
    'salesReps', coalesce((select jsonb_agg(jsonb_build_object('id', l.sales_id, 'name', private.crm_name(l.sales_id))) from public.client_sales_reps l where l.client_id = c.profile_id), '[]'::jsonb),
    'orders', (select count(distinct dp.deal_id) from public.deal_participants dp where dp.contact_id = c.id),
    'volume', coalesce((select sum(d.purchase_price) from public.deals d where d.status <> 'Cancelled' and exists (select 1 from public.deal_participants dp where dp.deal_id = d.id and dp.contact_id = c.id)), 0),
    'createdAt', c.created_at, 'modifiedAt', c.modified_at)
    || private.crm_person_json(to_jsonb(c))
  from public.contacts c where c.id = p_id $function$

CREATE OR REPLACE FUNCTION private.crm_contact_visible(p_contact uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and private.crm_in_pool(p_contact)
    and (private.crm_owner_ok((select crm_owner_id from public.contacts where id = p_contact)) or private.crm_linked(p_contact)) $function$

CREATE OR REPLACE FUNCTION private.crm_custom_in(p_entity text, p_new jsonb, p_old jsonb, p_insert boolean, p_require boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare r jsonb; k text; v jsonb; s text; n numeric; f public.crm_custom_fields; o jsonb := coalesce(p_old, '{}'); x text; arr jsonb; part text; m int; ok boolean;
  editor boolean := private.is_admin() or private.effective_uid() is null;
begin
  if p_new is null then p_new := '{}'; end if;
  if jsonb_typeof(p_new) <> 'object' then raise exception 'Custom values must be a JSON object.' using errcode = '23514'; end if;
  r := case when p_insert then p_new else o || p_new end;
  for k in select jsonb_object_keys(r) loop
    f := null; select * into f from public.crm_custom_fields cf where cf.id::text = k and cf.entity = p_entity;
    if f.id is null then raise exception 'Unknown custom field.' using errcode = '23514'; end if;
    v := r -> k;
    if f.archived_at is not null then
      if v is distinct from o -> k then raise exception 'The field "%" was deleted; restore it to change its value.', f.label using errcode = 'P0001'; end if; continue; end if;
    if f.type in ('formula', 'rollup') then r := r - k; continue; end if;   -- calculated by the app when shown; never stored
    if f.type = 'autonumber' then if p_insert then r := r - k; else r := jsonb_set(r, array[k], coalesce(o -> k, 'null')); if o -> k is null then r := r - k; end if; end if; continue; end if;
    if v is not distinct from o -> k then continue; end if;   -- unchanged (e.g. a retired option)
    -- video 8 Set Permission: a role without Edit cannot change the value (Admin / Super admin always can)
    if not editor and f.perm_edit is not null and not (private.me_role() = any (f.perm_edit)) then
      raise exception 'You cannot change "%".', f.label using errcode = '42501'; end if;
    if jsonb_typeof(v) = 'null' or (jsonb_typeof(v) = 'string' and btrim(v #>> '{}') = '') or (jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 0) then r := r - k; continue; end if;
    if f.type = 'multiselect' then
      if jsonb_typeof(v) <> 'array' then raise exception '% takes a list of options.', f.label using errcode = '23514'; end if;
      arr := '[]';
      for x in select distinct btrim(e) from jsonb_array_elements_text(v) e where btrim(e) <> '' loop
        perform private.crm_list_check('cf:' || f.id::text, x, case when coalesce(o -> k, '[]') ? x then x end, null, false, f.label); arr := arr || to_jsonb(x); end loop;
      r := jsonb_set(r, array[k], arr); continue; end if;
    if f.type = 'address' then
      if jsonb_typeof(v) <> 'object' then raise exception '% takes street, city, state, zip code and country.', f.label using errcode = '23514'; end if;
      arr := '{}';
      for part in select jsonb_object_keys(v) loop
        if part not in ('street', 'city', 'state', 'zip', 'country') then raise exception '% has an unknown part.', f.label using errcode = '23514'; end if;
        x := btrim(v ->> part); if char_length(x) > 120 or x ~ '[[:cntrl:]]' then raise exception '% (%) can be at most 120 characters.', f.label, part using errcode = '23514'; end if;
        if part = 'zip' and x <> '' and x !~ '^[A-Za-z0-9 -]{3,10}$' then raise exception '% (Zip Code) is not valid.', f.label using errcode = '23514'; end if;
        if x <> '' then arr := arr || jsonb_build_object(part, x); end if; end loop;
      if arr = '{}' then r := r - k; else r := jsonb_set(r, array[k], arr); end if; continue; end if;
    if f.type in ('file', 'image') then
      if jsonb_typeof(v) <> 'array' then raise exception '% takes uploaded files.', f.label using errcode = '23514'; end if;
      if exists (select 1 from jsonb_array_elements_text(v) e where e !~ '^[0-9a-f-]{36}$' or not exists (select 1 from public.crm_attachments a where a.id = e::uuid and a.entity = p_entity)) then
        raise exception '% must point at files uploaded to this record.', f.label using errcode = '23514'; end if;
      if f.type = 'image' and exists (select 1 from jsonb_array_elements_text(v) e join public.crm_attachments a on a.id = e::uuid where lower(substring(a.name from '\.([^.]+)$')) not in ('png', 'jpg', 'jpeg', 'gif', 'webp')) then
        raise exception '% takes an image (png, jpg, jpeg, gif, webp).', f.label using errcode = '23514'; end if;
      continue; end if;
    if jsonb_typeof(v) not in ('string', 'number', 'boolean') then raise exception '% has an invalid value.', f.label using errcode = '23514'; end if;
    s := btrim(v #>> '{}');
    if f.max_chars is not null and char_length(s) > f.max_chars then raise exception '% can be at most % characters.', f.label, f.max_chars using errcode = '23514'; end if;
    case f.type
      when 'text' then if char_length(s) > 255 then raise exception '% can be at most 255 characters.', f.label using errcode = '23514'; end if; r := jsonb_set(r, array[k], to_jsonb(s));
      when 'textarea' then if char_length(s) > 4000 then raise exception '% can be at most 4000 characters.', f.label using errcode = '23514'; end if; r := jsonb_set(r, array[k], to_jsonb(s));
      when 'number', 'currency', 'percent', 'decimal' then
        s := regexp_replace(s, case when f.type in ('number', 'decimal') then ',' else '[$,%\s]' end, '', 'g');
        if s !~ '^-?([0-9]+(\.[0-9]*)?|\.[0-9]+)$' then raise exception '% must be a number.', f.label using errcode = '23514'; end if;
        n := s::numeric; if abs(n) > 1e13 then raise exception '% is too large.', f.label using errcode = '23514'; end if;
        if f.type = 'decimal' then n := round(n, coalesce((f.config ->> 'decimals')::int, 2)); elsif f.type <> 'number' then n := round(n, 2); end if; r := jsonb_set(r, array[k], to_jsonb(n));
      when 'longint' then s := replace(s, ',', '');
        if s !~ '^-?[0-9]{1,16}$' or abs(s::numeric) > 9007199254740991 then raise exception '% must be a whole number.', f.label using errcode = '23514'; end if; r := jsonb_set(r, array[k], to_jsonb(s::bigint));
      when 'date' then
        begin if s !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or to_char(to_date(s, 'YYYY-MM-DD'), 'YYYY-MM-DD') <> s then s := 'bad'; end if;
        exception when others then s := 'bad'; end;
        if s = 'bad' then raise exception '% must be a real date (YYYY-MM-DD).', f.label using errcode = '23514'; end if;
        r := jsonb_set(r, array[k], to_jsonb(s));
      when 'datetime' then
        ok := s ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}';
        if ok then begin s := substr(s, 1, 10) || 'T' || substr(s, 12, 5); ok := to_char(to_timestamp(s, 'YYYY-MM-DD"T"HH24:MI'), 'YYYY-MM-DD"T"HH24:MI') = s; exception when others then ok := false; end; end if;
        if not ok then raise exception '% must be a real date and time.', f.label using errcode = '23514'; end if; r := jsonb_set(r, array[k], to_jsonb(s));
      when 'checkbox' then r := jsonb_set(r, array[k], to_jsonb(lower(s) in ('true', '1', 'on', 'yes')));
      when 'dropdown', 'radio' then
        perform private.crm_list_check('cf:' || f.id::text, s, o ->> k, null, false, f.label); r := jsonb_set(r, array[k], to_jsonb(s));
      when 'email' then s := lower(s);
        if char_length(s) > 200 or s !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception '% is not a valid email address.', f.label using errcode = '23514'; end if; r := jsonb_set(r, array[k], to_jsonb(s));
      when 'phone' then s := regexp_replace(s, '\D', '', 'g');
        if char_length(s) <> 10 then raise exception '% must be a 10-digit phone number (xxx-xxx-xxxx).', f.label using errcode = '23514'; end if;
        r := jsonb_set(r, array[k], to_jsonb(substr(s, 1, 3) || '-' || substr(s, 4, 3) || '-' || substr(s, 7)));
      when 'url' then r := jsonb_set(r, array[k], to_jsonb(private.crm_url_in(s)));
      when 'user' then
        if s !~ '^[0-9a-f-]{36}$' or not exists (select 1 from public.profiles p where p.id = s::uuid and p.status = 'active' and p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Admin', 'Super admin')) then
          raise exception 'Pick a CLA user for %.', f.label using errcode = '23514'; end if; r := jsonb_set(r, array[k], to_jsonb(s));
      when 'lookup' then
        ok := s ~ '^[0-9a-f-]{36}$';
        if ok then ok := case f.config ->> 'target' when 'contacts' then private.crm_in_pool(s::uuid) when 'leads' then exists (select 1 from public.crm_leads where id = s::uuid)
          when 'accounts' then exists (select 1 from public.crm_accounts where id = s::uuid) when 'opportunities' then exists (select 1 from public.crm_opportunities where id = s::uuid)
          when 'deals' then exists (select 1 from public.deals where id = s::uuid) else false end; end if;
        if not ok then raise exception 'Pick a record from %.', f.label using errcode = '23514'; end if; r := jsonb_set(r, array[k], to_jsonb(s));
      else raise exception '% has an invalid value.', f.label using errcode = '23514';
    end case;
  end loop;
  -- auto numbers: assigned on a new record, never typed
  if p_insert then
    for f in select * from public.crm_custom_fields cf where cf.entity = p_entity and cf.archived_at is null and cf.type = 'autonumber' order by cf.position for update loop
      m := coalesce((f.config ->> 'next')::int, 1);
      r := jsonb_set(r, array[f.id::text], to_jsonb(coalesce(f.config ->> 'prefix', '') || m || coalesce(f.config ->> 'suffix', '')));
      update public.crm_custom_fields set config = jsonb_set(config, '{next}', to_jsonb(m + 1)) where id = f.id; end loop; end if;
  -- required: on a new record (direct writes and the create functions), and a value once set cannot be blanked
  for f in select * from public.crm_custom_fields cf where cf.entity = p_entity and cf.archived_at is null and cf.required loop
    if not (r ? f.id::text) and (p_require or (not p_insert and o ? f.id::text)) then raise exception '% is required.', f.label using errcode = 'P0001'; end if;
  end loop;
  return r; end $function$

CREATE OR REPLACE FUNCTION private.crm_custom_unique()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare f public.crm_custom_fields; ent text := case tg_table_name when 'crm_leads' then 'lead' when 'contacts' then 'contact' when 'crm_accounts' then 'account' else 'opportunity' end; hit uuid; key text;
begin
  for f in select * from public.crm_custom_fields cf where cf.entity = ent and cf.archived_at is null and cf.unique_values loop
    key := private.crm_dup_key(f.type, new.custom -> f.id::text); if key is null then continue; end if;
    if tg_op = 'UPDATE' and private.crm_dup_key(f.type, old.custom -> f.id::text) is not distinct from key then continue; end if;
    execute format('select id from public.%I where id <> $1 and private.crm_dup_key($2, custom -> $3) = $4 limit 1', tg_table_name) into hit using new.id, f.type, f.id::text, key;
    if hit is not null then raise exception '% "%" is already used on another record. Duplicates are not allowed.', f.label, new.custom ->> f.id::text using errcode = '23505'; end if;
  end loop;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_dash_editable(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_editor() and exists (select 1 from public.crm_dashboards d where d.id = p_id and d.retired_at is null
    and ((d.builtin and private.is_admin()) or d.owner_id = private.effective_uid() or (private.is_admin() and not d.locked and d.visibility <> 'me'))) $function$

CREATE OR REPLACE FUNCTION private.crm_dash_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'Dashboards and components are never deleted; retire them instead.' using errcode = 'P0001'; end if;
  new.modified_by := coalesce(private.effective_uid(), new.modified_by); new.modified_at := now();
  if tg_table_name = 'crm_dashboards' then
    if tg_op = 'INSERT' then
      if private.effective_uid() is not null then new.builtin := false; new.owner_id := private.effective_uid(); new.created_by := private.effective_uid(); new.retired_at := null; end if;
    else
      if (new.builtin, new.owner_id, new.created_by) is distinct from (old.builtin, old.owner_id, old.created_by) then raise exception 'A dashboard''s owner never changes; clone it instead.' using errcode = 'P0001'; end if;
      if old.retired_at is not null and new.retired_at is not null and new is distinct from old then raise exception 'Restore the dashboard before changing it.' using errcode = 'P0001'; end if;
      if new.retired_at is not null and old.retired_at is null then new.retired_by := private.effective_uid(); end if;
      if new.builtin and new.retired_at is not null then raise exception 'Built-in dashboards cannot be retired.' using errcode = 'P0001'; end if;
    end if;
  else
    if tg_op = 'INSERT' then new.created_by := coalesce(private.effective_uid(), new.created_by);
      if private.effective_uid() is not null and not private.crm_dash_editable(new.dashboard_id) then raise exception 'You cannot change this dashboard.' using errcode = '42501'; end if;
      if (select count(*) from public.crm_dash_components where dashboard_id = new.dashboard_id and retired_at is null) >= 30 then raise exception 'At most 30 components per dashboard.' using errcode = 'P0001'; end if;
    elsif private.effective_uid() is not null and (not private.crm_dash_editable(old.dashboard_id) or not private.crm_dash_editable(new.dashboard_id)) then
      raise exception 'You cannot change this dashboard.' using errcode = '42501'; end if;
  end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_dash_visible(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and exists (select 1 from public.crm_dashboards d where d.id = p_id and (d.builtin or d.owner_id = private.effective_uid() or d.visibility = 'all'
    or (d.visibility = 'custom' and private.crm_shared_with_me(d.share)))) $function$

CREATE OR REPLACE FUNCTION private.crm_deal_row(g deals)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select jsonb_build_object('id', g.id, 'name', btrim(g.street || ', ' || g.city || ', ' || g.state || ' ' || g.zip), 'fileNumber', g.file_number, 'propertyAddress', g.street || ', ' || g.city || ', ' || g.state || ' ' || g.zip,
    'amount', g.purchase_price, 'loanAmount', g.loan_amount, 'stage', case g.status when 'Open' then 'Active' else g.status end, 'status', g.status,
    'closingDate', g.closing_date, 'openDate', g.open_date, 'county', coalesce(g.county, ''), 'city', g.city, 'transactionType', g.transaction_type,
    'clientName', coalesce((select string_agg(distinct btrim(c.first_name || ' ' || c.last_name), ', ') from public.deal_participants p join public.contacts c on c.id = p.contact_id where p.deal_id = g.id and p.role in ('Client-Buyer', 'Client-Seller')), ''),
    'clientIds', coalesce((select jsonb_agg(distinct p.contact_id) from public.deal_participants p where p.deal_id = g.id and p.role in ('Client-Buyer', 'Client-Seller')), '[]'),
    'contactName', coalesce((select string_agg(distinct btrim(c.first_name || ' ' || c.last_name), ', ') from public.deal_participants p join public.contacts c on c.id = p.contact_id where p.deal_id = g.id and p.role in ('Buyer Agent', 'Listing Agent')), ''),
    'ownerId', (select s.sales_id from public.deal_sales_people s where s.deal_id = g.id order by s.added_at, s.sales_id limit 1),
    'ownerName', coalesce((select private.crm_name(s.sales_id) from public.deal_sales_people s where s.deal_id = g.id order by s.added_at, s.sales_id limit 1), ''),
    'salesIds', coalesce((select jsonb_agg(s.sales_id order by s.added_at, s.sales_id) from public.deal_sales_people s where s.deal_id = g.id), '[]'),
    'salesReps', coalesce((select string_agg(private.crm_name(s.sales_id), ', ' order by s.added_at, s.sales_id) from public.deal_sales_people s where s.deal_id = g.id), ''),
    'source', coalesce((select b.source from public.deal_business_sources b where b.deal_id = g.id), ''),
    'sourceText', coalesce((select private.business_source_label(b.source) from public.deal_business_sources b where b.deal_id = g.id and b.source <> ''), ''),
    'createdAt', g.created_at) $function$

CREATE OR REPLACE FUNCTION private.crm_deal_scope_all()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and coalesce((select p.is_admin or (p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team')
      and coalesce((select bool_and(r.allowed) and count(*) = 2 from public.role_module_access r where r.role = p.role and r.module in ('crm', 'crm_all_deals')), false))
    from public.profiles p where p.id = private.effective_uid() and p.status = 'active'), false) $function$

CREATE OR REPLACE FUNCTION private.crm_deal_visible(d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and private.can_access_deal(d) and (private.crm_deal_scope_all()
    or (coalesce(private.me_role() = 'Sales Person', false) and exists (select 1 from public.deal_sales_people s where s.deal_id = d and s.sales_id = private.effective_uid()))) $function$

CREATE OR REPLACE FUNCTION private.crm_depts_of(p_role text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case when p_role in ('Sales Person', 'Sales Team') then array['sales'] when p_role in ('Processor', 'Preprocessor') then array['operations']
    when p_role in ('Admin', 'Super admin') then array['management'] else array[]::text[] end $function$

CREATE OR REPLACE FUNCTION private.crm_dropdown_has_options()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.type in ('dropdown', 'multiselect', 'radio') and new.archived_at is null and not exists (select 1 from public.crm_picklist_options where list_key = 'cf:' || new.id::text and not retired) then
    raise exception 'A dropdown field needs at least one option.' using errcode = 'P0001'; end if;
  return null; end $function$

CREATE OR REPLACE FUNCTION private.crm_dup_key(p_type text, v jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case when v is null or jsonb_typeof(v) = 'null' then null when p_type = 'phone' then nullif(regexp_replace(v #>> '{}', '\D', '', 'g'), '')
    when jsonb_typeof(v) = 'number' then (v #>> '{}')::numeric::text else nullif(lower(btrim(v #>> '{}')), '') end $function$

CREATE OR REPLACE FUNCTION private.crm_editor()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and coalesce((select p.is_admin or (p.role in ('Sales Person', 'Sales Team')
      and coalesce((select r.allowed from public.role_module_access r where r.role = p.role and r.module = 'crm'), false))
    from public.profiles p where p.id = private.effective_uid() and p.status = 'active'), false) $function$

CREATE OR REPLACE FUNCTION private.crm_email_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'Email templates, folders, files and signatures are never deleted (retire or detach instead).' using errcode = 'P0001'; end if;
  if tg_table_name = 'crm_email_folders' then
    new.name := btrim(new.name); new.modified_by := coalesce(private.effective_uid(), new.modified_by); new.modified_at := now();
    if tg_op = 'INSERT' then new.created_by := coalesce(private.effective_uid(), new.created_by); new.created_at := now(); end if;
  elsif tg_table_name = 'crm_email_templates' then
    new.name := btrim(new.name); new.subject := btrim(new.subject); new.modified_by := coalesce(private.effective_uid(), new.modified_by); new.modified_at := now();
    if tg_op = 'INSERT' then new.created_by := coalesce(private.effective_uid(), new.created_by); new.created_at := now(); new.retired_at := null; new.retired_by := null;
    else
      if new.module is distinct from old.module then raise exception 'A template stays tied to its module; use Save As to make one for another module.' using errcode = 'P0001'; end if;
      if new.kind is distinct from old.kind then raise exception 'A written template cannot turn into a builder one (or back); use Save As.' using errcode = 'P0001'; end if;
      if (new.created_by, new.created_at) is distinct from (old.created_by, old.created_at) then raise exception 'Who made a template never changes.' using errcode = 'P0001'; end if;
      if new.retired_at is not null and old.retired_at is null then new.retired_by := coalesce(private.effective_uid(), new.retired_by); elsif new.retired_at is null then new.retired_by := null; end if;
    end if;
    if private.effective_uid() is not null and new.personal_owner is not null and new.personal_owner <> private.effective_uid() and (tg_op = 'INSERT' or new.personal_owner is distinct from old.personal_owner) then
      raise exception 'You can only save into shared folders or your own folder.' using errcode = '42501'; end if;
  elsif tg_table_name = 'crm_email_template_files' then
    if tg_op = 'INSERT' then
      if not exists (select 1 from public.crm_attachments a where a.id = new.attachment_id and a.entity = 'template' and a.entity_id = new.template_id) then
        raise exception 'That file was not uploaded to this template.' using errcode = 'P0001'; end if;
      new.attached_by := coalesce(private.effective_uid(), new.attached_by); new.attached_at := now(); new.detached_at := null; new.detached_by := null;
    else
      if (new.template_id, new.attachment_id) is distinct from (old.template_id, old.attachment_id) then raise exception 'A file link cannot move.' using errcode = 'P0001'; end if;
      new.detached_by := case when new.detached_at is null then null else coalesce(private.effective_uid(), new.detached_by) end;
    end if;
  else
    new.modified_at := now();
  end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_email_record_visible(p_entity text, p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and case when p_entity = 'deal' then private.crm_deal_visible(p_id) else private.crm_entity_visible(p_entity, p_id) end $function$

CREATE OR REPLACE FUNCTION private.crm_emails_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare mine text;
begin
  if tg_op <> 'INSERT' then raise exception 'A saved email is never changed or deleted (and never sent).' using errcode = 'P0001'; end if;
  new.created_by := private.effective_uid(); new.created_at := now();
  if not private.crm_editor() then raise exception 'The Processor has read-only access to the CRM.' using errcode = '42501'; end if;
  mine := lower((select email from public.profiles where id = private.effective_uid()));
  if new.from_email is distinct from mine and not exists (select 1 from public.crm_email_aliases where user_id = private.effective_uid() and email = new.from_email and retired_at is null) then
    raise exception 'Send from your own address or one of your aliases.' using errcode = '42501'; end if;
  if new.status = 'scheduled' and new.scheduled_at <= now() then raise exception 'Pick a time in the future to schedule.' using errcode = '23514'; end if;
  if not private.crm_html_safe(new.body_html) then raise exception 'The email body has content that is not allowed (scripts or event handlers).' using errcode = '23514'; end if;
  if new.template_id is not null and not private.crm_template_visible(new.template_id) then raise exception 'That template is not available.' using errcode = '42501'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_emails_ok(a text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select cardinality(a) <= 100 and not exists (select 1 from unnest(a) e where char_length(e) > 200 or e !~ '^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$' or e <> lower(e)) $function$

CREATE OR REPLACE FUNCTION private.crm_entity_visible(p_entity text, p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case p_entity when 'lead' then private.crm_owner_ok((select owner_id from public.crm_leads where id = p_id)) and exists (select 1 from public.crm_leads where id = p_id)
    when 'contact' then private.crm_contact_visible(p_id) when 'account' then private.crm_account_visible(p_id) when 'opportunity' then private.crm_opp_visible(p_id) else false end $function$

CREATE OR REPLACE FUNCTION private.crm_field_section()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'INSERT' or new.section is distinct from old.section then
    if not exists (select 1 from public.crm_layout_sections where entity = new.entity and key = new.section and not hidden) then
      raise exception 'Pick a section that exists for this record type.' using errcode = '23514'; end if; end if;
  if new.type in ('formula', 'rollup', 'autonumber') and new.unique_values then raise exception 'A calculated field cannot be unique.' using errcode = '23514'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_fields_json()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'entity', f.entity, 'label', f.label, 'type', f.type, 'required', f.required, 'section', f.section, 'position', f.position,
    'showInList', f.show_in_list, 'archivedAt', f.archived_at,
    'options', case when f.type = 'dropdown' then coalesce((select jsonb_agg(jsonb_build_object('value', o.value, 'label', o.label, 'retired', o.retired) order by o.position, o.value)
      from public.crm_picklist_options o where o.list_key = 'cf:' || f.id::text), '[]'::jsonb) end) order by f.entity, f.position, f.label), '[]'::jsonb)
  from public.crm_custom_fields f $function$

CREATE OR REPLACE FUNCTION private.crm_first_option(k text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select value from public.crm_picklist_options where list_key = k and not retired order by position, value limit 1 $function$

CREATE OR REPLACE FUNCTION private.crm_html_safe(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select t is null or not (t ~* '<\s*/?\s*(script|iframe|object|embed|style|svg|math|form|meta|link|base)\M' or t ~* '<[^>]*\son[a-z]+\s*=' or t ~* '(java|vb)script\s*:' or t ~* 'data:\s*text/html') $function$

