CREATE OR REPLACE FUNCTION private.crm_today()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$ select (now() at time zone 'America/New_York')::date $function$

CREATE OR REPLACE FUNCTION private.crm_touch_contact()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.entity = 'contact' and new.kind in ('call', 'email', 'meeting') and new.occurred_on <= private.office_today() and not (new.kind = 'call' and new.call_status = 'Scheduled') then
    update public.contacts set last_contacted_on = new.occurred_on where id = new.entity_id and (last_contacted_on is null or last_contacted_on < new.occurred_on); end if;
  return null; end $function$

CREATE OR REPLACE FUNCTION private.crm_unique_on()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare tbl text := case new.entity when 'lead' then 'crm_leads' when 'contact' then 'contacts' when 'account' then 'crm_accounts' else 'crm_opportunities' end; dup boolean;
begin
  if new.unique_values and (tg_op = 'INSERT' or not old.unique_values) then
    execute format('select exists (select 1 from public.%I where private.crm_dup_key($1, custom -> $2) is not null group by private.crm_dup_key($1, custom -> $2) having count(*) > 1)', tbl) into dup using new.type, new.id::text;
    if dup then raise exception 'Two records already hold the same "%"; fix them before turning on Do not allow duplicate values.', new.label using errcode = '23505'; end if; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_url_in(v text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin v := btrim(coalesce(v, '')); if v = '' then return ''; end if;
  if v !~* '^[a-z][a-z0-9+.-]*:' then v := 'https://' || regexp_replace(v, '^/+', ''); end if;
  if not private.crm_url_ok(v) then raise exception 'Links must be http:// or https:// web addresses.' using errcode = 'P0001'; end if; return v; end $function$

CREATE OR REPLACE FUNCTION private.crm_url_ok(u text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select u = '' or (char_length(u) <= 500 and u ~* '^https?://[^\s/:@]+\.[^\s/:@]+(:[0-9]+)?(/\S*)?$') $function$

CREATE OR REPLACE FUNCTION private.crm_usage(k text, p_col text, p_table text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare r jsonb;
begin execute format('select coalesce(jsonb_object_agg(v, n), %L) from (select %I v, count(*) n from public.%I where coalesce(%I, %L) <> %L group by 1) x', '{}', p_col, p_table, p_col, '', '') into r; return r; end $function$

CREATE OR REPLACE FUNCTION private.crm_usage_sum(a jsonb, b jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(jsonb_object_agg(k, coalesce((a->>k)::int, 0) + coalesce((b->>k)::int, 0)), '{}') from (select jsonb_object_keys(a) k union select jsonb_object_keys(b)) x $function$

