 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_on() and (private.is_admin() or coalesce(private.me_role() in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team'), false)) $function$

