CREATE OR REPLACE FUNCTION private.crm_view_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'Views are never deleted; retire them instead.' using errcode = 'P0001'; end if;
  if tg_op = 'INSERT' then new.owner_id := coalesce(private.effective_uid(), new.owner_id); new.created_at := now(); new.retired_at := null; new.retired_by := null;
  else if new.owner_id is distinct from old.owner_id or new.module is distinct from old.module then raise exception 'A view''s owner and module never change; clone it instead.' using errcode = 'P0001'; end if;
    if new.retired_at is not null and old.retired_at is null then new.retired_by := private.effective_uid(); end if; end if;
  -- the Processor is read-only in the CRM: their views stay private
  if new.visibility <> 'me' and not private.crm_editor() and private.effective_uid() is not null then raise exception 'The Processor has read-only access to the CRM: views you make are for you only.' using errcode = '42501'; end if;
  new.modified_at := now(); new.modified_by := private.effective_uid(); return new; end $function$

CREATE OR REPLACE FUNCTION private.crm_view_share_ok()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if not exists (select 1 from public.profiles p where p.id = new.user_id and p.status = 'active' and p.role in ('Super admin', 'Admin', 'Processor', 'Sales Person', 'Sales Team')) then
    raise exception 'Share with active CLA users only.' using errcode = '23514'; end if;
  return new; end $function$

