 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.crm_user() and exists (select 1 from public.crm_views v where v.id = p_view and v.retired_at is null and (v.owner_id = private.effective_uid() or v.visibility = 'all'
    or (v.visibility = 'custom' and exists (select 1 from public.crm_view_shares s where s.view_id = v.id and s.user_id = private.effective_uid())))) $function$

CREATE OR REPLACE FUNCTION private.deal_cla_staff(d uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select x.pid from (
    select processor_id as pid from public.deals where id = d
    union select preprocessor_user_id from public.deals where id = d
    union select tc_user_id from public.deals where id = d
    union select sales_person_id from public.deals where id = d
    union select s.sales_id from public.deal_sales_people s where s.deal_id = d
    union select c.profile_id
      from public.deal_participants dp
      join public.contacts c on c.id = dp.contact_id
      where dp.deal_id = d
        and dp.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator')
    union
    select p.id
      from public.deal_participants dp
      join public.contacts c on c.id = dp.contact_id
      join public.profiles p on lower(p.email) = lower(btrim(c.email))
      where dp.deal_id = d
        and c.profile_id is null
        and btrim(coalesce(c.email, '')) <> ''
        and dp.role in ('Processor', 'Preprocessor')
        and p.status = 'active'
        and p.role in ('Processor', 'Preprocessor')
        and p.is_demo is not distinct from (select z.is_demo from public.deals z where z.id = d)
  ) x
  where x.pid is not null
$function$

CREATE OR REPLACE FUNCTION private.deal_closer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  new.closer_name := left(btrim(coalesce(new.closer_name, '')), 120);
  if new.closer_profile_id is null then return new; end if;
  if tg_op = 'UPDATE' and new.closer_profile_id is not distinct from old.closer_profile_id then return new; end if;
  if not exists (
    select 1 from public.profiles p
    where p.id = new.closer_profile_id
      and p.status = 'active'
      and p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin')
      and p.is_demo is not distinct from coalesce(new.is_demo, false)
  ) then
    raise exception 'The closer must be an active CLA staff member, or a typed name with no staff login.' using errcode = 'P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.deal_disbursement_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare f text; o numeric; n numeric;
begin
  if tg_op = 'DELETE' then raise exception 'Disbursement Details are never deleted; clear a field instead.' using errcode = 'P0001'; end if;
  new.updated_by := coalesce(private.effective_uid(), new.updated_by); new.updated_at := now();
  if (tg_op = 'INSERT' and new.disbursement_date is not null) or (tg_op = 'UPDATE' and new.disbursement_date is distinct from old.disbursement_date) then
    insert into public.deal_disbursement_log (deal_id, field_key, old_date, new_date, changed_by) values (new.deal_id, 'disbursement_date', case when tg_op = 'UPDATE' then old.disbursement_date end, new.disbursement_date, new.updated_by); end if;
  foreach f in array array['actual_revenue', 'net_title_insurance', 'settlement_fee', 'net_endorsement_fee', 'qualia_fee', 'shipping_fee', 'national_title_resource', 'notary_fee', 'searches_fee'] loop
    execute format('select ($1).%I, ($2).%I', f, f) into n, o using new, (case when tg_op = 'UPDATE' then old else null::public.deal_disbursements end);
    if n is distinct from o then insert into public.deal_disbursement_log (deal_id, field_key, old_amount, new_amount, changed_by) values (new.deal_id, f, o, n, new.updated_by); end if;
  end loop;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.deal_file_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  m text[]; next_number text;
begin
  if tg_op = 'INSERT' then
    if new.file_number is null or btrim(new.file_number) = '' then
      new.file_number := private.file_number_prefix(new.state) || '-' || to_char(now() at time zone 'America/New_York', 'YY') || '-' || nextval('public.file_number_seq');
    end if;
    return new;
  end if;
  -- UPDATE OF state
  if new.state is not distinct from old.state or new.file_number is distinct from old.file_number or new.status <> 'Open' then return new; end if;
  m := regexp_match(old.file_number, '^([A-Z]{2})-(\d{2})-(\d+)$');
  if m is null then return new; end if;
  next_number := private.file_number_prefix(new.state) || '-' || m[2] || '-' || m[3];
  if next_number = old.file_number then return new; end if;
  if exists (select 1 from public.deal_emails e where e.deal_id = old.id and e.direction = 'out'
               and exists (select 1 from unnest(coalesce(e.to_emails, '{}') || coalesce(e.cc_emails, '{}') || coalesce(e.bcc_emails, '{}')) a
                           where btrim(a) <> '' and lower(btrim(a)) not like '%@clatitle.com'))
     or exists (select 1 from public.outbox o where o.deal_id = old.id and (o.sent_at is not null or o.status = 'sent')
               and exists (select 1 from unnest(array[o.to_email] || coalesce(o.cc_emails, '{}') || coalesce(o.bcc_emails, '{}')) a
                           where btrim(coalesce(a, '')) <> '' and lower(btrim(a)) not like '%@clatitle.com')) then
    return new;   -- something carrying the number already went outside CLA: keep it
  end if;
  if exists (select 1 from public.deals d where d.file_number = next_number and d.id <> old.id) then return new; end if;
  new.file_number := next_number;
  perform private.log_activity(old.id, 'deal.file_number', 'deal', old.id, 'File number changed from ' || old.file_number || ' to ' || next_number || ' (property state ' || coalesce(new.state, '') || ')');
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.deal_file_number_edit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  next_number text;
begin
  next_number := regexp_replace(btrim(coalesce(new.file_number, '')), '\s+', ' ', 'g');
  if next_number = '' then
    raise exception 'Enter a file number.';
  end if;
  if char_length(next_number) > 40 then
    raise exception 'A file number can be up to 40 characters. Shorten it and save again.';
  end if;
  if next_number !~ $re$^[A-Za-z0-9][A-Za-z0-9 ._/#'-]*$$re$ then
    raise exception 'Use letters, numbers, and these marks only: space, hyphen, period, slash, and #.';
  end if;
  new.file_number := next_number;
  if next_number = old.file_number then return new; end if;
  if exists (select 1 from public.deals d where d.id <> old.id and lower(d.file_number) = lower(next_number)) then
    raise exception 'That file number is already on another file. Enter a different number.';
  end if;
  perform private.log_activity(old.id, 'deal.file_number', 'deal', old.id, 'File number changed from ' || old.file_number || ' to ' || next_number);
  return new;
end $function$

