 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin if new.transaction_type = 'Refinance' then new.primary_residence := ''; new.first_time_buyer := ''; end if; return new; end $function$

CREATE OR REPLACE FUNCTION private.deal_old_commission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.listing_commission_pct is not null or new.listing_commission_amount is not null
     or new.buyer_commission_pct is not null or new.buyer_commission_amount is not null
     or jsonb_strip_nulls(coalesce(new.financial, '{}'::jsonb)) ?| private.old_commission_keys() then
