CREATE OR REPLACE FUNCTION private.deal_party_names()
 RETURNS TABLE(deal_id uuid, party_names text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET jit TO 'off'
AS $function$
  with g as materialized (
    select * from private.reader_gate()
  ),
  visible as (
    select d.id
    from public.deals d
    cross join g
    where d.is_demo = g.is_demo
      and private.reader_can_deal(d.id, g.uid, g.role, g.is_admin, g.contact_id, g.active)
  ),
  roles as (
    select v.id as deal_id,
      case
        when g.role is null then '{}'::text[]
        when g.role <> 'Outside user' then array[g.role]::text[]
        else coalesce((
          select array_agg(x.role order by array_position(array['Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller'], x.role))
          from (
            select distinct p.role
            from public.deal_participants p
            join public.contacts c on c.id = p.contact_id
            where p.deal_id = v.id
              and c.profile_id = g.uid
              and p.role in ('Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller')
          ) x
        ), array['Outside user']::text[])
      end as roles
    from visible v
    cross join g
  ),
  shaped as (
    select r.deal_id,
      r.roles,
      case
        when g.role is null then null::text
        when g.role <> 'Outside user' then g.role
        else coalesce(r.roles[1], 'Outside user')
      end as deal_role,
      case
        when g.role is distinct from 'Outside user' then 'staff'
        else (
          select case when count(distinct s) = 1 then max(s) end
          from (
            select case ur
              when 'Buyer Agent' then 'buyer'
              when 'Client-Buyer' then 'buyer'
              when 'Listing Agent' then 'seller'
              when 'Client-Seller' then 'seller'
            end as s
            from unnest(r.roles) ur
          ) q
          where s is not null
        )
      end as side
    from roles r
    cross join g
  ),
  flags as (
    select s.deal_id, s.deal_role,
      (g.uid is not null and not g.staffish and coalesce(s.side <> 'staff', false)
        and 'Client-Buyer' = any (s.roles)
        and not (s.roles && array['Buyer Agent', 'Listing Agent']::text[])) as pure_buyer,
      (g.uid is not null and not g.staffish and coalesce(s.side <> 'staff', false)
        and 'Client-Seller' = any (s.roles)
        and not ('Client-Buyer' = any (s.roles))
        and not (s.roles && array['Buyer Agent', 'Listing Agent']::text[])) as pure_seller
    from shaped s
    cross join g
  ),
  named as (
    select f.deal_id,
      coalesce(
        case when dp.role in ('Client-Buyer', 'Client-Seller') then nullif(btrim(e.name), '') end,
        nullif(btrim(c.first_name || ' ' || c.last_name), ''),
        case when dp.role in ('Client-Buyer', 'Client-Seller') then nullif(btrim(c.company), '') end
      ) as party_name
    from flags f
    join public.deal_participants dp on dp.deal_id = f.deal_id
    join public.contacts c on c.id = dp.contact_id
    left join public.participant_entities e on e.participant_id = dp.id and e.removed_at is null
    where not (
        f.deal_role in ('Client-Buyer', 'Client-Seller')
        and dp.role like 'Client-%'
        and dp.role <> f.deal_role
      )
      and not (dp.role = 'Listing Agent' and f.pure_buyer)
      and not (dp.role = 'Buyer Agent' and f.pure_seller)
  )
  select n.deal_id, coalesce(array_agg(distinct n.party_name), '{}'::text[])
  from named n
  where coalesce(n.party_name, '') <> ''
  group by n.deal_id
$function$

CREATE OR REPLACE FUNCTION private.deal_place_order_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'INSERT' or new.open_date is distinct from old.open_date then
    if new.open_date is null then new.open_date := (now() at time zone 'America/New_York')::date; end if;
    if new.open_date > (now() at time zone 'America/New_York')::date then raise exception 'Open date cannot be in the future.' using errcode = 'P0001'; end if;
  end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.deal_preprocessor_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.preprocessor_user_id is not null and not exists (select 1 from public.profiles p where p.id = new.preprocessor_user_id and p.role = 'Preprocessor' and p.status = 'active') then
    raise exception 'The Preprocessor on an order must be an active Preprocessor.' using errcode = 'P0001'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.deal_processor_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.processor_id is null then return new; end if;
  if tg_op = 'INSERT' or new.processor_id is distinct from old.processor_id then
    if not exists (select 1 from public.profiles p where p.id = new.processor_id and p.status = 'active'
       and p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin')
       and p.is_demo is not distinct from coalesce(new.is_demo, false)) then
      raise exception 'The Processor on an order must be an active staff login.' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.deal_profiles(d uuid)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select array(select c.profile_id from public.deal_participants p join public.contacts c on c.id = p.contact_id where p.deal_id = d and c.profile_id is not null
               union select processor_id from public.deals where id = d and processor_id is not null) $function$

CREATE OR REPLACE FUNCTION private.deal_refi_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare chg boolean := tg_op = 'INSERT' or new.transaction_type is distinct from old.transaction_type;
begin
  if new.transaction_type = 'Refinance' then
    if new.purchase_price is not null and (chg or new.purchase_price is distinct from old.purchase_price) then
      raise exception 'A refinance has no purchase price. Leave it empty.' using errcode = '23514'; end if;
    if new.emd_amount is not null and (chg or new.emd_amount is distinct from old.emd_amount) then
      raise exception 'A refinance has no EMD amount. Leave it empty.' using errcode = '23514'; end if;
    if new.emd_due_date is not null and (chg or new.emd_due_date is distinct from old.emd_due_date) then
      raise exception 'A refinance has no EMD due date. Leave it empty.' using errcode = '23514'; end if;
    if tg_op = 'UPDATE' and chg and exists (select 1 from public.deal_participants p where p.deal_id = new.id and private.refi_blocked_role(p.role)) then
      raise exception 'This order still has a seller, realtor or transaction coordinator; remove them before making it a refinance.' using errcode = '23514'; end if;
  end if;
  return new; end $function$

