 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case when private.me_role() is null then null when private.me_role() <> 'Outside user' then private.me_role() else private.file_role_of(private.effective_uid(), d) end $function$

CREATE OR REPLACE FUNCTION private.deal_roles(d uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case when private.me_role() is null then '{}'::text[] else private.file_roles_of(private.effective_uid(), d) end $function$

CREATE OR REPLACE FUNCTION private.deal_sales_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare s public.profiles;
begin
  select * into s from public.profiles where id = new.sales_id;
  if s.id is null then raise exception 'Salesperson not found.' using errcode = 'P0001'; end if;
  if coalesce(current_setting('cla.sales_backfill', true), '') = 'on' then return new; end if;
  if s.role not in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin')
     or s.status <> 'active' then
    raise exception 'Only an active staff login can be a salesperson on an order.' using errcode = 'P0001';
  end if;
  if s.is_demo is distinct from coalesce((select d.is_demo from public.deals d where d.id = new.deal_id), false) then
    raise exception 'A real order cannot use a demo login, and a demo order cannot use a real login.' using errcode = 'P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.deal_tc_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'INSERT' and new.tc_user_id is null and new.created_by is not null and exists (
       select 1 from public.profiles p where p.id = new.created_by
         and p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin')
         and p.status = 'active'
         and p.is_demo is not distinct from coalesce(new.is_demo, false)
         and p.role = 'Transaction Coordinator') then
    new.tc_user_id := new.created_by;
  end if;
  if new.tc_user_id is null then return new; end if;
  if tg_op = 'INSERT' or new.tc_user_id is distinct from old.tc_user_id then
    if not exists (select 1 from public.profiles p where p.id = new.tc_user_id and p.status = 'active'
         and p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin')
         and p.is_demo is not distinct from coalesce(new.is_demo, false)) then
      raise exception 'The Transaction Coordinator on an order must be an active staff login.' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.demo_portal_role(p_profile uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(
    (select dp.role from public.deal_participants dp
       join public.contacts c on c.id = dp.contact_id
       join public.deals d on d.id = dp.deal_id and d.is_demo
      where c.profile_id = p_profile
      order by case dp.role
        when 'Buyer Agent' then 1 when 'Listing Agent' then 2
        when 'Client-Buyer' then 3 when 'Client-Seller' then 4 else 9 end
      limit 1),
    (select role from public.profiles where id = p_profile))
$function$

CREATE OR REPLACE FUNCTION private.demo_view_status_for(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare s private.view_as_sessions; t public.profiles;
begin
  perform private.expire_demo_view(p_actor);
  select * into s from private.view_as_sessions v
    where v.actor_id = p_actor and v.stopped_at is null and v.expires_at > pg_catalog.now();
  if s.actor_id is null then
    return jsonb_build_object('active', false, 'actor_id', p_actor);
  end if;
  select * into t from public.profiles where id = s.target_id;
  return jsonb_build_object(
    'active', true,
    'actor_id', p_actor,
    'target_id', s.target_id,
    'target_name', btrim(coalesce(t.first_name, '') || ' ' || coalesce(t.last_name, '')),
    'role', t.role,
    'portal_role', private.demo_portal_role(s.target_id),
    'expires_at', s.expires_at);
end $function$

CREATE OR REPLACE FUNCTION private.demo_visible_deal_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER ROWS 30
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET jit TO 'off'
AS $function$
  select d.id
  from private.reader_gate() g
  join public.deals d on d.is_demo = g.is_demo
$function$

CREATE OR REPLACE FUNCTION private.doc_readable_by(pid uuid, doc uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.doc_visible_to(pid, doc) and exists (select 1 from public.documents d where d.id = doc and (
    not private.person_pure_buyer(pid, d.deal_id) or d.uploaded_by = pid or d.shared_with_client or private.buyer_doc_ok(pid, d.id))
    and (not private.person_pure_seller(pid, d.deal_id) or d.uploaded_by = pid or d.shared_with_seller or private.seller_doc_ok(pid, d.id))) $function$

CREATE OR REPLACE FUNCTION private.doc_types(p_side text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case p_side
    when 'seller' then array['Payoff statement', 'HOA documents', 'Deed', 'Survey', 'Tax bill', 'Power of attorney', 'Death certificate / estate documents', 'Mortgage statement', 'W-9 / 1099-S information', 'Utility bills',
      'Operating agreement / amendments', 'Certificate of good standing', 'Articles of organization', 'Other']
    when 'buyer' then array['Contract / addendum', 'Photo ID', 'Lender documents', 'Homeowners insurance', 'Earnest money receipt', 'Settlement statement',
      'Operating agreement / amendments', 'Certificate of good standing', 'Articles of organization', 'Other']
    else array['Contract / addendum', 'Photo ID', 'Lender documents', 'Homeowners insurance', 'Earnest money receipt', 'Settlement statement', 'Other',
      'Payoff statement', 'HOA documents', 'Deed', 'Survey', 'Tax bill', 'Power of attorney', 'Death certificate / estate documents', 'Mortgage statement', 'W-9 / 1099-S information', 'Utility bills',
      'Operating agreement / amendments', 'Certificate of good standing', 'Articles of organization'] end $function$

CREATE OR REPLACE FUNCTION private.doc_visible(visibility text, uploader uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select uploader = private.effective_uid() or private.is_staffish() or visibility = 'all' $function$

CREATE OR REPLACE FUNCTION private.doc_visible(visibility text, uploader uuid, d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select uploader = private.effective_uid() or private.is_staffish()
         or visibility = 'all' or (visibility in ('buyer', 'seller') and visibility = private.side_of(private.deal_role(d))) $function$

CREATE OR REPLACE FUNCTION private.doc_visible_to(pid uuid, doc uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select exists (select 1 from public.documents d left join public.folders f on f.id = d.folder_id where d.id = doc and (
    private.person_side(pid, d.deal_id) = 'staff' or d.uploaded_by = pid
    or (not coalesce(f.staff_only, false) and (d.visibility = 'all' or d.visibility = private.person_side(pid, d.deal_id)
        or (d.shared_with_client and d.visibility <> 'staff' and private.person_pure_buyer(pid, d.deal_id))
        or (d.shared_with_seller and d.visibility <> 'staff' and private.person_pure_seller(pid, d.deal_id)))))
    and (not d.wire_instructions or d.uploaded_by = pid or private.person_wire_allowed(pid, d.deal_id))) $function$

CREATE OR REPLACE FUNCTION private.document_readable(doc uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET jit TO 'off'
AS $function$
  with viewer as materialized (
    select coalesce(
      (select s.target_id
         from private.view_as_sessions s
         join public.profiles a on a.id = s.actor_id
        where s.actor_id = auth.uid()
          and a.role = 'Super admin' and a.is_admin and a.status = 'active'
          and s.stopped_at is null
          and s.expires_at > pg_catalog.now()),
      auth.uid()
    ) as uid
  ),
  me as materialized (
    select v.uid,
           (select p.role from public.profiles p where p.id = v.uid and p.status = 'active') as active_role,
           (select p.role from public.profiles p where p.id = v.uid) as raw_role,
           coalesce((select p.is_admin from public.profiles p where p.id = v.uid and p.status = 'active'), false) as is_admin,
           (select c.id from public.contacts c where c.profile_id = v.uid) as contact_id
    from viewer v
  ),
  gate as materialized (
    select m.*,
           (m.active_role is not null) as active,
           (m.is_admin or coalesce(m.active_role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin'), false)) as staffish
    from me m
  ),
  one as (
    select d.*
    from public.documents d
    where d.id = doc
  ),
  role_row as (
    select z.roles,
           z.one_role,
           case
             when g.raw_role is distinct from 'Outside user' then 'staff'
             else (
               select case when count(distinct s) = 1 then max(s) end
               from (
                 select case r
                          when 'Buyer Agent' then 'buyer'
                          when 'Client-Buyer' then 'buyer'
                          when 'Listing Agent' then 'seller'
                          when 'Client-Seller' then 'seller'
                        end as s
                 from unnest(z.roles) r
               ) q
               where s is not null
             )
           end as viewer_side
    from gate g
    cross join one o
    cross join lateral (
      select
        case
          when g.active_role is null then '{}'::text[]
          when g.raw_role is null then '{}'::text[]
          when g.raw_role <> 'Outside user' then array[g.raw_role]::text[]
          else coalesce((
            select array_agg(x.role order by array_position(array['Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller'], x.role))
            from (
              select distinct p.role
              from public.deal_participants p
              join public.contacts c on c.id = p.contact_id
              where p.deal_id = o.deal_id
                and c.profile_id = g.uid
                and p.role in ('Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller')
            ) x
          ), array['Outside user']::text[])
        end as roles,
        case
          when g.active_role is null then null::text
          when g.active_role <> 'Outside user' then g.active_role
          else coalesce((
            select p.role
            from public.deal_participants p
            join public.contacts c on c.id = p.contact_id
            where p.deal_id = o.deal_id
              and c.profile_id = g.uid
              and p.role in ('Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller')
            order by array_position(array['Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller'], p.role)
            limit 1
          ), 'Outside user')
        end as one_role
    ) z
  )
  select exists (
    select 1
    from one o
    cross join gate g
    cross join role_row r
    left join public.folders f on f.id = o.folder_id
    left join lateral (
      select case
               when pr.role is distinct from 'Outside user' then 'staff'
               else (
                 select case when count(distinct s) = 1 then max(s) end
                 from (
                   select case ur
                            when 'Buyer Agent' then 'buyer'
                            when 'Client-Buyer' then 'buyer'
                            when 'Listing Agent' then 'seller'
                            when 'Client-Seller' then 'seller'
                          end as s
                   from unnest(
                     case
                       when pr.role is null then '{}'::text[]
                       when pr.role <> 'Outside user' then array[pr.role]::text[]
                       else coalesce((
                         select array_agg(x.role order by array_position(array['Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller'], x.role))
                         from (
                           select distinct p.role
                           from public.deal_participants p
                           join public.contacts c on c.id = p.contact_id
                           where p.deal_id = o.deal_id
                             and c.profile_id = o.uploaded_by
                             and p.role in ('Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller')
                         ) x
                       ), array['Outside user']::text[])
                     end
                   ) ur
                 ) q
                 where s is not null
               )
             end as side
      from (select (select role from public.profiles where id = o.uploaded_by) as role) pr
    ) up on true
    where g.active
      and (
        o.deal_id is null
        or (
          g.is_admin
          or coalesce(g.active_role in ('Processor', 'Sales Team', 'Transaction Coordinator'), false)
          or (g.active_role = 'Preprocessor' and exists (
                select 1 from public.deals x where x.id = o.deal_id and x.preprocessor_user_id = g.uid))
          or (g.active_role in ('Sales Person', 'Sales Team') and exists (
                select 1 from public.deal_sales_people s where s.deal_id = o.deal_id and s.sales_id = g.uid))
          or exists (
                select 1 from public.deal_participants p
                where p.deal_id = o.deal_id and p.contact_id = g.contact_id)
        )
      )
      and (
        o.folder_id is null
        or (
          f.id is not null
          and (not f.staff_only or g.staffish)
          and (
            f.scope = 'library'
            or g.is_admin
            or coalesce(g.active_role in ('Processor', 'Sales Team', 'Transaction Coordinator'), false)
            or (g.active_role = 'Preprocessor' and exists (
                  select 1 from public.deals x where x.id = f.deal_id and x.preprocessor_user_id = g.uid))
            or (g.active_role in ('Sales Person', 'Sales Team') and exists (
                  select 1 from public.deal_sales_people s where s.deal_id = f.deal_id and s.sales_id = g.uid))
            or exists (
                  select 1 from public.deal_participants p
                  where p.deal_id = f.deal_id and p.contact_id = g.contact_id)
          )
        )
      )
      and (
        not o.wire_instructions
        or o.uploaded_by = g.uid
        or g.staffish
        or (o.deal_id is not null and g.uid is not null and 'Client-Buyer' = any (r.roles))
      )
      and not (
        o.deal_id is not null
        and 'Buyer Agent' = any (r.roles)
        and not ('Client-Buyer' = any (r.roles))
        and not g.staffish
        and private.buyer_agent_blocked(o.title_doc_kind, o.name, o.doc_type, o.wire_instructions)
      )
      and case
        when o.deal_id is not null
         and o.uploaded_by is distinct from g.uid
         and g.uid is not null
         and not g.staffish
         and coalesce(r.viewer_side <> 'staff', false)
         and 'Client-Buyer' = any (r.roles)
         and not (r.roles && array['Buyer Agent', 'Listing Agent']::text[])
        then (o.shared_with_client and o.visibility <> 'staff')
          or (
            (
              o.uploaded_by = g.uid
              or up.side = 'staff'
              or exists (
                select 1
                from public.signature_requests req
                join public.signature_signers sig on sig.request_id = req.id
                where req.document_id = o.id and sig.profile_id = g.uid
              )
            )
            and (
              o.uploaded_by = g.uid
              or g.staffish
              or o.visibility = 'all'
              or (o.visibility in ('buyer', 'seller') and o.visibility = case r.one_role
                    when 'Buyer Agent' then 'buyer'
                    when 'Client-Buyer' then 'buyer'
                    when 'Listing Agent' then 'seller'
                    when 'Client-Seller' then 'seller'
                  end)
            )
          )
        when o.deal_id is not null
         and o.uploaded_by is distinct from g.uid
         and g.uid is not null
         and not g.staffish
         and coalesce(r.viewer_side <> 'staff', false)
         and 'Client-Seller' = any (r.roles)
         and not ('Client-Buyer' = any (r.roles))
         and not (r.roles && array['Buyer Agent', 'Listing Agent']::text[])
        then (o.shared_with_seller and o.visibility <> 'staff')
          or (
            (
              o.uploaded_by = g.uid
              or coalesce(up.side, '') in ('staff', 'seller')
              or exists (
                select 1
                from public.signature_requests req
                join public.signature_signers sig on sig.request_id = req.id
                where req.document_id = o.id and sig.profile_id = g.uid
              )
            )
            and (
              o.uploaded_by = g.uid
              or g.staffish
              or o.visibility = 'all'
              or (o.visibility in ('buyer', 'seller') and o.visibility = case r.one_role
                    when 'Buyer Agent' then 'buyer'
                    when 'Client-Buyer' then 'buyer'
                    when 'Listing Agent' then 'seller'
                    when 'Client-Seller' then 'seller'
                  end)
            )
          )
        else (
          o.uploaded_by = g.uid
          or g.staffish
          or o.visibility = 'all'
          or (o.visibility in ('buyer', 'seller') and o.visibility = case r.one_role
                when 'Buyer Agent' then 'buyer'
                when 'Client-Buyer' then 'buyer'
                when 'Listing Agent' then 'seller'
                when 'Client-Seller' then 'seller'
              end)
        )
        or (
          o.title_doc_kind = 'title_commitment'
          and o.deal_id is not null
          and 'Buyer Agent' = any (r.roles)
          and not g.staffish
          and not private.buyer_agent_blocked(o.title_doc_kind, o.name, o.doc_type, o.wire_instructions)
        )
      end
  )
$function$

CREATE OR REPLACE FUNCTION private.documents_are_permanent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin raise exception 'Documents cannot be deleted' using errcode = 'P0001'; end $function$

CREATE OR REPLACE FUNCTION private.documents_folder_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare f public.folders;
begin
  if new.folder_id is null then return new; end if;
  select * into f from public.folders where id = new.folder_id;
  if f.scope = 'deal' and f.deal_id is distinct from new.deal_id then raise exception 'That folder is not part of this order'; end if;
  if f.scope = 'library' and new.deal_id is not null then raise exception 'Order documents cannot go into a Library folder'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.documents_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.deal_id is distinct from old.deal_id or new.name <> old.name or new.storage_path is distinct from old.storage_path or new.uploaded_by <> old.uploaded_by or new.size_bytes <> old.size_bytes then
    raise exception 'Only description, visibility and folder of a document can change'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.e2e_gmail_admin(p_actor uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select exists (
    select 1 from public.profiles p
    where p.id = p_actor and p.status = 'active' and p.is_admin is true and p.is_demo is false
      and p.role in ('Admin', 'Super admin')) $function$

CREATE OR REPLACE FUNCTION private.e2e_gmail_vault_get(p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select d.decrypted_secret from vault.decrypted_secrets d
   where d.name = p_name and p_name in ('e2e_gmail_client_id', 'e2e_gmail_client_secret', 'e2e_gmail_refresh_token') $function$

CREATE OR REPLACE FUNCTION private.e2e_gmail_vault_put(p_name text, p_value text, p_description text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_id uuid;
begin
  if p_name not in ('e2e_gmail_client_id', 'e2e_gmail_client_secret', 'e2e_gmail_refresh_token') then
    raise exception 'refusing: that vault name is not an e2e gmail secret';
  end if;
  if coalesce(p_value, '') = '' then raise exception 'refusing: empty secret'; end if;
  select s.id into v_id from vault.secrets s where s.name = p_name;
  if v_id is null then perform vault.create_secret(p_value, p_name, p_description);
  else perform vault.update_secret(v_id, p_value, p_name, p_description); end if;
end $function$

CREATE OR REPLACE FUNCTION private.effective_uid()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  actor text;
  found uuid;
begin
  actor := coalesce(auth.uid()::text, '');
  if current_setting('cla.effective_uid_for', true) is not distinct from actor
     and current_setting('cla.effective_uid_for', true) is not null then
    return nullif(current_setting('cla.effective_uid', true), '')::uuid;
  end if;
  select coalesce(
    (select s.target_id
       from private.view_as_sessions s
       join public.profiles a on a.id = s.actor_id
      where s.actor_id = auth.uid()
        and a.role = 'Super admin' and a.is_admin and a.status = 'active'
        and s.stopped_at is null
        and s.expires_at > pg_catalog.now()),
    auth.uid())
  into found;
  perform set_config('cla.effective_uid_for', actor, true);
  perform set_config('cla.effective_uid', coalesce(found::text, ''), true);
  return found;
end
$function$

