CREATE OR REPLACE FUNCTION private.entity_attorney_authorized(p_profile uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select exists (select 1 from public.entity_review_attorneys a join public.profiles p on p.id = a.profile_id
    where a.profile_id = p_profile and a.active and a.retired_at is null and p.status = 'active' and a.assignment_role in ('attorney', 'backup')) $function$

CREATE OR REPLACE FUNCTION private.entity_doc_list()
 RETURNS TABLE(key text, label text, optional boolean, pos integer)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  values ('entity_doc_operating', 'Operating Agreement', false, 1), ('entity_doc_amendments', 'Amendments to the Operating Agreement (if any)', true, 2),
         ('entity_doc_good_standing', 'Certificate of Good Standing', false, 3), ('entity_doc_articles', 'Articles of Organization', false, 4) $function$

CREATE OR REPLACE FUNCTION private.entity_prefill(e participant_entities)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  update public.tasks t set form_data = jsonb_strip_nulls(jsonb_build_object('is_entity', true, 'entity_name', e.name,
      'entity_type', nullif(e.entity_type, ''), 'entity_rep_name', nullif(e.rep_name, ''), 'entity_rep_title', nullif(e.rep_title, ''),
      'entity_rep_phone', nullif(e.rep_phone, ''), 'entity_rep_email', nullif(e.rep_email, '')))
    from public.task_templates tp
    where t.participant_id = e.participant_id and tp.id = t.template_id and tp.fields @> '[{"k":"is_entity"}]' and t.kind = 'form' and t.status = 'todo'
      and t.saved_at is null and t.saved_by is null and t.form_data = '{}'::jsonb $function$

CREATE OR REPLACE FUNCTION private.expire_demo_view(p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare tid uuid;
begin
  select s.target_id into tid from private.view_as_sessions s
    where s.actor_id = p_actor and s.stopped_at is null and s.expires_at <= pg_catalog.now();
  if tid is null then return; end if;
  update private.view_as_sessions set stopped_at = pg_catalog.now() where actor_id = p_actor and stopped_at is null;
  insert into private.view_as_audit (actor_id, target_id, action) values (p_actor, tid, 'timeout');
end $function$

CREATE OR REPLACE FUNCTION private.fields_for_role(p_fields jsonb, p_role text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(jsonb_agg(f order by n), '[]'::jsonb) from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) with ordinality as x(f, n)
  where not (f ? 'roles') or (f->'roles') ? p_role $function$

CREATE OR REPLACE FUNCTION private.file_number_prefix(p_state text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case when upper(btrim(coalesce(p_state, ''))) ~ '^[A-Z]{2}$' then upper(btrim(p_state)) else 'MD' end $function$

CREATE OR REPLACE FUNCTION private.file_role_of(pid uuid, d uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case when pr.role is distinct from 'Outside user' then pr.role
    else coalesce((select p.role from public.deal_participants p join public.contacts c on c.id = p.contact_id
                   where p.deal_id = d and c.profile_id = pid and p.role in ('Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller')
                   order by array_position(array['Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller'], p.role) limit 1), 'Outside user') end
  from (select (select role from public.profiles where id = pid) as role) pr $function$

CREATE OR REPLACE FUNCTION private.file_roles_of(pid uuid, d uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select case
    when pr.role is null then '{}'::text[]
    when pr.role <> 'Outside user' then
      coalesce((
        select array_agg(q.r order by q.ord, array_position(array['Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller'], q.r))
        from (
          select pr.role as r, 0 as ord
          union all
          select x.role, 1
          from (
            select distinct p.role
            from public.deal_participants p
            join public.contacts c on c.id = p.contact_id
            where p.deal_id = d and c.profile_id = pid
              and p.role in ('Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller')
          ) x
        ) q
      ), array[pr.role])
    else coalesce((
      select array_agg(x.role order by array_position(array['Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller'], x.role))
      from (
        select distinct p.role
        from public.deal_participants p
        join public.contacts c on c.id = p.contact_id
        where p.deal_id = d and c.profile_id = pid
          and p.role in ('Buyer Agent', 'Listing Agent', 'Client-Buyer', 'Client-Seller')
      ) x
    ), array['Outside user'])
  end
  from (select (select role from public.profiles where id = pid) as role) pr
$function$

CREATE OR REPLACE FUNCTION private.file_title(p_deal uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  with c as (
    select dc.role,
           coalesce(nullif(btrim(e.name), ''), nullif(btrim(dc.last_name), ''), nullif(btrim(dc.first_name), ''), nullif(btrim(dc.company), '')) as n,
           dp.created_at,
           dp.id
    from public.deal_contacts(p_deal) dc
    join public.deal_participants dp on dp.id = dc.participant_id
    left join public.participant_entities e on e.participant_id = dp.id and e.removed_at is null
    where dc.role in ('Client-Buyer', 'Client-Seller')
  ),
  g as (
    select role, n, min(created_at) as m, min(id::text) as i
    from c
    where coalesce(n, '') <> ''
    group by role, n
  )
  select concat_ws(' / ',
    (select string_agg(n, ' & ' order by m, i) from g where role = 'Client-Buyer'),
    (select string_agg(n, ' & ' order by m, i) from g where role = 'Client-Seller'))
$function$

CREATE OR REPLACE FUNCTION private.fmt_phone(v text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare d text := regexp_replace(coalesce(v, ''), '\D', '', 'g');
begin
  if btrim(coalesce(v, '')) = '' then return ''; end if;
  if length(d) = 11 and left(d, 1) = '1' then d := substr(d, 2); end if;
  if length(d) <> 10 then return null; end if;   -- not a phone number
  return substr(d, 1, 3) || '-' || substr(d, 4, 3) || '-' || substr(d, 7, 4); end $function$

