  select f is null or exists (select 1 from public.folders x where x.id = f and (not x.staff_only or private.is_staffish())
                              and (x.scope = 'library' or private.can_access_deal(x.deal_id))) $function$

CREATE OR REPLACE FUNCTION private.form_owner_or_manager(owner uuid)
