      or (d.share_scope = 'employees' and exists (select 1 from public.hr_company_document_shares s where s.document_id = d.id and s.removed_at is null and s.employee_id = e.id))))) $function$

CREATE OR REPLACE FUNCTION private.hr_doc_hist(p_table text, p_row uuid, p_emp uuid, p_field text, p_old text, p_new text, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare nm text; begin
  select btrim(first_name || ' ' || last_name) into nm from public.profiles where id = private.effective_uid();
  insert into public.hr_change_history (table_name, row_id, employee_id, field, old_value, new_value, action, changed_by, changed_by_name)
    values (p_table, p_row, p_emp, p_field, coalesce(p_old, ''), coalesce(p_new, ''), p_action, private.effective_uid(), coalesce(nm, ''));
end $function$

CREATE OR REPLACE FUNCTION private.hr_employee_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare me uuid := private.effective_uid(); k text; o jsonb := to_jsonb(old); n jsonb := to_jsonb(new); m public.hr_employees; i int := 0;
begin
  if tg_op = 'INSERT' then
    new.email := lower(btrim(new.email)); new.employee_code := upper(btrim(new.employee_code));
    if new.created_by is null then new.created_by := me; end if;
    if me is not null and not private.hr_admin() then raise exception 'Only HR managers and Super admins add employees.' using errcode = '42501'; end if;
    return new; end if;
  new.email := lower(btrim(new.email)); new.employee_code := upper(btrim(new.employee_code)); n := to_jsonb(new);
  if new.id <> old.id or new.created_at is distinct from old.created_at or new.created_by is distinct from old.created_by then raise exception 'id / created are never changed.' using errcode = '42501'; end if;
  if me is not null then
    -- what changed beyond the employee's own columns?
    for k in select key from jsonb_object_keys(n) key where key not in ('updated_at', 'updated_by') and not (key = any (private.hr_self_columns())) loop
      if (o -> k) is distinct from (n -> k) then
        -- accepting an invite: the new login links itself to its own record, nothing else
        if k = 'profile_id' and old.profile_id is null and new.profile_id = me
          and exists (select 1 from public.hr_invites v where v.employee_id = new.id and v.accepted_profile = me and v.accepted_at is not null) then continue; end if;
        if not private.hr_admin() then raise exception 'You can only edit your own phone, address and emergency contact.' using errcode = '42501'; end if;
        if not private.hr_is_super() and old.profile_id = me then raise exception 'HR managers cannot change the HR fields on their own record; a Super admin does that.' using errcode = '42501'; end if;
        if old.archived_at is not null and k <> 'archived_at' and k <> 'archived_by' then raise exception 'Restore the employee before editing.' using errcode = 'P0001'; end if;
      end if;
    end loop;
    if not private.hr_admin() and (old.profile_id is distinct from me or old.archived_at is not null) and not (old.profile_id is null and new.profile_id = me) then
      raise exception 'You can only edit your own record.' using errcode = '42501'; end if;
  end if;
  -- integrity, for everyone
  if new.reporting_to is not null and new.reporting_to is distinct from old.reporting_to then
    if not exists (select 1 from public.hr_employees z where z.id = new.reporting_to and z.archived_at is null) then raise exception 'Reporting To must be an active employee.' using errcode = '22023'; end if;
    m.reporting_to := new.reporting_to;
    while m.reporting_to is not null and i < 60 loop
      if m.reporting_to = new.id then raise exception 'That would make a reporting loop.' using errcode = '22023'; end if;
      select z.reporting_to into m.reporting_to from public.hr_employees z where z.id = m.reporting_to; i := i + 1; end loop;
  end if;
  if new.department_id is distinct from old.department_id and new.department_id is not null and exists (select 1 from public.hr_departments d where d.id = new.department_id and d.archived_at is not null)
    then raise exception 'Pick an active department.' using errcode = '22023'; end if;
  if new.designation_id is distinct from old.designation_id and new.designation_id is not null and exists (select 1 from public.hr_designations d where d.id = new.designation_id and d.archived_at is not null)
    then raise exception 'Pick an active designation.' using errcode = '22023'; end if;
  if new.archived_at is not null and old.archived_at is null then
    if exists (select 1 from public.hr_employees z where z.reporting_to = new.id and z.archived_at is null) then raise exception 'Move this person''s direct reports to another manager first.' using errcode = 'P0001'; end if;
    if new.profile_id = me then raise exception 'You cannot archive your own record.' using errcode = 'P0001'; end if;
  end if;
  if n is distinct from o then new.updated_at := now(); new.updated_by := coalesce(me, new.updated_by); end if;
  return new;
end $function$

