CREATE OR REPLACE FUNCTION private.hr_is_manager()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(private.hr_open() and exists (select 1 from public.hr_role_assignments a where a.employee_id = private.hr_my_employee() and a.role = 'hr_manager' and a.removed_at is null), false) $function$

CREATE OR REPLACE FUNCTION private.hr_is_super()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(private.is_super_admin(), false) $function$

CREATE OR REPLACE FUNCTION private.hr_lookup_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare col text := case when tg_table_name = 'hr_departments' then 'department_id' else 'designation_id' end; busy boolean;
begin
  if private.effective_uid() is not null and not private.hr_admin() then raise exception 'Only HR managers and Super admins change departments and designations.' using errcode = '42501'; end if;
  new.name := btrim(new.name);
  if tg_op = 'INSERT' then new.created_by := coalesce(new.created_by, private.effective_uid()); return new; end if;
  if new.id <> old.id or new.created_at is distinct from old.created_at then raise exception 'id / created are never changed.' using errcode = '42501'; end if;
  if new.archived_at is not null and old.archived_at is null then
    execute format('select exists (select 1 from public.hr_employees where %I = $1 and archived_at is null)', col) into busy using new.id;
    if busy then raise exception 'Move the active employees out of it before archiving.' using errcode = 'P0001'; end if;
    new.archived_by := coalesce(private.effective_uid(), new.archived_by); end if;
  if new.archived_at is null then new.archived_by := null; end if;
  new.updated_at := now(); new.updated_by := coalesce(private.effective_uid(), new.updated_by); return new;
end $function$

