 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce(array_agg(f->>'k'), '{}') from public.task_templates t, jsonb_array_elements(t.fields) f where t.id = p_template and coalesce((f->>'mask')::boolean, false) $function$

