CREATE OR REPLACE FUNCTION private.message_html_safe(h text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select h = '' or (h !~* '<\s*/?\s*(script|style|iframe|object|embed|svg|img|form|input|span|font|table)\b' and h !~* '\son[a-z]+\s*=' and h !~* 'javascript:' and h !~* 'style\s*=') $function$

CREATE OR REPLACE FUNCTION private.message_readable(m uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select exists (
    select 1 from public.messages msg join public.threads th on th.id = msg.thread_id
    where msg.id = m and private.thread_member(th.id)
      and (not th.staff_coordinated or private.is_staffish() or msg.author_id = private.effective_uid()
           or private.person_side(msg.author_id, th.deal_id) = 'staff'
           or private.person_side(msg.author_id, th.deal_id) is not distinct from private.my_side(th.deal_id))) $function$

