 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin perform pg_advisory_xact_lock(hashtext(new.deal_id::text || new.contact_id::text)); return new; end $function$

CREATE OR REPLACE FUNCTION private.participant_tc_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.role = 'Transaction Coordinator' and not exists (
       select 1 from public.contacts c join public.profiles p on p.id = c.profile_id
       where c.id = new.contact_id
         and p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin')
         and p.status = 'active') then
    raise exception 'Only an active staff login can be the Transaction Coordinator on an order.' using errcode = 'P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.participant_visible(d uuid, prole text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.can_access_deal(d) and not (private.deal_role(d) in ('Client-Buyer', 'Client-Seller') and prole like 'Client-%' and prole <> private.deal_role(d))
     and not (prole = 'Listing Agent' and private.is_pure_buyer(d))
     and not (prole = 'Buyer Agent' and private.is_pure_seller(d)) $function$

CREATE OR REPLACE FUNCTION private.payoff_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare j jsonb;
begin
  if tg_op = 'DELETE' then raise exception 'Payoff records are never deleted. Retire them instead.' using errcode = 'P0001'; end if;
  j := to_jsonb(new);
  if tg_table_name = 'deal_payoff_notes' and coalesce(j ->> 'body', '') ~ '\d{9,17}' and coalesce(j ->> 'body', '') ~* '(routing|aba|account|acct|wire)' then
    raise exception 'Notes never hold wire instructions or bank account numbers.' using errcode = '23514'; end if;
  if tg_op = 'INSERT' then
    if j ? 'created_by' then new := jsonb_populate_record(new, jsonb_build_object('created_by', private.effective_uid(), 'created_at', now())); end if;
    if j ? 'updated_by' and tg_table_name <> 'deal_payoff_notes' then new := jsonb_populate_record(new, jsonb_build_object('updated_by', private.effective_uid(), 'updated_at', now())); end if;
    if j ? 'retired_at' then new := jsonb_populate_record(new, jsonb_build_object('retired_at', null)); end if;
    return new; end if;
  if (j ? 'deal_id') and (to_jsonb(old) ->> 'deal_id') is distinct from (j ->> 'deal_id') then raise exception 'A payoff record cannot move to another order.' using errcode = 'P0001'; end if;
  if (j ? 'created_by') and ((to_jsonb(old) -> 'created_by') is distinct from (j -> 'created_by') or (to_jsonb(old) -> 'created_at') is distinct from (j -> 'created_at')) then
    raise exception 'Who created a record never changes.' using errcode = 'P0001'; end if;
  if (j ? 'retired_at') and (to_jsonb(old) ->> 'retired_at') is not null and (j ->> 'retired_at') is not null and (j - array['retired_at', 'retired_by', 'updated_at', 'updated_by']) <> (to_jsonb(old) - array['retired_at', 'retired_by', 'updated_at', 'updated_by']) then
    raise exception 'This record is retired.' using errcode = 'P0001'; end if;
  if j ? 'retired_by' and (to_jsonb(old) ->> 'retired_at') is null and (j ->> 'retired_at') is not null then new := jsonb_populate_record(new, jsonb_build_object('retired_by', private.effective_uid(), 'retired_at', now())); end if;
  if j ? 'updated_by' then new := jsonb_populate_record(new, jsonb_build_object('updated_by', private.effective_uid(), 'updated_at', now())); end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.payoff_items_ok(a jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare it jsonb;
begin
  if a is null then return true; end if;
  if jsonb_typeof(a) <> 'array' or jsonb_array_length(a) > 12 then return false; end if;
  for it in select jsonb_array_elements(a) loop
    if not private.payoff_obj_ok(it, array['label', 'amount'], 80) then return false; end if;
    if it ? 'amount' and jsonb_typeof(it -> 'amount') <> 'null' and not (jsonb_typeof(it -> 'amount') = 'number' and abs((it ->> 'amount')::numeric) <= 100000000) then return false; end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.payoff_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else null end; v_new jsonb := to_jsonb(new); v_action text; v_id uuid; v_what text;
begin
  if v_old is not null and (v_old - array['updated_at', 'updated_by']) = (v_new - array['updated_at', 'updated_by']) then return null; end if;
  v_action := case when tg_op = 'INSERT' then 'added' when v_new ? 'retired_at' and v_old ->> 'retired_at' is null and v_new ->> 'retired_at' is not null then 'retired'
                   when v_new ? 'retired_at' and v_old ->> 'retired_at' is not null and v_new ->> 'retired_at' is null then 'restored' else 'edited' end;
  v_id := coalesce((v_new ->> 'id')::uuid, (v_new ->> 'deal_id')::uuid);
  v_what := case tg_table_name when 'deal_payoffs' then 'Payoff ' || (v_new ->> 'position') when 'deal_payoff_notes' then 'Note (' || (v_new ->> 'section') || ')'
                               when 'deal_payoff_info' then 'Order info' else 'Other contact (' || (v_new ->> 'contact_type') || ')' end;
  insert into public.deal_payoff_log (deal_id, what, row_id, action, changed_by, old_row, new_row) values ((v_new ->> 'deal_id')::uuid, v_what, v_id, v_action, private.effective_uid(), v_old, v_new);
  return null;
end $function$

