CREATE OR REPLACE FUNCTION private.processor_backfill_fake(p_deal uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select exists (
    select 1 from public.deals d
    where d.id = p_deal
      and (
        coalesce(d.is_demo, false)
        or coalesce(d.notes, '') ~* 'fake file|test portal|sample only'
        or coalesce(d.street, '') ~* 'fake|sample|test lane|test road|test street'
        or coalesce(d.file_number, '') ~* '^DEMO-'
        or (
          coalesce(d.file_number, '') ~ '^[A-Z]{2}-[0-9]{2}-[0-9]+$'
          and exists (
            select 1 from public.deal_participants dp
            join public.contacts c on c.id = dp.contact_id
            where dp.deal_id = d.id
              and coalesce(c.email, '') ~* '@example\.(test|com)$|\.example\.test$'
          )
          and not exists (
            select 1 from public.deal_participants dp
            join public.contacts c on c.id = dp.contact_id
            where dp.deal_id = d.id
              and btrim(coalesce(c.email, '')) <> ''
              and coalesce(c.email, '') !~* '@example\.(test|com)$'
              and coalesce(c.email, '') !~* '\.example\.test$'
          )
        )
      )
  );
$function$

CREATE OR REPLACE FUNCTION private.processor_party_contact(p_profile uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare p public.profiles; cid uuid; v_email text;
begin
  select * into p from public.profiles where id = p_profile;
  if p.id is null then
    raise exception 'The Processor on an order must be an active staff login.' using errcode = 'P0001';
  end if;
  select c.id into cid from public.contacts c where c.profile_id = p.id order by c.id limit 1;
  if cid is not null then return cid; end if;
  v_email := nullif(lower(btrim(coalesce(p.email, ''))), '');
  if v_email is not null then
    select c.id into cid from public.contacts c
     where c.profile_id is null
       and nullif(lower(btrim(coalesce(c.email, ''))), '') = v_email
     order by c.id limit 1;
    if cid is not null then
      update public.contacts
         set profile_id = p.id,
             first_name = coalesce(nullif(btrim(first_name), ''), coalesce(p.first_name, '')),
             last_name = coalesce(nullif(btrim(last_name), ''), coalesce(p.last_name, '')),
             is_demo = coalesce(p.is_demo, false)
       where id = cid;
      return cid;
    end if;
  end if;
  begin
    insert into public.contacts (id, profile_id, first_name, last_name, email, phone, company, is_demo)
    values (gen_random_uuid(), p.id, coalesce(p.first_name, ''), coalesce(p.last_name, ''), coalesce(v_email, ''),
            coalesce(p.phone, ''), '', coalesce(p.is_demo, false))
    returning id into cid;
  exception when unique_violation then
    raise exception 'That staff login shares an email with a different contact. Pick the staff login from the list.' using errcode = 'P0001';
  end;
  return cid;
end $function$

CREATE OR REPLACE FUNCTION private.processor_staff_id(p_contact uuid, p_deal uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_profile uuid; v_role text; v_status text; v_demo boolean; v_deal_demo boolean;
begin
  select c.profile_id, p.role, p.status, p.is_demo
    into v_profile, v_role, v_status, v_demo
    from public.contacts c
    left join public.profiles p on p.id = c.profile_id
   where c.id = p_contact;
  if v_profile is null or v_role is null then
    return null;
  end if;
  if v_role = 'Outside user' then
    raise exception 'An outside user cannot be added as CLA staff. Pick Buyer Agent, Listing Agent, Client-Buyer or Client-Seller.' using errcode = 'P0001';
  end if;
  if v_status is distinct from 'active'
     or v_role not in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator', 'Admin', 'Super admin') then
    raise exception 'The Processor on an order must be an active staff login.' using errcode = 'P0001';
  end if;
  select coalesce(d.is_demo, false) into v_deal_demo from public.deals d where d.id = p_deal;
  if coalesce(v_demo, false) is distinct from coalesce(v_deal_demo, false) then
    raise exception 'A real order cannot use a demo login, and a demo order cannot use a real login.' using errcode = 'P0001';
  end if;
  return v_profile;
end $function$

CREATE OR REPLACE FUNCTION private.profile_ensure_tc_contact()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare new_contact uuid;
begin
  if new.role = 'Transaction Coordinator' and new.status = 'active'
     and not exists (select 1 from public.contacts c where c.profile_id = new.id)
     and not exists (
       select 1 from public.contacts c
        where c.email <> '' and coalesce(new.email, '') <> '' and lower(c.email) = lower(new.email)
     ) then
    insert into public.contacts (profile_id, first_name, last_name, email, phone, company, is_demo)
    values (new.id, coalesce(new.first_name, ''), coalesce(new.last_name, ''), coalesce(new.email, ''),
            coalesce(new.phone, ''), '', coalesce(new.is_demo, false))
    returning id into new_contact;
    insert into private.migration_20261110103000_tc_contacts (contact_id) values (new_contact);
  end if;
  return new;
exception when unique_violation then
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.profile_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.id <> old.id or new.email <> old.email then raise exception 'id and email are changed by the auth provider only'; end if;
  if old.status = 'removed' and private.effective_uid() is not null then raise exception 'This user was removed'; end if;
  if new.role in ('Admin', 'Super admin') and new.role = old.role and old.is_admin and not new.is_admin and new.status <> 'removed' then
    raise exception 'An %-role user keeps Admin access; change the role first', new.role; end if;
  if new.role in ('Admin', 'Super admin') and new.status <> 'removed' then new.is_admin := true;
  elsif old.role in ('Admin', 'Super admin') and new.role not in ('Admin', 'Super admin') and new.is_admin = old.is_admin then new.is_admin := false; end if;
  if private.effective_uid() is not null and (new.role <> old.role or new.status <> old.status or new.is_admin <> old.is_admin) then
    if not private.is_admin() then raise exception 'Only an Admin can change role, status or Admin access'; end if;
    if new.role = 'Super admin' and old.role <> 'Super admin' and not private.is_super_admin() then
      raise exception 'Only a Super admin can grant the Super admin role.'; end if;
    if old.role = 'Super admin' and not private.is_super_admin() then
      raise exception 'Only a Super admin can change, suspend or delete a Super admin.'; end if;
    if new.id = private.effective_uid() and (new.status <> old.status or new.is_admin <> old.is_admin) then raise exception 'You cannot change your own status or Admin access'; end if;
    if new.status = 'removed' and coalesce(current_setting('cla.removing_user', true), ''::text) <> 'on' then raise exception 'Use admin_delete_user to delete a user'; end if;
  end if;
  if old.is_admin and old.status = 'active' and not (new.is_admin and new.status = 'active')
     and not exists (select 1 from public.profiles p where p.is_admin and p.status = 'active' and p.id <> old.id) then
    raise exception 'There must always be at least one Admin'; end if;
  if old.role = 'Super admin' and old.status = 'active' and not (new.role = 'Super admin' and new.status = 'active')
     and not exists (select 1 from public.profiles p where p.role = 'Super admin' and p.is_admin and p.status = 'active' and p.id <> old.id) then
    raise exception 'There must always be at least one Super admin'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.profile_insert_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  -- The bootstrap flag is honored only when no user JWT is present (operator or service_role).
  -- An authenticated session cannot set the flag and insert its own Super admin.
  if pg_catalog.current_setting('cla.bootstrap_admin', true) = 'on' and private.effective_uid() is null then
    if new.role <> 'Super admin' then raise exception 'Bootstrap can only create the first Super admin.' using errcode = '42501'; end if;
    if exists (select 1 from public.profiles where role = 'Super admin' and status <> 'removed') then
      raise exception 'A Super admin already exists.' using errcode = '42501'; end if;
    new.is_admin := true;
    return new;
  end if;
  if new.role = 'Super admin' and private.effective_uid() is not null and not private.is_super_admin() then
    raise exception 'Only a Super admin can grant the Super admin role.' using errcode = 'P0001'; end if;
  if new.role in ('Admin', 'Super admin') then new.is_admin := true; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.profile_insert_staff_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if pg_catalog.current_setting('cla.bootstrap_admin', true) = 'on' and private.effective_uid() is null then return new; end if;
  if private.effective_uid() is not null and new.role <> 'Outside user' and not private.is_admin() then
    raise exception 'Only an Admin can create a CLA staff login.' using errcode = 'P0001'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.profile_sales_links_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.status = 'removed' then
    if old.status <> 'removed' then delete from public.client_sales_reps where client_id = new.id or sales_id = new.id; end if;
    return new; end if;
  if new.role <> old.role then
    if new.role <> 'Outside user' and exists (select 1 from public.client_sales_reps where client_id = new.id) then
      raise exception 'This client is linked to salespeople. Remove those links before changing the account type.' using errcode = 'P0001'; end if;
    if new.role not in ('Sales Person', 'Sales Team') and exists (select 1 from public.client_sales_reps where sales_id = new.id) then
      raise exception 'This salesperson is linked to clients. Remove those links before changing the role.' using errcode = 'P0001'; end if;
  end if;
  return new; end $function$

