 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.title_on() and coalesce(private.is_admin() or private.me_role() in ('Processor', 'Preprocessor', 'Transaction Coordinator'), false) and private.can_access_deal(d) $function$

