 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select coalesce((select enabled from private.features where name = 'title'), false) $function$

CREATE OR REPLACE FUNCTION private.title_reader(d uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select private.title_on() and coalesce(private.is_admin() or private.me_role() in ('Processor', 'Preprocessor', 'Transaction Coordinator', 'Sales Person', 'Sales Team'), false) and private.can_access_deal(d) $function$

CREATE OR REPLACE FUNCTION private.title_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'INSERT' then new.created_at := coalesce(new.created_at, now()); new.created_by := coalesce(new.created_by, private.effective_uid()); end if;
  if tg_op = 'UPDATE' then new.created_at := old.created_at; new.created_by := old.created_by; end if;
  new.updated_at := now(); new.updated_by := coalesce(private.effective_uid(), new.updated_by);
  if new.deleted_at is not null and new.deleted_by is null then new.deleted_by := private.effective_uid(); end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.touch_settlement_token_expiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'INSERT'
     or new.buyer_token_hash is distinct from old.buyer_token_hash
     or new.seller_token_hash is distinct from old.seller_token_hash then
    new.token_expires_at := pg_catalog.now() + interval '14 days';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.trg_agent_tasks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin perform private.make_agent_tasks(new.id); return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_client_share_visibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare role text; side text;
begin
  role := private.deal_role(new.deal_id);
  if role in ('Client-Buyer', 'Client-Seller') and new.visibility in ('staff', 'all') then
    side := private.side_of(role);
    if side in ('buyer', 'seller') then new.visibility := side; end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.trg_deal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'INSERT' then
    perform private.log_activity(new.id, 'deal.created', 'deal', new.id, 'Order ' || new.file_number || ' opened');
    insert into public.tasks (deal_id, title, assigned_role, created_by) values (new.id, 'Collect executed contract', 'Processor', new.created_by);
    insert into public.folders (scope, deal_id, name, created_by)
      select 'deal', new.id, n, new.created_by from unnest(array['Contract & addenda', 'IDs & personal', 'Lender & payoff', 'HOA', 'Closing']) n;
  else
    if new.stage <> old.stage then perform private.log_activity(new.id, 'stage.changed', 'deal', new.id, 'Stage set to ' || new.stage); end if;
    if new.status <> old.status then perform private.log_activity(new.id, 'status.changed', 'deal', new.id, 'Status set to ' || new.status); end if;
    if new.closing_date is distinct from old.closing_date then perform private.log_activity(new.id, 'closing.date', 'deal', new.id, 'Closing date set to ' || coalesce(new.closing_date::text, 'none')); end if;
  end if; return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_deal_processor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_name text;
begin
  if new.processor_id is not distinct from old.processor_id then return new; end if;
  if new.processor_id is null then
    perform private.log_activity(new.id, 'deal.processor', 'deal', new.id, 'Processor unassigned');
    return new;
  end if;
  select coalesce(nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), ''), nullif(p.email, ''), 'a user')
    into v_name from public.profiles p where p.id = new.processor_id;
  perform private.log_activity(new.id, 'deal.processor', 'deal', new.id, 'Processor set to ' || coalesce(v_name, 'a user'));
  perform private.notify(array[new.processor_id], 'processor', new.id,
    'You are now the Processor on ' || coalesce(nullif(new.file_number, ''), 'an order'), '#/deals/' || new.id::text);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.trg_deal_tc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_name text;
begin
  if new.tc_user_id is not distinct from old.tc_user_id then return new; end if;
  if new.tc_user_id is null then
    perform private.log_activity(new.id, 'deal.tc', 'deal', new.id, 'Transaction Coordinator unassigned');
    return new;
  end if;
  select coalesce(nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), ''), nullif(p.email, ''), 'a user')
    into v_name from public.profiles p where p.id = new.tc_user_id;
  perform private.log_activity(new.id, 'deal.tc', 'deal', new.id, 'Transaction Coordinator set to ' || coalesce(v_name, 'a user'));
  if coalesce(current_setting('cla.tc_backfill', true), '') <> 'on' then
    perform private.notify(array[new.tc_user_id], 'tc', new.id,
      'You are now the Transaction Coordinator on ' || coalesce(nullif(new.file_number, ''), 'an order'), '#/deals/' || new.id::text);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.trg_doc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  perform private.log_activity(new.deal_id, 'document.uploaded', 'document', new.id, 'Uploaded ' || new.name);
  if new.deal_id is not null then
    perform private.notify(array(select x from unnest(private.deal_profiles(new.deal_id)) x
      where exists (select 1 from public.profiles p where p.id = x and (p.role in ('Processor', 'Preprocessor', 'Sales Person', 'Sales Team', 'Transaction Coordinator')
                    or new.visibility = 'all' or new.visibility = private.side_of(private.file_role_of(x, new.deal_id))))
        and (not new.wire_instructions or private.person_wire_allowed(x, new.deal_id))
        and (not private.person_pure_buyer(x, new.deal_id) or private.doc_readable_by(x, new.id))
        and (not private.person_pure_seller(x, new.deal_id) or private.doc_readable_by(x, new.id))),
      'document', new.deal_id, 'New document: ' || new.name, '#/deals/' || new.deal_id || '/documents'); end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_doc_share_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'INSERT' then
    if private.effective_uid() is not null and (new.shared_with_client or new.shared_with_client_by is not null or new.shared_with_client_at is not null) then
      new.shared_with_client := false; new.shared_with_client_by := null; new.shared_with_client_at := null; end if;
    if private.effective_uid() is not null and (new.shared_with_seller or new.shared_with_seller_by is not null or new.shared_with_seller_at is not null) then
      new.shared_with_seller := false; new.shared_with_seller_by := null; new.shared_with_seller_at := null; end if;
    return new; end if;
  if ((new.shared_with_client, new.shared_with_client_by, new.shared_with_client_at) is distinct from (old.shared_with_client, old.shared_with_client_by, old.shared_with_client_at)
      or (new.shared_with_seller, new.shared_with_seller_by, new.shared_with_seller_at) is distinct from (old.shared_with_seller, old.shared_with_seller_by, old.shared_with_seller_at))
     and private.effective_uid() is not null and coalesce(current_setting('cla.doc_share', true), '') <> 'on' then
    raise exception 'Use Share with buyer / Share with seller (CLA Title staff) to change this.' using errcode = '42501'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_doc_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if private.effective_uid() is not null and new.doc_type <> '' and new.deal_id is not null and not private.is_staffish()
     and not (new.doc_type = any (private.doc_types(coalesce(private.my_side(new.deal_id), 'none')))) then
    raise exception 'Pick a document type from the list.' using errcode = '42501'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_doc_wire()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if tg_op = 'UPDATE' and new.wire_instructions is distinct from old.wire_instructions and private.effective_uid() is not null and not private.is_staffish() then
    raise exception 'Only CLA Title staff can mark wire instructions.' using errcode = '42501'; end if;
  if tg_op = 'INSERT' and new.wire_instructions and private.effective_uid() is not null and not private.is_staffish() then new.wire_instructions := false; end if;
  if private.wire_name(new.name) then new.wire_instructions := true; end if;   -- a file named wire instructions stays buyer-only
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_hr_designation_portal_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  mapped text;
  old_mapped text;
begin
  mapped := private.hr_portal_role_for(new.designation_id);
  if tg_op = 'UPDATE' then
    old_mapped := private.hr_portal_role_for(old.designation_id);
    if old.profile_id is not null and old.profile_id is distinct from new.profile_id then
      perform private.hr_apply_portal_role(old.profile_id, 'Employee', true);
    end if;
  end if;
  if new.archived_at is not null then
    if new.profile_id is not null then
      perform private.hr_apply_portal_role(new.profile_id, 'Employee', true);
    end if;
    return new;
  end if;
  if new.profile_id is null then
    return new;
  end if;
  if mapped in ('Processor', 'Preprocessor', 'Sales Person', 'Transaction Coordinator') then
    perform private.hr_apply_portal_role(new.profile_id, mapped, false);
  elsif tg_op = 'UPDATE'
    and old_mapped in ('Processor', 'Preprocessor', 'Sales Person', 'Transaction Coordinator')
    and mapped is distinct from old_mapped then
    perform private.hr_apply_portal_role(new.profile_id, 'Employee', true);
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.trg_lender_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin new.lender_email := lower(btrim(coalesce(new.lender_email, '')));
  if new.lender_email <> '' and new.lender_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Lender email is not valid.' using errcode = '23514'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_lender_phone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin new.lender_phone := private.phone_or_raise(new.lender_phone, 'Lender phone'); return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare d uuid; s text;
begin
  select deal_id, subject into d, s from public.threads where id = new.thread_id;
  perform private.notify(array(select profile_id from public.thread_participants where thread_id = new.thread_id), 'message', d, 'New message: ' || s, '#/deals/' || d || '/messages/' || new.thread_id);
