CREATE OR REPLACE FUNCTION private.trg_msg_wire()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if private.wire_text(coalesce(new.body, '') || ' ' || coalesce(new.body_html, '')) and private.thread_has_non_wire(new.thread_id) then
    raise exception 'Wire instructions go to the buyer only (and CLA Title staff). Real estate agents never receive them.' using errcode = '42501'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_participant_copies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare owner uuid; n int;
begin
  select profile_id into owner from public.contacts where id = new.contact_id;
  insert into public.tasks (deal_id, title, description, assigned_role, status, due_date, due_overridden, created_by, kind, participant_id, owner_profile_id, template_id, template_code, template_version, lane, audiences)
  select new.deal_id, t.title, t.description, new.role, 'todo', (case coalesce(t.due_anchor, 'opened') when 'closing' then d.closing_date when 'contract' then d.contract_date else d.open_date end) + t.due_days, false, private.effective_uid(), 'form', new.id, owner, t.id, t.code, t.version, t.lane, t.audiences
  from public.task_templates t join public.deals d on d.id = new.deal_id where t.active and t.retired_at is null and new.role = any (t.roles) and private.task_enabled(t.code)
    and (t.audiences is null or (not (t.audiences = array['internal']::text[]) and (
      (new.role = 'Client-Buyer' and 'buyer' = any (t.audiences)) or (new.role = 'Client-Seller' and 'seller' = any (t.audiences))
      or (new.role = 'Buyer Agent' and 'buyer_agent' = any (t.audiences)) or (new.role = 'Listing Agent' and 'listing_agent' = any (t.audiences))
      or (new.role in ('Sales Person', 'Sales Team') and 'sales_team' = any (t.audiences))
      or (new.role = 'Transaction Coordinator' and 'transaction_coordinator' = any (t.audiences)))))
    and not exists (select 1 from public.tasks x where x.participant_id = new.id and x.template_code = t.code and x.status <> 'cancelled');
  get diagnostics n = row_count;
  if n > 0 and owner is not null then perform private.notify(array[owner], 'task', new.deal_id, n || ' new task(s) on your order', '#/deals/' || new.deal_id || '/tasks'); end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_participant_entity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare r text;
begin
  select role into r from public.deal_participants where id = new.participant_id;
  if r is null or r not in ('Client-Buyer', 'Client-Seller') then raise exception 'Only a buyer or a seller can be an entity.' using errcode = '23514'; end if;
  new.name := btrim(new.name); new.rep_name := btrim(new.rep_name); new.rep_title := btrim(new.rep_title); new.rep_email := lower(btrim(new.rep_email));
  new.rep_phone := private.phone_or_raise(new.rep_phone, 'Entity Representative''s phone');
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_participant_tc_assign()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v uuid;
begin
  if not exists (select 1 from public.deals x where x.id = new.deal_id and x.tc_user_id is null) then return new; end if;
  v := private.tc_candidate(new.deal_id);
  if v is null then return new; end if;
  begin
    update public.deals set tc_user_id = v where id = new.deal_id and tc_user_id is null;
  exception when raise_exception then
    -- an unrelated order guard refused the update: adding the person must still succeed; the TC stays blank for staff to set
    null;
  end;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.trg_participant_unlink()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin update public.tasks set status = 'cancelled' where participant_id = old.id and status in ('todo', 'in_progress', 'blocked'); return old; end $function$

CREATE OR REPLACE FUNCTION private.trg_phone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin new.phone := private.phone_or_raise(new.phone, 'Phone'); return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_processor_deal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if coalesce(current_setting('cla.processor_sync', true), '') = 'on' then return new; end if;
  if new.processor_id is not distinct from old.processor_id then return new; end if;
  perform private.apply_processor_party(new.id);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.trg_processor_party()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_profile uuid; v_deal uuid; v_contact uuid;
begin
  if coalesce(current_setting('cla.processor_sync', true), '') = 'on' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_op = 'INSERT' and new.role is distinct from 'Processor' then return new; end if;
  if tg_op = 'DELETE' and old.role is distinct from 'Processor' then return old; end if;
  if tg_op = 'UPDATE' and old.role is distinct from 'Processor' and new.role is distinct from 'Processor' then return new; end if;
  -- A contact with no login can be listed as Processor. That does not change who the file's Processor is.
  if tg_op <> 'DELETE' and new.role = 'Processor'
     and not exists (select 1 from public.contacts c where c.id = new.contact_id and c.profile_id is not null)
     and not (tg_op = 'UPDATE' and old.role = 'Processor' and exists (
       select 1 from public.contacts c where c.id = old.contact_id and c.profile_id is not null)) then
    return new;
  end if;

  perform set_config('cla.processor_sync', 'on', true);

  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and old.role = 'Processor' and new.role is distinct from 'Processor') then
    v_deal := old.deal_id;
    v_contact := old.contact_id;
    update public.deals d
       set processor_id = null
      from public.contacts c
     where d.id = v_deal and c.id = v_contact and d.processor_id is not distinct from c.profile_id;
    delete from public.deal_participants dp
     using public.contacts c
     where dp.deal_id = v_deal and dp.role = 'Processor' and dp.id is distinct from old.id
       and c.id = dp.contact_id and c.profile_id is not null;
  end if;

  if tg_op = 'INSERT'
     or (tg_op = 'UPDATE' and new.role = 'Processor'
         and (old.role is distinct from 'Processor' or old.contact_id is distinct from new.contact_id)) then
    v_profile := private.processor_staff_id(new.contact_id, new.deal_id);
    if v_profile is not null then
      update public.deals set processor_id = v_profile
       where id = new.deal_id and processor_id is distinct from v_profile;
      delete from public.deal_participants dp
       using public.contacts c
       where dp.deal_id = new.deal_id and dp.role = 'Processor' and dp.id is distinct from new.id
         and c.id = dp.contact_id and c.profile_id is not null;
    end if;
  end if;

  perform set_config('cla.processor_sync', 'off', true);
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.trg_release_thread_invitees()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if new.profile_id is null then return new; end if;
  -- Setting up a portal login must never fail because of a held conversation. If this step fails, the rows stay held and a warning is logged.
  begin
    insert into public.thread_participants (thread_id, profile_id)
      select ti.thread_id, new.profile_id
      from public.thread_invitees ti
      join public.threads th on th.id = ti.thread_id
      where ti.contact_id = new.id
        -- still on that file (someone taken off the file before signing in gets nothing)
        and exists (select 1 from public.deal_participants dp where dp.deal_id = th.deal_id and dp.contact_id = new.id)
        and not exists (select 1 from public.thread_participants tp where tp.thread_id = ti.thread_id and tp.profile_id = new.profile_id);
    delete from public.thread_invitees ti where ti.contact_id = new.id;
  exception when others then
    raise warning 'held conversations were not opened for contact %: %', new.id, sqlerrm;
  end;
  return new;
end $function$

