begin
  if new.kind = 'sign' and new.status = 'done' and old.status <> 'done' and coalesce(current_setting('cla.sign_rpc', true), '') <> 'on' then
    raise exception 'A signature task is completed by the signer signing it.' using errcode = '42501'; end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin if new.status <> old.status then perform private.log_activity(new.deal_id, 'task.status', 'task', new.id, new.title || ': ' || new.status ||
    case when private.effective_uid() is not null and not private.is_manager() and cardinality(private.deal_roles(new.deal_id)) > 1 then ' by ' || private.person_label(private.effective_uid(), new.deal_id, new.assigned_role) else '' end); end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.trg_task_flow_deal_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  begin
    if tg_op = 'INSERT' then perform private.task_flow_start(new.id, 'order_opened');
    else
      if coalesce(new.emd_received, false) and not coalesce(old.emd_received, false) then perform private.task_flow_start(new.id, 'emd_received'); end if;
      if new.closing_date is not null and new.closing_date is distinct from old.closing_date then perform private.task_flow_start(new.id, 'closing_date_set'); end if;
    end if;
  exception when others then
    begin insert into public.task_flow_errors (deal_id, message) values (new.id, sqlerrm); exception when others then null; end;
  end;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.trg_task_masked()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if private.effective_uid() is not null and new.form_data is distinct from old.form_data and cardinality(private.masked_keys(new.template_id)) > 0
     and not (new.owner_profile_id = private.effective_uid() or private.is_processor()) then
    raise exception 'Only the client and the processor can change bank details.' using errcode = '42501'; end if;
  return new; end $function$

