CREATE OR REPLACE FUNCTION public.agent_fee_history(p_deal uuid)
 RETURNS TABLE(side text, kind text, slot smallint, old_value jsonb, new_value jsonb, reason text, source text, changed_by_name text, changed_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select l.side, l.kind, l.slot, l.old_value, l.new_value, l.reason, l.source,
         nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), ''), l.changed_at
  from public.deal_agent_fee_log l left join public.profiles p on p.id = l.changed_by
  where l.deal_id = p_deal and private.agent_fee_actor(p_deal, l.side) is not null
  order by l.changed_at desc, l.id desc
  limit 500 $function$

CREATE OR REPLACE FUNCTION public.agent_fee_sides(p_deal uuid)
 RETURNS TABLE(side text, access text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select s.side, case when a.actor = 'reader' then 'read' else 'edit' end
  from (values ('listing', 1), ('buyer', 2)) s(side, ord)
  cross join lateral (select private.agent_fee_actor(p_deal, s.side) as actor) a
  where a.actor is not null
    and exists (select 1 from public.deals d where d.id = p_deal and d.transaction_type is distinct from 'Refinance')
  order by s.ord $function$

CREATE OR REPLACE FUNCTION public.agent_fees(p_deal uuid)
 RETURNS TABLE(side text, kind text, slot smallint, basis text, percent numeric, amount numeric, payer text, description text, paid_to text, source text, confirmed_role text, confirmed_by_name text, confirmed_at timestamp with time zone, updated_at timestamp with time zone, can_edit boolean, base_amount numeric, additional_amount numeric, split_buyer numeric, split_seller numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select f.side, f.kind, f.slot, f.basis, round(f.pct, 4), f.amount, f.payer, f.description, f.paid_to, f.source, f.confirmed_role,
         nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), ''), f.confirmed_at, f.updated_at,
         a.actor in ('staff', 'agent', 'tc'), f.base_amount, f.additional_amount, f.split_buyer, f.split_seller
  from public.deal_agent_fees f
  cross join lateral (select private.agent_fee_actor(p_deal, f.side) as actor) a
  left join public.profiles p on p.id = f.confirmed_by
  where f.deal_id = p_deal and a.actor is not null
  order by f.side, case f.kind when 'commission' then 0 when 'admin' then 1 else 2 end, f.slot $function$

