CREATE OR REPLACE FUNCTION public.create_agent_invite(p_contact uuid, p_first text, p_last text, p_email text, p_deal uuid DEFAULT NULL::uuid)
 RETURNS TABLE(invite_id uuid, token text, expires_at timestamp with time zone)
