CREATE OR REPLACE FUNCTION public.crm_date_bounds(p_spec jsonb, p_now timestamp with time zone DEFAULT now())
 RETURNS TABLE(mode text, lo timestamp with time zone, hi timestamp with time zone, lo_date date, hi_date date)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  op text;
  unit text;
  n int;
  span int;
  today date;
  tomorrow date;
  yesterday date;
  d0 date;
  d1 date;
  start_d date;
  end_d date;
  swap date;
begin
  mode := 'none'; lo := null; hi := null; lo_date := null; hi_date := null;
  if p_spec is null or jsonb_typeof(p_spec) <> 'object' then return next; return; end if;
  op := coalesce(p_spec->>'op', '');
  today := (p_now at time zone 'America/New_York')::date;
  tomorrow := today + 1;
  yesterday := today - 1;
  if op = '' then
    begin
      d0 := nullif(p_spec->>'from', '')::date;
      d1 := nullif(p_spec->>'to', '')::date;
    exception when others then return next; return; end;
    if d0 is null and d1 is null then return next; return; end if;
    if d0 is null then d0 := d1; end if;
    if d1 is null then d1 := d0; end if;
    op := 'between';
  end if;
  if op = 'empty' then mode := 'empty'; return next; return; end if;
  if op = 'not_empty' then mode := 'present'; return next; return; end if;
  if op in ('age_in', 'due_in', 'prev_n', 'next_n') then
    unit := coalesce(nullif(p_spec->>'unit', ''), 'days');
    if unit not in ('days', 'weeks', 'months') then return next; return; end if;
    begin n := nullif(p_spec->>'n', '')::int; exception when others then return next; return; end;
    if n is null or n < 1 then return next; return; end if;
    if (unit = 'days' and n > 3650) or (unit = 'weeks' and n > 520) or (unit = 'months' and n > 240) then return next; return; end if;
    span := case when unit = 'weeks' then n * 7 else n end;
  end if;
  if op in ('on', 'before', 'after', 'between', 'not_between') then
    begin
      d0 := coalesce(nullif(p_spec->>'value', ''), nullif(p_spec->>'from', ''))::date;
      d1 := coalesce(nullif(p_spec->>'value2', ''), nullif(p_spec->>'to', ''))::date;
    exception when others then return next; return; end;
    if op in ('on', 'before', 'after') and d0 is null then return next; return; end if;
    if op in ('between', 'not_between') and (d0 is null or d1 is null) then return next; return; end if;
    if d0 is not null and d1 is not null and d1 < d0 then swap := d0; d0 := d1; d1 := swap; end if;
  end if;
  if op = 'today' then start_d := today; end_d := tomorrow;
  elsif op = 'tomorrow' then start_d := tomorrow; end_d := tomorrow + 1;
  elsif op = 'yesterday' then start_d := yesterday; end_d := today;
  elsif op = 'till_yesterday' then start_d := null; end_d := today;
  elsif op = 'starting_tomorrow' then start_d := tomorrow; end_d := null;
  elsif op = 'this_week' then start_d := today - extract(dow from today)::int; end_d := start_d + 7;
  elsif op = 'prev_week' then end_d := today - extract(dow from today)::int; start_d := end_d - 7;
  elsif op = 'this_month' then start_d := date_trunc('month', today)::date; end_d := (start_d + interval '1 month')::date;
  elsif op = 'prev_month' then end_d := date_trunc('month', today)::date; start_d := (end_d - interval '1 month')::date;
  elsif op = 'this_year' then start_d := date_trunc('year', today)::date; end_d := (start_d + interval '1 year')::date;
  elsif op = 'next_year' then start_d := (date_trunc('year', today)::date + interval '1 year')::date; end_d := (start_d + interval '1 year')::date;
  elsif op = 'on' then start_d := d0; end_d := d0 + 1;
  elsif op = 'before' then start_d := null; end_d := d0;
  elsif op = 'after' then start_d := d0 + 1; end_d := null;
  elsif op in ('between', 'not_between') then start_d := d0; end_d := d1 + 1;
  elsif op = 'prev_n' and unit = 'months' then end_d := date_trunc('month', today)::date; start_d := (end_d - make_interval(months => n))::date;
  elsif op = 'next_n' and unit = 'months' then start_d := (date_trunc('month', today)::date + interval '1 month')::date; end_d := (start_d + make_interval(months => n))::date;
  elsif op = 'age_in' and unit = 'months' then start_d := (today - make_interval(months => n))::date; end_d := tomorrow;
  elsif op = 'due_in' and unit = 'months' then start_d := today; end_d := ((today + make_interval(months => n))::date + 1);
  elsif op = 'age_in' then start_d := today - (span - 1); end_d := tomorrow;
  elsif op = 'due_in' then start_d := today; end_d := today + span;
  elsif op = 'prev_n' then start_d := today - span; end_d := today;
  elsif op = 'next_n' then start_d := tomorrow; end_d := tomorrow + span;
  else return next; return;
  end if;
  mode := case when op = 'not_between' then 'outside' else 'range' end;
  if start_d is not null then lo := start_d::timestamp at time zone 'America/New_York'; lo_date := start_d; end if;
  if end_d is not null then hi := end_d::timestamp at time zone 'America/New_York'; hi_date := end_d; end if;
  return next;
end
$function$

CREATE OR REPLACE FUNCTION public.crm_deal_filters()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare everyone boolean;
begin
  if not private.crm_user() then raise exception 'The CRM is for CLA staff only.' using errcode = '42501'; end if;
  if not private.role_can('crm') then raise exception 'The CRM is turned off for your role. A Super admin can change this in Admin > Role access.' using errcode = '42501'; end if;
  everyone := private.crm_deal_scope_all();
  return jsonb_build_object('scope', case when everyone then 'all' else 'own' end, 'role', private.me_role(),
    'me', jsonb_build_object('id', auth.uid(), 'name', private.crm_name(auth.uid())),
    'owners', case when everyone then coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'name', btrim(p.first_name || ' ' || p.last_name), 'role', p.role) order by p.first_name, p.last_name)
      from public.profiles p where p.role in ('Sales Person', 'Sales Team') and (p.status = 'active' or exists (select 1 from public.deal_sales_people s where s.sales_id = p.id))), '[]') else '[]' end,
    'clients', case when everyone then coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', btrim(c.first_name || ' ' || c.last_name)) order by c.first_name, c.last_name)
      from public.contacts c where exists (select 1 from public.deal_participants p where p.contact_id = c.id and p.role in ('Client-Buyer', 'Client-Seller') and private.crm_deal_visible(p.deal_id))), '[]') else '[]' end,
    'sources', coalesce((select jsonb_agg(x order by x->>'position', x->>'value') from (
      select jsonb_build_object('value', v, 'label', l, 'position', p) as x from (values
        ('buyer', 'Buyer', '1'), ('seller', 'Seller', '2'), ('buyer_agent', 'Buyer''s agent', '3'), ('listing_agent', 'Listing agent', '4'), ('lender', 'Lender', '5'), ('homeowner', 'Homeowner', '6')) r(v, l, p)
      union all
      select jsonb_build_object('value', o.value, 'label', o.label || case when o.retired then ' (retired)' else '' end, 'position', (100 + o.position)::text)
      from public.crm_picklist_options o where o.list_key = 'leadSource' and (not o.retired or exists (select 1 from public.deal_business_sources b where b.source = o.value and private.crm_deal_visible(b.deal_id)))
    ) s), '[]'),
    'statuses', '["Open", "Closed", "On Hold", "Cancelled", "All"]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.crm_deals(p_status text DEFAULT NULL::text, p_owner text DEFAULT NULL::text, p_client uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare st text := nullif(btrim(coalesce(p_status, '')), ''); ow text := nullif(btrim(coalesce(p_owner, '')), ''); src text := nullif(btrim(coalesce(p_source, '')), '');
begin
  if not private.crm_user() then raise exception 'The CRM is for CLA staff only.' using errcode = '42501'; end if;
  if not private.role_can('crm') then raise exception 'The CRM is turned off for your role. A Super admin can change this in Admin > Role access.' using errcode = '42501'; end if;
  if st is not null and st <> 'All' and st not in ('Open', 'Closed', 'On Hold', 'Cancelled') then raise exception 'Unknown status.' using errcode = '22023'; end if;
  if ow is not null and ow <> 'none' and ow !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'Unknown deal owner.' using errcode = '22023'; end if;
  if ow is not null and not private.crm_deal_scope_all() and ow <> auth.uid()::text then raise exception 'A Sales Person sees only their own deals.' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(private.crm_deal_row(g) order by g.closing_date desc nulls last, g.file_number) from public.deals g
    where private.crm_deal_visible(g.id)
      and (st is null or st = 'All' or g.status = st)
      and (ow is null or (ow = 'none' and not exists (select 1 from public.deal_sales_people s where s.deal_id = g.id))
           or exists (select 1 from public.deal_sales_people s where s.deal_id = g.id and s.sales_id::text = ow))
      and (p_client is null or exists (select 1 from public.deal_participants p where p.deal_id = g.id and p.contact_id = p_client and p.role in ('Client-Buyer', 'Client-Seller')))
      and (src is null or (src = 'none' and coalesce((select b.source from public.deal_business_sources b where b.deal_id = g.id), '') = '')
           or exists (select 1 from public.deal_business_sources b where b.deal_id = g.id and (b.source = src or split_part(b.source, ':', 1) = src)))), '[]');
end $function$

