CREATE OR REPLACE FUNCTION public.crm_import_batch(p_commit boolean, p_module text, p_kind text, p_file_name text, p_defaults jsonb, p_rows jsonb, p_import uuid DEFAULT NULL::uuid, p_chunk integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_uid uuid;
  v_n int;
  v_row jsonb;
  v_rec jsonb;
  v_def jsonb;
  v_field text;
  v_val text;
  v_list text;
  v_line int;
  v_notes jsonb;
  v_first text;
  v_last text;
  v_email text;
  v_phone text;
  v_mobile text;
  v_company text;
  v_role text;
  v_title text;
  v_source text;
  v_status text;
  v_canon text;
  v_street text;
  v_city text;
  v_state text;
  v_zip text;
  v_county text;
  v_license text;
  v_desc text;
  v_owner uuid;
  v_owner_text text;
  v_account uuid;
  v_acc_name text;
  v_acc_archived timestamptz;
  v_links jsonb;
  v_new uuid;
  v_name text;
  v_link text;
  v_entity text;
  v_body text;
  v_subject text;
  v_em text;
  v_nm text;
  v_hits int;
  v_arch boolean;
  v_msg text;
  v_state_code text;
  v_out_rows jsonb := '[]'::jsonb;
  v_ok int := 0;
  v_dup int := 0;
  v_err int := 0;
  v_total int := 0;
  v_import uuid;
  v_batch_module text;
  v_batch_kind text;
  v_batch_by uuid;
  v_prev_total int;
  v_result jsonb;
  v_row_status text;
begin
  -- once per call, before any row is touched
  if coalesce(private.is_admin(), false) is not true then
    raise exception 'Only an Admin or Super admin can import.' using errcode = '42501';
  end if;
  v_uid := private.effective_uid();
  if p_module is distinct from 'leads' and p_module is distinct from 'contacts' then
    raise exception 'Import into Leads or Clients.' using errcode = 'P0001';
  end if;
  if p_kind is distinct from 'records' and p_kind is distinct from 'notes' then
    raise exception 'Import records or notes.' using errcode = 'P0001';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) is null or jsonb_array_length(p_rows) < 1 then
    raise exception 'The file needs a header row and at least one row of data.' using errcode = 'P0001';
  end if;
  v_n := jsonb_array_length(p_rows);
  if p_chunk is null then
    p_chunk := 1;
  end if;
  if p_chunk < 1 or p_chunk > 20 then
    raise exception 'Chunk % is outside 1 to 20. A file is at most 10000 rows, sent 500 at a time.', p_chunk using errcode = 'P0001';
  end if;
  if v_n > 500 then
    raise exception 'At most 500 rows per import call.' using errcode = 'P0001';
  end if;
  if (select count(distinct (value->>'line')::int) from jsonb_array_elements(p_rows)) is distinct from v_n then
    raise exception 'Each import row needs its own line number.' using errcode = 'P0001';
  end if;
  if p_defaults is null or jsonb_typeof(p_defaults) = 'null' then
    p_defaults := '[]'::jsonb;
  elsif jsonb_typeof(p_defaults) is distinct from 'array' then
    raise exception 'Defaults must be a list.' using errcode = 'P0001';
  end if;
  if p_kind = 'records' then
    for v_def in select value from jsonb_array_elements(p_defaults) loop
      v_field := btrim(coalesce(v_def->>'field', ''));
      v_val := btrim(coalesce(v_def->>'value', ''));
      if v_field not in ('ownerId', 'roleInCompany', 'relationshipStatus', 'leadSource', 'state') then
        raise exception '"%" cannot have a default value.', v_field using errcode = 'P0001';
      end if;
      if v_val = '' then continue; end if;
      if v_field = 'ownerId' then
        if v_val !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           or not exists (
             select 1 from public.profiles
             where id = v_val::uuid and status = 'active' and role in ('Sales Person', 'Sales Team')
           ) then
          raise exception 'The default Owner must be an active Sales Person or Sales Team user.' using errcode = 'P0001';
        end if;
      elsif v_field = 'state' then
        if not private.us_state_ok(upper(v_val)) then
          raise exception 'Pick a state for the default State.' using errcode = 'P0001';
        end if;
      elsif v_field = 'relationshipStatus' then
        v_list := case when p_module = 'leads' then 'leadRelationshipStatus' else 'relationshipStatus' end;
        if not private.crm_option_active(v_list, v_val) then
          raise exception 'A default Relationship Status must be a current choice. Retired statuses are not offered and are not imported.' using errcode = 'P0001';
        end if;
      else
        v_list := v_field;
        if not private.crm_option_active(v_list, v_val) then
          if exists (select 1 from public.crm_picklist_options where list_key = v_list and value = v_val) then
            raise exception '"%" is retired; pick another %.', private.crm_option_label(v_list, v_val),
              case when v_field = 'roleInCompany' then 'Role in Company' else 'Lead Source' end using errcode = 'P0001';
          end if;
          raise exception 'Pick a % from the list.', case when v_field = 'roleInCompany' then 'Role in Company' else 'Lead Source' end using errcode = 'P0001';
        end if;
      end if;
    end loop;
  end if;

  -- client duplicate checks run only when the CRM itself is writing
  perform set_config('crm.person_write', '1', true);

  -- rows (private.is_admin already ran once above; nothing in this loop calls it)
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_total := v_total + 1;
    v_line := (v_row->>'line')::int;
    v_notes := case when jsonb_typeof(v_row->'prepNotes') = 'array' then v_row->'prepNotes' else '[]'::jsonb end;
    v_rec := coalesce(v_row->'values', '{}'::jsonb);
    v_new := null; v_name := null; v_link := null; v_owner := null; v_account := null;
    begin
      if p_kind = 'records' then
        for v_def in select value from jsonb_array_elements(p_defaults) loop
          v_field := v_def->>'field';
          v_val := btrim(coalesce(v_def->>'value', ''));
          if v_val = '' or btrim(coalesce(v_rec->>v_field, '')) <> '' then continue; end if;
          if v_field = 'state' then v_val := upper(v_val); end if;
          v_rec := jsonb_set(v_rec, array[v_field], to_jsonb(v_val), true);
          if v_field = 'ownerId' then
            v_notes := v_notes || jsonb_build_array('Owner: ' || coalesce(private.crm_name(v_val::uuid), v_val) || ' (default)');
          else
            v_notes := v_notes || jsonb_build_array(
              (case v_field when 'roleInCompany' then 'Role in Company' when 'relationshipStatus' then 'Relationship Status'
                when 'leadSource' then 'Lead Source' when 'state' then 'State' else v_field end)
              || ': ' || v_val || ' (default)');
          end if;
        end loop;
        v_first := left(btrim(coalesce(v_rec->>'firstName', '')), 80);
        v_last := left(btrim(coalesce(v_rec->>'lastName', '')), 80);
        v_email := left(lower(btrim(coalesce(v_rec->>'email', ''))), 200);
        v_phone := left(btrim(coalesce(v_rec->>'phone', '')), 40);
        v_mobile := left(btrim(coalesce(v_rec->>'mobile', '')), 40);
        v_company := left(btrim(coalesce(v_rec->>'company', '')), 160);
        v_role := left(btrim(coalesce(v_rec->>'roleInCompany', '')), 80);
        v_title := left(btrim(coalesce(v_rec->>'title', '')), 100);
        v_source := left(btrim(coalesce(v_rec->>'leadSource', '')), 80);
        v_status := left(btrim(coalesce(v_rec->>'relationshipStatus', '')), 80);
        v_street := left(btrim(coalesce(v_rec->>'street', '')), 200);
        v_city := left(btrim(coalesce(v_rec->>'city', '')), 80);
        v_state := upper(left(btrim(coalesce(v_rec->>'state', '')), 2));
        if length(btrim(coalesce(v_rec->>'state', ''))) > 2 then v_state := left(btrim(v_rec->>'state'), 40); end if;
        v_zip := left(btrim(coalesce(v_rec->>'zip', '')), 10);
        v_county := left(btrim(coalesce(v_rec->>'county', '')), 60);
        v_license := left(btrim(coalesce(v_rec->>'licenseNo', '')), 60);
        v_desc := left(btrim(coalesce(v_rec->>'description', '')), 4000);
        if v_email <> '' and v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then
          raise exception 'Email is not valid.' using errcode = 'P0001';
        end if;
        if v_state <> '' and not private.us_state_ok(v_state) then
          raise exception 'Pick a US state (or DC).' using errcode = 'P0001';
        end if;
        if v_zip <> '' and v_zip !~ '^[0-9]{5}(-[0-9]{4})?$' then
          raise exception 'Zip Code must be 5 digits (or ZIP+4).' using errcode = 'P0001';
        end if;
        if v_status <> '' then
          v_list := case when p_module = 'leads' then 'leadRelationshipStatus' else 'relationshipStatus' end;
          select o.value into v_canon
          from public.crm_picklist_options o
          where o.list_key = v_list and not o.retired
            and (o.value = v_status or lower(o.label) = lower(v_status))
          order by (o.value = v_status) desc
          limit 1;
          if v_canon is null then
            if exists (
              select 1 from public.crm_picklist_options o
              where o.list_key = v_list and o.retired
                and (o.value = v_status or lower(o.label) = lower(v_status))
            ) then
              raise exception 'Relationship Status "%" is retired and is not imported. Pick a current status.', v_status using errcode = 'P0001';
            end if;
          else
            v_status := v_canon;
          end if;
        end if;
        if p_module = 'leads' then
          if v_role = '' then
            raise exception 'Role in Company is required.' using errcode = 'P0001';
          end if;
          if v_status = '' then
            raise exception 'Relationship Status is required.' using errcode = 'P0001';
          end if;
          if v_state = '' then
            raise exception 'State is required.' using errcode = 'P0001';
          end if;
        end if;
        v_owner_text := btrim(coalesce(v_rec->>'ownerId', ''));
        if v_owner_text <> '' then
          if v_owner_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
            select id into v_owner from public.profiles
            where id = v_owner_text::uuid and status = 'active' and role in ('Sales Person', 'Sales Team');
          end if;
          if v_owner is null then
            select count(*) into v_hits from public.profiles
            where status = 'active' and role in ('Sales Person', 'Sales Team')
              and (lower(email) = lower(v_owner_text) or lower(btrim(first_name || ' ' || last_name)) = lower(v_owner_text));
            if v_hits > 1 then
              raise exception 'Owner "%" matches more than one salesperson. Use the email.', v_owner_text using errcode = 'P0001';
            end if;
            select id into v_owner from public.profiles
            where status = 'active' and role in ('Sales Person', 'Sales Team')
              and (lower(email) = lower(v_owner_text) or lower(btrim(first_name || ' ' || last_name)) = lower(v_owner_text));
          end if;
          if v_owner is null then
            raise exception 'Owner "%" is not an active Sales Person or Sales Team user.', v_owner_text using errcode = 'P0001';
          end if;
        end if;
        v_links := '{}'::jsonb;
        if jsonb_typeof(v_rec->'links') = 'object' then
          select coalesce(jsonb_object_agg(e.key, to_jsonb(btrim(e.value #>> '{}'))), '{}'::jsonb) into v_links
          from jsonb_each(v_rec->'links') e
          where e.key = any (private.crm_link_keys()) and jsonb_typeof(e.value) = 'string' and btrim(e.value #>> '{}') <> '';
        end if;
        if v_company <> '' then
          select a.id, a.name, a.archived_at into v_account, v_acc_name, v_acc_archived
          from public.crm_accounts a
          where private.crm_company_key(a.name) = private.crm_company_key(v_company)
          order by a.archived_at nulls first
          limit 1;
          if v_account is not null and v_acc_archived is null then
            v_notes := v_notes || jsonb_build_array('Company: ' || v_acc_name);
          else
            v_account := null;
            v_notes := v_notes || jsonb_build_array('No company called "' || v_company || '" yet: kept as text' || case when p_module = 'leads' then ' (pick it from Companies later)' else '' end);
          end if;
        end if;
        if p_module = 'leads' then
          insert into public.crm_leads (
            first_name, last_name, company, email, phone, mobile, source, status, owner_id, notes,
            role_in_company, title, license_no, crm_street, crm_city, crm_state, crm_zip, crm_county, links, account_id
          ) values (
            v_first, v_last, case when v_account is null then v_company else '' end, v_email, v_phone, v_mobile,
            v_source, v_status, v_owner, v_desc, v_role, v_title, v_license, v_street, v_city, v_state, v_zip, v_county,
            coalesce(v_links, '{}'::jsonb), v_account
          ) returning id, btrim(first_name || ' ' || last_name) into v_new, v_name;
          v_link := '#/crm/leads/' || v_new::text;
        else
          v_new := public.crm_create_contact(jsonb_strip_nulls(jsonb_build_object(
            'firstName', v_first, 'lastName', v_last, 'email', v_email, 'phone', v_phone, 'mobile', v_mobile,
            'company', case when v_account is null then v_company else '' end,
            'accountId', v_account, 'roleInCompany', v_role, 'title', v_title, 'leadSource', v_source,
            'relationshipStatus', nullif(v_status, ''), 'street', v_street, 'city', v_city, 'state', v_state,
            'zip', v_zip, 'county', v_county, 'licenseNo', v_license, 'description', v_desc,
            'ownerId', v_owner, 'links', coalesce(v_links, '{}'::jsonb)
          )));
          select btrim(c.first_name || ' ' || c.last_name) into v_name from public.contacts c where c.id = v_new;
          v_link := '#/crm/contacts/' || v_new::text;
        end if;
      else
        v_body := left(btrim(coalesce(v_rec->>'note', '')), 4000);
        if v_body = '' then raise exception 'Note is required.' using errcode = 'P0001'; end if;
        v_subject := left(btrim(coalesce(v_rec->>'noteTitle', '')), 200);
        if v_subject = '' then v_subject := left(split_part(v_body, E'\n', 1), 80); end if;
        if btrim(v_subject) = '' then raise exception 'Note is required.' using errcode = 'P0001'; end if;
        v_em := lower(left(btrim(coalesce(v_rec->>'email', '')), 200));
        v_nm := lower(btrim(regexp_replace(coalesce(nullif(btrim(coalesce(v_rec->>'fullName', '')), ''),
          btrim(coalesce(v_rec->>'firstName', '') || ' ' || coalesce(v_rec->>'lastName', ''))), '\s+', ' ', 'g')));
        v_entity := case when p_module = 'leads' then 'lead' else 'contact' end;
        v_new := null;
        if p_module = 'leads' then
          if v_em <> '' then
            select l.id, btrim(l.first_name || ' ' || l.last_name), l.archived_at is not null
              into v_new, v_name, v_arch
            from public.crm_leads l
            where lower(l.email) = v_em
            order by (l.archived_at is null) desc, l.created_at
            limit 1;
          end if;
          if v_new is null then
            if v_nm = '' then
              if v_em <> '' then raise exception 'No lead has the email %.', v_em using errcode = 'P0002'; end if;
              raise exception 'Give the email or the name of the lead for this note.' using errcode = 'P0001';
            end if;
            select count(*) into v_hits from public.crm_leads l
            where lower(btrim(regexp_replace(l.first_name || ' ' || l.last_name, '\s+', ' ', 'g'))) = v_nm;
            if v_hits > 1 then
              raise exception '% leads are named "%"; add the email to pick one.', v_hits, v_nm using errcode = 'P0001';
            end if;
            if v_hits = 0 then
              raise exception 'No lead %is named "%".', case when v_em <> '' then 'has the email ' || v_em || ' or ' else '' end, v_nm using errcode = 'P0002';
            end if;
            select l.id, btrim(l.first_name || ' ' || l.last_name), l.archived_at is not null
              into v_new, v_name, v_arch
            from public.crm_leads l
            where lower(btrim(regexp_replace(l.first_name || ' ' || l.last_name, '\s+', ' ', 'g'))) = v_nm
            limit 1;
          end if;
        else
          if v_em <> '' then
            select c.id, btrim(c.first_name || ' ' || c.last_name), c.crm_archived_at is not null
              into v_new, v_name, v_arch
            from public.contacts c
            where lower(c.email) = v_em
            order by (c.crm_archived_at is null) desc, c.created_at
            limit 1;
          end if;
          if v_new is null then
            if v_nm = '' then
              if v_em <> '' then raise exception 'No client has the email %.', v_em using errcode = 'P0002'; end if;
              raise exception 'Give the email or the name of the client for this note.' using errcode = 'P0001';
            end if;
            select count(*) into v_hits from public.contacts c
            where lower(btrim(regexp_replace(c.first_name || ' ' || c.last_name, '\s+', ' ', 'g'))) = v_nm;
            if v_hits > 1 then
              raise exception '% clients are named "%"; add the email to pick one.', v_hits, v_nm using errcode = 'P0001';
            end if;
            if v_hits = 0 then
              raise exception 'No client %is named "%".', case when v_em <> '' then 'has the email ' || v_em || ' or ' else '' end, v_nm using errcode = 'P0002';
            end if;
            select c.id, btrim(c.first_name || ' ' || c.last_name), c.crm_archived_at is not null
              into v_new, v_name, v_arch
            from public.contacts c
            where lower(btrim(regexp_replace(c.first_name || ' ' || c.last_name, '\s+', ' ', 'g'))) = v_nm
            limit 1;
          end if;
        end if;
        if exists (
          select 1 from public.crm_activities a
          where a.kind = 'note' and a.entity = v_entity and a.entity_id = v_new and a.body = v_body and a.subject = v_subject
        ) then
          raise exception 'Duplicate: this note is already on %.', v_name using errcode = '23505';
        end if;
        insert into public.crm_activities (entity, entity_id, kind, subject, body, status)
        values (v_entity, v_new, 'note', v_subject, v_body, 'done');
        v_link := '#/crm/' || case when p_module = 'leads' then 'leads' else 'contacts' end || '/' || v_new::text;
        v_notes := v_notes || jsonb_build_array(case when v_arch then 'on an archived ' || v_entity else 'linked by ' || case when v_em <> '' then 'email' else 'name' end end);
      end if;
      v_ok := v_ok + 1;
      v_out_rows := v_out_rows || jsonb_build_array(jsonb_build_object(
        'line', v_line, 'status', 'ok', 'message', '', 'id', v_new, 'name', coalesce(v_name, ''), 'link', v_link, 'notes', v_notes
      ));
    exception
      when sqlstate 'P0004' then
        -- assert_failure. WHEN OTHERS does not catch it. A preview must leave
        -- this row and roll the chunk back, so name the code and re-raise.
        raise;
      when others then
      get stacked diagnostics v_msg = message_text, v_state_code = returned_sqlstate;
      if v_state_code = '23505' or v_msg ~* 'already (used|exists|a client)|duplicate' then
        v_row_status := 'duplicate';
        v_dup := v_dup + 1;
        if v_state_code = '23505' and v_msg !~* 'already|duplicate' then
          v_msg := 'Duplicate: this email or phone is already on a lead or client.';
        end if;
      else
        v_row_status := 'error';
        v_err := v_err + 1;
      end if;
      v_out_rows := v_out_rows || jsonb_build_array(jsonb_build_object(
        'line', v_line, 'status', v_row_status, 'message', left(coalesce(v_msg, 'This row could not be imported.'), 500),
        'id', null, 'name', '', 'link', '', 'notes', v_notes
      ));
    end;
  end loop;

  v_result := jsonb_build_object(
    'rows', v_out_rows,
    'counts', jsonb_build_object('total', v_total, 'ok', v_ok, 'duplicates', v_dup, 'errors', v_err),
    'importId', null
  );
  if not coalesce(p_commit, false) then
    -- Rolls the lead / client / note inserts back. The error detail carries every row,
    -- including names and emails, so Postgres logs can keep that text. Fine on TEST
    -- with fake data. Revisit before any real import.
    raise exception 'Import preview only. Nothing was saved.'
      using errcode = 'P0004', detail = v_result::text;
  end if;

  if p_import is null then
    insert into public.crm_imports (module, kind, file_name, created_by, created, duplicates, errors, total, defaults)
    values (
      p_module, p_kind, left(btrim(coalesce(p_file_name, '')), 200), v_uid, v_ok, v_dup, v_err, v_total, p_defaults
    ) returning id into v_import;
  else
    select i.module, i.kind, i.created_by, i.total
      into v_batch_module, v_batch_kind, v_batch_by, v_prev_total
    from public.crm_imports i
    where i.id = p_import
    for update;
    if not found then
      raise exception 'Import batch not found.' using errcode = 'P0002';
    end if;
    if v_batch_by is distinct from v_uid then
      raise exception 'Only the admin who started this import can add a chunk.' using errcode = '42501';
    end if;
    if v_batch_module is distinct from p_module or v_batch_kind is distinct from p_kind then
      raise exception 'This chunk does not match the import it was added to.' using errcode = 'P0001';
    end if;
    if coalesce(v_prev_total, 0) + v_n > 10000 then
      raise exception 'A file is at most 10000 rows. Split the file and import each part.' using errcode = 'P0001';
    end if;
    update public.crm_imports
    set created = created + v_ok,
        duplicates = duplicates + v_dup,
        errors = errors + v_err,
        total = total + v_total
    where id = p_import;
    v_import := p_import;
  end if;

  insert into public.crm_import_rows (import_id, line, status, message, record_id, record_name)
  select v_import, (r->>'line')::int, r->>'status', left(coalesce(r->>'message', ''), 500),
         nullif(r->>'id', '')::uuid, left(coalesce(r->>'name', ''), 200)
  from jsonb_array_elements(v_out_rows) r;

  v_result := jsonb_set(v_result, '{importId}', to_jsonb(v_import));
  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.crm_invited_meetings(p_entity text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$ BEGIN RETURN private.rpc_crm_invited_meetings(p_entity, p_id); END; $function$

CREATE OR REPLACE FUNCTION public.crm_list_export(p_module text, p_rows integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$ BEGIN RETURN private.rpc_crm_list_export(p_module, p_rows); END; $function$

CREATE OR REPLACE FUNCTION public.crm_list_import_rows(p_import uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_out jsonb;
begin
  if coalesce(private.is_admin(), false) is not true then
    raise exception 'Only an Admin or Super admin can import.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.crm_imports where id = p_import) then
    raise exception 'Import not found.' using errcode = 'P0002';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'importId', r.import_id,
    'line', r.line,
    'status', r.status,
    'message', r.message,
    'recordId', r.record_id,
    'recordName', r.record_name
  ) order by r.line), '[]'::jsonb) into v_out
  from public.crm_import_rows r
  where r.import_id = p_import;
  return v_out;
end
$function$

CREATE OR REPLACE FUNCTION public.crm_list_imports()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_out jsonb;
begin
  if coalesce(private.is_admin(), false) is not true then
    raise exception 'Only an Admin or Super admin can import.' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(q.obj order by q.at desc), '[]'::jsonb) into v_out
  from (
    select i.created_at as at, jsonb_build_object(
      'id', i.id,
      'module', i.module,
      'kind', i.kind,
      'fileName', coalesce(i.file_name, ''),
      'at', i.created_at,
      'by', i.created_by,
      'byName', coalesce(private.crm_name(i.created_by), ''),
      'created', case when coalesce(c.n, 0) > 0 then c.ok else i.created end,
      'duplicates', case when coalesce(c.n, 0) > 0 then c.dup else i.duplicates end,
      'errors', case when coalesce(c.n, 0) > 0 then c.err else i.errors end,
      'rowCount', coalesce(c.n, 0),
      'defaults', coalesce(def.defaults, '[]'::jsonb)
    ) as obj
    from public.crm_imports i
    left join lateral (
      select count(*) filter (where r.status = 'ok')::int as ok,
             count(*) filter (where r.status = 'duplicate')::int as dup,
             count(*) filter (where r.status = 'error')::int as err,
             count(*)::int as n
      from public.crm_import_rows r
      where r.import_id = i.id
    ) c on true
    left join lateral (
      select jsonb_agg(jsonb_build_object(
        'field', d->>'field',
        'value', d->>'value',
        'text', case
          when d->>'field' = 'ownerId' and d->>'value' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then coalesce(private.crm_name((d->>'value')::uuid), d->>'value')
          else d->>'value' end
      )) as defaults
      from jsonb_array_elements(coalesce(i.defaults, '[]'::jsonb)) d
    ) def on true
  ) q;
  return v_out;
end
$function$

CREATE OR REPLACE FUNCTION public.crm_list_page(p_module text, p_filter jsonb, p_page integer, p_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  size int := least(greatest(coalesce(p_size, 100), 1), 100);
  page int := greatest(coalesce(p_page, 1), 1);
  total int;
  ids jsonb;
begin
  if auth.uid() is null then raise exception 'Sign in required.' using errcode = '42501'; end if;
  select count(*) into total from public.crm_match_ids(p_module, coalesce(p_filter, '{}'::jsonb));
  select coalesce(jsonb_agg(s.match_id), '[]'::jsonb) into ids from (
    select crm_match_ids as match_id from public.crm_match_ids(p_module, coalesce(p_filter, '{}'::jsonb))
    order by 1
    offset (page - 1) * size
    limit size
  ) s;
  return jsonb_build_object('total', total, 'ids', ids);
end
$function$

CREATE OR REPLACE FUNCTION public.crm_mass_email(p_module text, p_filter jsonb, p_subject text, p_html text, p_ids uuid[] DEFAULT NULL::uuid[], p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  -- EMAIL_DRAFT_BATCH: drafts inserted per statement. Not the recipient cap.
  batch_size constant int := 500;
  -- EMAIL_RECIPIENT_CAP: deduplicated addresses. Change this one number to move the limit.
  recipient_cap constant int := 250;
  m text := case lower(btrim(coalesce(p_module, '')))
    when 'leads' then 'lead' when 'contacts' then 'contact' when 'clients' then 'contact'
    when 'accounts' then 'account' when 'companies' then 'account'
    when 'opportunities' then 'opportunity' when 'deals' then 'deal' else lower(btrim(coalesce(p_module, ''))) end;
  subject text := left(regexp_replace(btrim(coalesce(p_subject, '')), '[\r\n]+', ' ', 'g'), 250);
  body text := left(coalesce(p_html, ''), 200000);
  sender text;
  wrote int := 0;
  n int;
  recip_n int;
  off int := 0;
begin
  if auth.uid() is null then raise exception 'Sign in required.' using errcode = '42501'; end if;
  if exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('Processor', 'Preprocessor')) then
    raise exception 'The Processor has read-only access to the CRM.' using errcode = '42501';
  end if;
  if not coalesce(p_dry_run, false) and subject = '' then raise exception 'Subject is required.' using errcode = '22023'; end if;
  select lower(btrim(coalesce(p.email, ''))) into sender from public.profiles p where p.id = auth.uid();
  create temp table if not exists crm_mass_recip (
    n int generated always as identity,
    entity text not null,
    entity_id uuid not null,
    email text not null
  ) on commit drop;
  truncate crm_mass_recip restart identity;
  if m = 'lead' then
    insert into crm_mass_recip (entity, entity_id, email)
    select 'lead', l.id, lower(btrim(l.email)) from public.crm_leads l
    where case when p_ids is null then l.id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else l.id = any(p_ids) end
      and btrim(coalesce(l.email, '')) <> '' and position('@' in l.email) > 0;
  elsif m = 'contact' then
    insert into crm_mass_recip (entity, entity_id, email)
    select 'contact', c.id, lower(btrim(c.email)) from public.contacts c
    where case when p_ids is null then c.id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else c.id = any(p_ids) end
      and btrim(coalesce(c.email, '')) <> '' and position('@' in c.email) > 0;
  elsif m = 'account' then
    insert into crm_mass_recip (entity, entity_id, email)
    select 'account', a.id, lower(btrim(c.email)) from public.crm_accounts a
    join public.contacts c on c.account_id = a.id
    where case when p_ids is null then a.id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else a.id = any(p_ids) end
      and btrim(coalesce(c.email, '')) <> '' and position('@' in c.email) > 0;
  elsif m = 'opportunity' then
    insert into crm_mass_recip (entity, entity_id, email)
    select 'contact', c.id, lower(btrim(c.email)) from public.crm_opportunities o
    join public.contacts c on c.id = o.contact_id
    where case when p_ids is null then o.id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else o.id = any(p_ids) end
      and btrim(coalesce(c.email, '')) <> '' and position('@' in c.email) > 0;
  elsif m = 'deal' then
    insert into crm_mass_recip (entity, entity_id, email)
    select 'deal', g.id, lower(btrim(c.email)) from public.deals g
    join public.deal_participants p on p.deal_id = g.id
    join public.contacts c on c.id = p.contact_id
    where case when p_ids is null then g.id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else g.id = any(p_ids) end
      and btrim(coalesce(c.email, '')) <> '' and position('@' in c.email) > 0;
  else raise exception 'Unknown list.' using errcode = '22023';
  end if;
  delete from crm_mass_recip r using crm_mass_recip e where r.email = e.email and r.n > e.n;
  select count(*) into recip_n from crm_mass_recip;
  if coalesce(p_dry_run, false) then
    return jsonb_build_object('count', recip_n, 'recipients', recip_n, 'drafted', 0, 'cap', recipient_cap, 'over', recip_n > recipient_cap);
  end if;
  if recip_n = 0 then
    raise exception 'None of these records have an email address. Nothing was saved.' using errcode = '22023';
  end if;
  if recip_n > recipient_cap then
    raise exception '% recipients is over the limit of %. Nothing was saved.', recip_n, recipient_cap using errcode = '22023';
  end if;
  loop
    insert into public.crm_emails (entity, entity_id, from_email, to_emails, cc_emails, bcc_emails, subject, body_html, status, scheduled_at, created_by)
    select r.entity, r.entity_id, coalesce(sender, ''), array[r.email], '{}', '{}', subject, body, 'drafted', null, auth.uid()
    from crm_mass_recip r where r.n > off and r.n <= off + batch_size;
    get diagnostics n = row_count;
    exit when n = 0;
    wrote := wrote + n;
    off := off + batch_size;
  end loop;
  return jsonb_build_object('count', wrote, 'drafted', wrote, 'recipients', recip_n, 'cap', recipient_cap, 'over', false);
end
$function$

CREATE OR REPLACE FUNCTION public.crm_mass_update(p_module text, p_filter jsonb, p_field text, p_value text, p_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  m text := case lower(btrim(coalesce(p_module, '')))
    when 'leads' then 'lead' when 'contacts' then 'contact' when 'clients' then 'contact'
    when 'accounts' then 'account' when 'companies' then 'account'
    when 'opportunities' then 'opportunity' when 'deals' then 'deal' else lower(btrim(coalesce(p_module, ''))) end;
  field text := btrim(coalesce(p_field, ''));
  val text := btrim(coalesce(p_value, ''));
  author text;
  stamp text;
  n int;
begin
  if auth.uid() is null then raise exception 'Sign in required.' using errcode = '42501'; end if;
  if exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('Processor', 'Preprocessor')) then
    raise exception 'The Processor has read-only access to the CRM.' using errcode = '42501';
  end if;
  if val = '' then raise exception 'Enter the new value.' using errcode = '22023'; end if;
  if m = 'lead' and field not in ('notes', 'relationshipStatus', 'leadSource') then raise exception 'That field cannot be changed for every selected record.' using errcode = '22023'; end if;
  if m = 'contact' and field <> 'notes' then raise exception 'That field cannot be changed for every selected record.' using errcode = '22023'; end if;
  if m = 'account' and field not in ('notes', 'kind') then raise exception 'That field cannot be changed for every selected record.' using errcode = '22023'; end if;
  if m = 'opportunity' and field not in ('notes', 'stage') then raise exception 'That field cannot be changed for every selected record.' using errcode = '22023'; end if;
  if m = 'deal' and field <> 'notes' then raise exception 'That field cannot be changed for every selected record.' using errcode = '22023'; end if;
  if p_ids is not null and cardinality(p_ids) > 100 then raise exception 'Select at most one page of records.' using errcode = '22023'; end if;
  if field = 'notes' then
    select case
      when btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')) <> ''
        then btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, ''))
      else coalesce(nullif(btrim(p.email), ''), 'CLA Title')
    end into author
    from public.profiles p where p.id = auth.uid();
    stamp := to_char(timezone('America/New_York', clock_timestamp()), 'FMMon FMDD, YYYY') || ' — ' || coalesce(author, 'CLA Title');
  end if;
  if m = 'lead' and field = 'notes' then
    update public.crm_leads set notes = case when btrim(coalesce(notes, '')) = '' then stamp || E'\n' || val else btrim(notes) || E'\n\n---\n' || stamp || E'\n' || val end, modified_at = now()
    where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'lead' and field = 'relationshipStatus' then update public.crm_leads set status = val, modified_at = now() where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'lead' and field = 'leadSource' then update public.crm_leads set source = val, modified_at = now() where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'contact' then
    update public.contacts set crm_notes = case when btrim(coalesce(crm_notes, '')) = '' then stamp || E'\n' || val else btrim(crm_notes) || E'\n\n---\n' || stamp || E'\n' || val end, modified_at = now(), modified_by = auth.uid()
    where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'account' and field = 'notes' then
    update public.crm_accounts set notes = case when btrim(coalesce(notes, '')) = '' then stamp || E'\n' || val else btrim(notes) || E'\n\n---\n' || stamp || E'\n' || val end, modified_at = now()
    where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'account' and field = 'kind' then update public.crm_accounts set kind = val, modified_at = now() where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'opportunity' and field = 'notes' then
    update public.crm_opportunities set notes = case when btrim(coalesce(notes, '')) = '' then stamp || E'\n' || val else btrim(notes) || E'\n\n---\n' || stamp || E'\n' || val end, modified_at = now()
    where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'opportunity' and field = 'stage' then update public.crm_opportunities set stage = val, modified_at = now() where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  elsif m = 'deal' then
    update public.deals set notes = case when btrim(coalesce(notes, '')) = '' then stamp || E'\n' || val else btrim(notes) || E'\n\n---\n' || stamp || E'\n' || val end
    where case when p_ids is null then id in (select public.crm_match_ids(m, coalesce(p_filter, '{}'::jsonb))) else id = any(p_ids) end;
  else raise exception 'Unknown list.' using errcode = '22023';
  end if;
  get diagnostics n = row_count;
  return jsonb_build_object('count', n, 'updated', n, 'failed', 0);
end
$function$

CREATE OR REPLACE FUNCTION public.crm_match_ids(p_module text, p_filter jsonb)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  m text := case lower(btrim(coalesce(p_module, '')))
    when 'leads' then 'lead' when 'contacts' then 'contact' when 'clients' then 'contact'
    when 'accounts' then 'account' when 'companies' then 'account'
    when 'opportunities' then 'opportunity' when 'deals' then 'deal' else lower(btrim(coalesce(p_module, ''))) end;
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  words text[];
  c_mode text; c_lo timestamptz; c_hi timestamptz; c_lo_d date; c_hi_d date;
  m_mode text; m_lo timestamptz; m_hi timestamptz; m_lo_d date; m_hi_d date;
  a_mode text; a_lo timestamptz; a_hi timestamptz; a_lo_d date; a_hi_d date;
  o_mode text; o_lo timestamptz; o_hi timestamptz; o_lo_d date; o_hi_d date;
  k_mode text; k_lo timestamptz; k_hi timestamptz; k_lo_d date; k_hi_d date;
  x_mode text; x_lo timestamptz; x_hi timestamptz; x_lo_d date; x_hi_d date;
begin
  if auth.uid() is null then raise exception 'Sign in required.' using errcode = '42501'; end if;
  if m not in ('lead', 'contact', 'account', 'opportunity', 'deal') then
    raise exception 'Unknown list.' using errcode = '22023';
  end if;
  words := regexp_split_to_array(lower(btrim(coalesce(f->>'q', ''))), '\s+');
  select b.mode, b.lo, b.hi, b.lo_date, b.hi_date into c_mode, c_lo, c_hi, c_lo_d, c_hi_d from public.crm_date_bounds(coalesce((select s from jsonb_array_elements(coalesce(f->'dates', '[]'::jsonb)) s where s->>'field' = 'createdAt' limit 1), '{}'::jsonb)) b;
  select b.mode, b.lo, b.hi, b.lo_date, b.hi_date into m_mode, m_lo, m_hi, m_lo_d, m_hi_d from public.crm_date_bounds(coalesce((select s from jsonb_array_elements(coalesce(f->'dates', '[]'::jsonb)) s where s->>'field' = 'modifiedAt' limit 1), '{}'::jsonb)) b;
  select b.mode, b.lo, b.hi, b.lo_date, b.hi_date into a_mode, a_lo, a_hi, a_lo_d, a_hi_d from public.crm_date_bounds(coalesce((select s from jsonb_array_elements(coalesce(f->'dates', '[]'::jsonb)) s where s->>'field' = 'lastActivityAt' limit 1), '{}'::jsonb)) b;
  select b.mode, b.lo, b.hi, b.lo_date, b.hi_date into o_mode, o_lo, o_hi, o_lo_d, o_hi_d from public.crm_date_bounds(coalesce((select s from jsonb_array_elements(coalesce(f->'dates', '[]'::jsonb)) s where s->>'field' = 'openDate' limit 1), '{}'::jsonb)) b;
  select b.mode, b.lo, b.hi, b.lo_date, b.hi_date into k_mode, k_lo, k_hi, k_lo_d, k_hi_d from public.crm_date_bounds(coalesce((select s from jsonb_array_elements(coalesce(f->'dates', '[]'::jsonb)) s where s->>'field' = 'closingDate' limit 1), '{}'::jsonb)) b;
  select b.mode, b.lo, b.hi, b.lo_date, b.hi_date into x_mode, x_lo, x_hi, x_lo_d, x_hi_d from public.crm_date_bounds(coalesce((select s from jsonb_array_elements(coalesce(f->'dates', '[]'::jsonb)) s where s->>'field' = 'expectedClose' limit 1), '{}'::jsonb)) b;

  if m = 'lead' then
    return query select l.id from public.crm_leads l
    where (coalesce(f->>'archived', '') = 'all' or (coalesce(f->>'archived', '') = 'only' and l.archived_at is not null) or (coalesce(f->>'archived', '') = '' and l.archived_at is null))
      and (coalesce(f->>'converted', '') = 'all' or (coalesce(f->>'converted', '') = 'only' and l.converted_at is not null) or (coalesce(f->>'converted', '') = '' and l.converted_at is null))
      and (nullif(f->>'ownerId', '') is null or (f->>'ownerId' = 'none' and l.owner_id is null) or l.owner_id::text = f->>'ownerId')
      and (nullif(f->>'relationshipStatus', '') is null or l.status = f->>'relationshipStatus')
      and (nullif(f->>'leadSource', '') is null or l.source = f->>'leadSource')
      and (nullif(f->>'roleInCompany', '') is null or l.role_in_company = f->>'roleInCompany')
      and (nullif(f->>'state', '') is null or l.crm_state = f->>'state')
      and (nullif(f->>'county', '') is null or (f->>'county' = 'none' and btrim(coalesce(l.crm_county, '')) = '') or lower(l.crm_county) = lower(f->>'county'))
      and (f->'custom' is null or f->'custom' = '{}'::jsonb or l.custom @> (f->'custom'))
      and (btrim(coalesce(f->>'q', '')) = '' or lower(coalesce(l.first_name, '') || ' ' || coalesce(l.last_name, '') || ' ' || coalesce(l.email, '') || ' ' || coalesce(l.company, '') || ' ' || coalesce(l.phone, '') || ' ' || coalesce(l.notes, '') || ' ' || coalesce(l.crm_county, '') || ' ' || coalesce(l.crm_city, '')) like all (array(select '%' || w || '%' from unnest(words) w where w <> '')))
      and (c_mode = 'none' or (c_mode = 'empty' and l.created_at is null) or (c_mode = 'present' and l.created_at is not null) or (c_mode = 'outside' and l.created_at is not null and ((c_lo is not null and l.created_at < c_lo) or (c_hi is not null and l.created_at >= c_hi))) or (c_mode = 'range' and (c_lo is null or l.created_at >= c_lo) and (c_hi is null or l.created_at < c_hi)))
      and (m_mode = 'none' or (m_mode = 'empty' and l.modified_at is null) or (m_mode = 'present' and l.modified_at is not null) or (m_mode = 'outside' and l.modified_at is not null and ((m_lo is not null and l.modified_at < m_lo) or (m_hi is not null and l.modified_at >= m_hi))) or (m_mode = 'range' and (m_lo is null or l.modified_at >= m_lo) and (m_hi is null or l.modified_at < m_hi)))
      and (a_mode = 'none' or (a_mode = 'empty' and not exists (select 1 from public.crm_activities act where act.entity = 'lead' and act.entity_id = l.id))
        or (a_mode = 'present' and exists (select 1 from public.crm_activities act where act.entity = 'lead' and act.entity_id = l.id))
        or (a_mode in ('range', 'outside') and exists (select 1 from (select max(act.created_at) as last_at from public.crm_activities act where act.entity = 'lead' and act.entity_id = l.id) z
          where z.last_at is not null and ((a_mode = 'range' and (a_lo is null or z.last_at >= a_lo) and (a_hi is null or z.last_at < a_hi)) or (a_mode = 'outside' and ((a_lo is not null and z.last_at < a_lo) or (a_hi is not null and z.last_at >= a_hi)))))));
  elsif m = 'contact' then
    return query select c.id from public.contacts c
    where not exists (select 1 from public.profiles p where p.id = c.profile_id and p.status is distinct from 'removed' and p.role is distinct from 'Outside user')
      and (coalesce(f->>'archived', '') = 'all' or (coalesce(f->>'archived', '') = 'only' and c.crm_archived_at is not null) or (coalesce(f->>'archived', '') = '' and c.crm_archived_at is null))
      and (nullif(f->>'ownerId', '') is null or (f->>'ownerId' = 'none' and c.crm_owner_id is null) or c.crm_owner_id::text = f->>'ownerId')
      and (nullif(f->>'relationshipStatus', '') is null or c.relationship_status = f->>'relationshipStatus')
      and (nullif(f->>'leadSource', '') is null or c.lead_source = f->>'leadSource')
      and (nullif(f->>'roleInCompany', '') is null or c.role_in_company = f->>'roleInCompany')
      and (nullif(f->>'state', '') is null or c.crm_state = f->>'state')
      and (nullif(f->>'contactType', '') is null or c.contact_type = f->>'contactType')
      and (nullif(f->>'county', '') is null or (f->>'county' = 'none' and btrim(coalesce(c.crm_county, '')) = '') or lower(c.crm_county) = lower(f->>'county'))
      and (nullif(f->>'tag', '') is null or lower(f->>'tag') = any (c.tags))
      and (f->'custom' is null or f->'custom' = '{}'::jsonb or c.custom @> (f->'custom'))
      and (btrim(coalesce(f->>'q', '')) = '' or lower(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '') || ' ' || coalesce(c.email, '') || ' ' || coalesce(c.company, '') || ' ' || coalesce(c.phone, '') || ' ' || coalesce(c.crm_notes, '') || ' ' || coalesce(c.crm_county, '') || ' ' || coalesce(c.crm_city, '')) like all (array(select '%' || w || '%' from unnest(words) w where w <> '')))
      and (c_mode = 'none' or (c_mode = 'empty' and c.created_at is null) or (c_mode = 'present' and c.created_at is not null) or (c_mode = 'outside' and c.created_at is not null and ((c_lo is not null and c.created_at < c_lo) or (c_hi is not null and c.created_at >= c_hi))) or (c_mode = 'range' and (c_lo is null or c.created_at >= c_lo) and (c_hi is null or c.created_at < c_hi)))
      and (m_mode = 'none' or (m_mode = 'empty' and c.modified_at is null) or (m_mode = 'present' and c.modified_at is not null) or (m_mode = 'outside' and c.modified_at is not null and ((m_lo is not null and c.modified_at < m_lo) or (m_hi is not null and c.modified_at >= m_hi))) or (m_mode = 'range' and (m_lo is null or c.modified_at >= m_lo) and (m_hi is null or c.modified_at < m_hi)))
      and (a_mode = 'none' or (a_mode = 'empty' and not exists (select 1 from public.crm_activities act where act.entity = 'contact' and act.entity_id = c.id))
        or (a_mode = 'present' and exists (select 1 from public.crm_activities act where act.entity = 'contact' and act.entity_id = c.id))
        or (a_mode in ('range', 'outside') and exists (select 1 from (select max(act.created_at) as last_at from public.crm_activities act where act.entity = 'contact' and act.entity_id = c.id) z
          where z.last_at is not null and ((a_mode = 'range' and (a_lo is null or z.last_at >= a_lo) and (a_hi is null or z.last_at < a_hi)) or (a_mode = 'outside' and ((a_lo is not null and z.last_at < a_lo) or (a_hi is not null and z.last_at >= a_hi)))))));
  elsif m = 'account' then
    return query select a.id from public.crm_accounts a
    where (coalesce(f->>'archived', '') = 'all' or (coalesce(f->>'archived', '') = 'only' and a.archived_at is not null) or (coalesce(f->>'archived', '') = '' and a.archived_at is null))
      and (nullif(f->>'ownerId', '') is null or (f->>'ownerId' = 'none' and a.owner_id is null) or a.owner_id::text = f->>'ownerId')
      and (nullif(f->>'kind', '') is null or a.kind = f->>'kind')
      and (f->'custom' is null or f->'custom' = '{}'::jsonb or a.custom @> (f->'custom'))
      and (btrim(coalesce(f->>'q', '')) = '' or lower(coalesce(a.name, '') || ' ' || coalesce(a.city, '') || ' ' || coalesce(a.notes, '') || ' ' || coalesce(a.phone, '')) like all (array(select '%' || w || '%' from unnest(words) w where w <> '')))
      and (c_mode = 'none' or (c_mode = 'empty' and a.created_at is null) or (c_mode = 'present' and a.created_at is not null) or (c_mode = 'outside' and a.created_at is not null and ((c_lo is not null and a.created_at < c_lo) or (c_hi is not null and a.created_at >= c_hi))) or (c_mode = 'range' and (c_lo is null or a.created_at >= c_lo) and (c_hi is null or a.created_at < c_hi)))
      and (m_mode = 'none' or (m_mode = 'empty' and a.modified_at is null) or (m_mode = 'present' and a.modified_at is not null) or (m_mode = 'outside' and a.modified_at is not null and ((m_lo is not null and a.modified_at < m_lo) or (m_hi is not null and a.modified_at >= m_hi))) or (m_mode = 'range' and (m_lo is null or a.modified_at >= m_lo) and (m_hi is null or a.modified_at < m_hi)))
      and (a_mode = 'none' or (a_mode = 'empty' and not exists (select 1 from public.crm_activities act where act.entity = 'account' and act.entity_id = a.id))
        or (a_mode = 'present' and exists (select 1 from public.crm_activities act where act.entity = 'account' and act.entity_id = a.id))
        or (a_mode in ('range', 'outside') and exists (select 1 from (select max(act.created_at) as last_at from public.crm_activities act where act.entity = 'account' and act.entity_id = a.id) z
          where z.last_at is not null and ((a_mode = 'range' and (a_lo is null or z.last_at >= a_lo) and (a_hi is null or z.last_at < a_hi)) or (a_mode = 'outside' and ((a_lo is not null and z.last_at < a_lo) or (a_hi is not null and z.last_at >= a_hi)))))));
  elsif m = 'opportunity' then
    return query select o.id from public.crm_opportunities o
    where (coalesce(f->>'archived', '') = 'all' or (coalesce(f->>'archived', '') = 'only' and o.archived_at is not null) or (coalesce(f->>'archived', '') = '' and o.archived_at is null))
      and (nullif(f->>'ownerId', '') is null or (f->>'ownerId' = 'none' and o.owner_id is null) or o.owner_id::text = f->>'ownerId')
      and (nullif(f->>'stage', '') is null or o.stage = f->>'stage')
      and (f->'custom' is null or f->'custom' = '{}'::jsonb or o.custom @> (f->'custom'))
      and (btrim(coalesce(f->>'q', '')) = '' or lower(coalesce(o.name, '') || ' ' || coalesce(o.notes, '')) like all (array(select '%' || w || '%' from unnest(words) w where w <> '')))
      and (c_mode = 'none' or (c_mode = 'empty' and o.created_at is null) or (c_mode = 'present' and o.created_at is not null) or (c_mode = 'outside' and o.created_at is not null and ((c_lo is not null and o.created_at < c_lo) or (c_hi is not null and o.created_at >= c_hi))) or (c_mode = 'range' and (c_lo is null or o.created_at >= c_lo) and (c_hi is null or o.created_at < c_hi)))
      and (m_mode = 'none' or (m_mode = 'empty' and o.modified_at is null) or (m_mode = 'present' and o.modified_at is not null) or (m_mode = 'outside' and o.modified_at is not null and ((m_lo is not null and o.modified_at < m_lo) or (m_hi is not null and o.modified_at >= m_hi))) or (m_mode = 'range' and (m_lo is null or o.modified_at >= m_lo) and (m_hi is null or o.modified_at < m_hi)))
      and (x_mode = 'none' or (x_mode = 'empty' and o.expected_close is null) or (x_mode = 'present' and o.expected_close is not null) or (x_mode = 'outside' and o.expected_close is not null and ((x_lo_d is not null and o.expected_close < x_lo_d) or (x_hi_d is not null and o.expected_close >= x_hi_d))) or (x_mode = 'range' and (x_lo_d is null or o.expected_close >= x_lo_d) and (x_hi_d is null or o.expected_close < x_hi_d)));
  else
    return query select g.id from public.deals g
    where (nullif(f->>'status', '') is null or f->>'status' = 'All' or g.status = f->>'status')
      and (nullif(f->>'ownerId', '') is null or (f->>'ownerId' = 'none' and not exists (select 1 from public.deal_sales_people s where s.deal_id = g.id)) or exists (select 1 from public.deal_sales_people s where s.deal_id = g.id and s.sales_id::text = f->>'ownerId'))
      and (nullif(f->>'clientId', '') is null or exists (select 1 from public.deal_participants p where p.deal_id = g.id and p.contact_id::text = f->>'clientId' and p.role in ('Client-Buyer', 'Client-Seller')))
      and (nullif(f->>'source', '') is null or (f->>'source' = 'none' and not exists (select 1 from public.deal_business_sources b where b.deal_id = g.id and coalesce(b.source, '') <> '')) or exists (select 1 from public.deal_business_sources b where b.deal_id = g.id and (b.source = f->>'source' or split_part(b.source, ':', 1) = f->>'source')))
      and (btrim(coalesce(f->>'q', '')) = '' or lower(coalesce(g.file_number, '') || ' ' || coalesce(g.street, '') || ' ' || coalesce(g.city, '') || ' ' || coalesce(g.notes, '')) like all (array(select '%' || w || '%' from unnest(words) w where w <> '')))
      and (c_mode = 'none' or (c_mode = 'range' and (c_lo is null or g.created_at >= c_lo) and (c_hi is null or g.created_at < c_hi)) or (c_mode = 'empty' and g.created_at is null) or (c_mode = 'present' and g.created_at is not null) or (c_mode = 'outside' and g.created_at is not null and ((c_lo is not null and g.created_at < c_lo) or (c_hi is not null and g.created_at >= c_hi))))
      and (o_mode = 'none' or (o_mode = 'empty' and g.open_date is null) or (o_mode = 'present' and g.open_date is not null) or (o_mode = 'outside' and g.open_date is not null and ((o_lo_d is not null and g.open_date < o_lo_d) or (o_hi_d is not null and g.open_date >= o_hi_d))) or (o_mode = 'range' and (o_lo_d is null or g.open_date >= o_lo_d) and (o_hi_d is null or g.open_date < o_hi_d)))
      and (k_mode = 'none' or (k_mode = 'empty' and g.closing_date is null) or (k_mode = 'present' and g.closing_date is not null) or (k_mode = 'outside' and g.closing_date is not null and ((k_lo_d is not null and g.closing_date < k_lo_d) or (k_hi_d is not null and g.closing_date >= k_hi_d))) or (k_mode = 'range' and (k_lo_d is null or g.closing_date >= k_lo_d) and (k_hi_d is null or g.closing_date < k_hi_d)))
      and (a_mode = 'none' or (a_mode = 'empty' and not exists (select 1 from public.crm_activities act where act.entity = 'deal' and act.entity_id = g.id))
        or (a_mode = 'present' and exists (select 1 from public.crm_activities act where act.entity = 'deal' and act.entity_id = g.id))
        or (a_mode in ('range', 'outside') and exists (select 1 from (select max(act.created_at) as last_at from public.crm_activities act where act.entity = 'deal' and act.entity_id = g.id) z
          where z.last_at is not null and ((a_mode = 'range' and (a_lo is null or z.last_at >= a_lo) and (a_hi is null or z.last_at < a_hi)) or (a_mode = 'outside' and ((a_lo is not null and z.last_at < a_lo) or (a_hi is not null and z.last_at >= a_hi)))))));
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.crm_match_plan(p_module text, p_filter jsonb, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  m text := case lower(btrim(coalesce(p_module, '')))
    when 'leads' then 'lead' when 'contacts' then 'contact' when 'clients' then 'contact'
    when 'accounts' then 'account' when 'companies' then 'account'
    when 'opportunities' then 'opportunity' when 'deals' then 'deal' else lower(btrim(coalesce(p_module, ''))) end;
  action text := lower(btrim(coalesce(p_action, 'update')));
  n int;
  recipients int;
  skipped int;
begin
  if auth.uid() is null then raise exception 'Sign in required.' using errcode = '42501'; end if;
  if action not in ('update', 'email') then raise exception 'Unknown action.' using errcode = '22023'; end if;
  select count(*) into n from public.crm_match_ids(m, p_filter);
  if action = 'update' then
    return jsonb_build_object('count', n, 'records', n, 'recipients', n, 'skipped', 0);
  end if;
  if m = 'lead' then
    select count(*) filter (where email <> ''), count(*) filter (where email = '') into recipients, skipped from (
      select distinct lower(btrim(l.email)) as email from public.crm_leads l where l.id in (select public.crm_match_ids(m, p_filter))
    ) s;
  elsif m = 'contact' then
    select count(*) filter (where email <> ''), count(*) filter (where email = '') into recipients, skipped from (
      select distinct lower(btrim(c.email)) as email from public.contacts c where c.id in (select public.crm_match_ids(m, p_filter))
    ) s;
  elsif m = 'account' then
    select count(distinct email) filter (where email <> ''), n - count(distinct account_id) filter (where email <> '') into recipients, skipped from (
      select a.id as account_id, lower(btrim(c.email)) as email
      from public.crm_accounts a
      left join public.contacts c on c.account_id = a.id and btrim(coalesce(c.email, '')) <> ''
      where a.id in (select public.crm_match_ids(m, p_filter))
    ) s;
  elsif m = 'opportunity' then
    select count(*) filter (where email <> ''), count(*) filter (where email = '') into recipients, skipped from (
      select distinct lower(btrim(coalesce(c.email, ''))) as email
      from public.crm_opportunities o
      left join public.contacts c on c.id = o.contact_id
      where o.id in (select public.crm_match_ids(m, p_filter))
    ) s;
  else
    select count(*) filter (where email <> ''), count(*) filter (where email = '') into recipients, skipped from (
      select distinct lower(btrim(coalesce(c.email, ''))) as email
      from public.deals g
      left join public.deal_participants p on p.deal_id = g.id
      left join public.contacts c on c.id = p.contact_id and btrim(coalesce(c.email, '')) <> ''
      where g.id in (select public.crm_match_ids(m, p_filter))
    ) s;
  end if;
  return jsonb_build_object('count', coalesce(recipients, 0), 'records', n, 'recipients', coalesce(recipients, 0), 'skipped', coalesce(skipped, n));
end
$function$

