CREATE OR REPLACE FUNCTION public.save_spouse(p_deal uuid, p_participant uuid, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare dp public.deal_participants; c public.contacts;
begin
  select * into dp from public.deal_participants where id = p_participant and deal_id = p_deal;
  if not found or dp.role not in ('Client-Buyer', 'Client-Seller') or not private.can_access_deal(p_deal) then
    raise exception 'Not available' using errcode = '42501';
  end if;
  select * into c from public.contacts where id = dp.contact_id;
  if c.profile_id is distinct from private.effective_uid() and not private.ssn_staff() then
    raise exception 'Not available' using errcode = '42501';
  end if;
  insert into public.spouse_info (participant_id, deal_id, full_name, citizenship, gender, marital_status, cell_phone, home_phone, work_phone, email, date_of_birth, poa_given)
  values (dp.id, p_deal,
    left(btrim(coalesce(p_data->>'fullName', '')), 200), left(btrim(coalesce(p_data->>'citizenship', '')), 80),
    left(btrim(coalesce(p_data->>'gender', '')), 40), left(btrim(coalesce(p_data->>'maritalStatus', '')), 40),
    left(btrim(coalesce(p_data->>'cellPhone', '')), 40), left(btrim(coalesce(p_data->>'homePhone', '')), 40),
    left(btrim(coalesce(p_data->>'workPhone', '')), 40), left(btrim(coalesce(p_data->>'email', '')), 200),
    left(btrim(coalesce(p_data->>'dateOfBirth', '')), 20), case when p_data->>'poaGiven' in ('Yes', 'No') then p_data->>'poaGiven' else '' end)
  on conflict (participant_id) do update set
    full_name = excluded.full_name, citizenship = excluded.citizenship, gender = excluded.gender,
    marital_status = excluded.marital_status, cell_phone = excluded.cell_phone, home_phone = excluded.home_phone,
    work_phone = excluded.work_phone, email = excluded.email, date_of_birth = excluded.date_of_birth, poa_given = excluded.poa_given;
  perform private.log_activity(p_deal, 'spouse.saved', 'participant', dp.id, 'Spouse information saved');
end
$function$

CREATE OR REPLACE FUNCTION public.save_task_flow(p_id uuid, p_name text, p_description text, p_trigger text, p_trigger_days integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_uid uuid := private.effective_uid();
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_desc text := btrim(coalesce(p_description, ''));
  v_days int := case when p_trigger in ('emd_not_received', 'days_before_closing') then p_trigger_days else null end;
  v_old public.task_flows; v_id uuid; v_changes text[] := '{}';
begin
  if not private.is_admin() then raise exception 'Only an Admin or Super admin can use Task Builder.' using errcode = '42501'; end if;
  if v_name = '' then raise exception 'Give the flow a name, for example "EMD reminder".' using errcode = 'P0001'; end if;
  if length(v_name) < 3 then raise exception 'The name is too short. Use at least 3 characters.' using errcode = 'P0001'; end if;
  if length(v_name) > 80 then raise exception 'The name is too long. Use 80 characters or fewer.' using errcode = 'P0001'; end if;
  if length(v_desc) > 500 then raise exception 'The description is too long. Use 500 characters or fewer.' using errcode = 'P0001'; end if;
  if p_trigger is null or p_trigger not in ('order_opened', 'contract_received', 'emd_received', 'emd_not_received', 'commitment_received', 'closing_date_set', 'days_before_closing') then
    raise exception 'Choose what starts the flow.' using errcode = 'P0001'; end if;
  if p_trigger in ('emd_not_received', 'days_before_closing') and (v_days is null or v_days < 1 or v_days > 60) then
    raise exception 'Days must be a whole number from 1 to 60.' using errcode = 'P0001'; end if;
  if exists (select 1 from public.task_flows f where f.id is distinct from p_id and lower(regexp_replace(btrim(f.name), '\s+', ' ', 'g')) = lower(v_name)) then
    raise exception 'Another flow already has that name. Use a different name.' using errcode = 'P0001'; end if;

  if p_id is null then
    insert into public.task_flows (name, description, trigger, trigger_days, active, created_by, updated_by)
      values (v_name, v_desc, p_trigger, v_days, false, v_uid, v_uid) returning id into v_id;
    insert into public.task_flow_log (flow_id, flow_name, action, detail, by_id)
      values (v_id, v_name, 'created', 'Starts: ' || private.task_flow_trigger_text(p_trigger, v_days) || '. Off.', v_uid);
    return v_id;
  end if;

  select * into v_old from public.task_flows where id = p_id for update;
  if not found then raise exception 'That flow was not found. Refresh the page and try again.' using errcode = 'P0001'; end if;
  if v_old.name <> v_name then v_changes := v_changes || ('name was "' || v_old.name || '"'); end if;
  if v_old.trigger <> p_trigger or v_old.trigger_days is distinct from v_days then
    v_changes := v_changes || ('starts: was ' || private.task_flow_trigger_text(v_old.trigger, v_old.trigger_days) || ', now ' || private.task_flow_trigger_text(p_trigger, v_days)); end if;
  if v_old.description <> v_desc then v_changes := v_changes || 'description changed'::text; end if;
  if cardinality(v_changes) = 0 then return p_id; end if;
  update public.task_flows set name = v_name, description = v_desc, trigger = p_trigger, trigger_days = v_days, updated_by = v_uid, updated_at = now() where id = p_id;
  insert into public.task_flow_log (flow_id, flow_name, action, detail, by_id) values (p_id, v_name, 'changed', array_to_string(v_changes, '; '), v_uid);
  return p_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_task_flow_v2(p_id uuid, p_name text, p_description text, p_trigger text, p_trigger_days integer, p_conditions jsonb, p_steps jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_uid uuid := private.effective_uid();
  v_cond jsonb := private.task_flow_clean_conditions(coalesce(p_conditions, '{}'));
  v_steps jsonb := private.task_flow_clean_steps(p_steps);
  v_old public.task_flows; v_id uuid; v_changes text[] := '{}'; v_why text;
begin
  if not private.is_admin() then raise exception 'Only an Admin or Super admin can use Task Builder.' using errcode = '42501'; end if;
  if p_id is not null then
    select * into v_old from public.task_flows where id = p_id for update;
    if not found then raise exception 'That flow was not found. Refresh the page and try again.' using errcode = 'P0001'; end if;
    if v_old.active then
      v_why := private.task_flow_can_run(p_trigger, v_steps);
      if v_why <> '' then raise exception '%', v_why using errcode = 'P0001'; end if;
    end if;
  end if;
  v_id := public.save_task_flow(p_id, p_name, p_description, p_trigger, p_trigger_days);   -- TB-1 checks name, trigger and days, and logs those changes
  if p_id is null then
    update public.task_flows set conditions = v_cond, steps = v_steps where id = v_id;
    update public.task_flow_log set detail = detail || ' ' || jsonb_array_length(v_steps) || case when jsonb_array_length(v_steps) = 1 then ' step.' else ' steps.' end
      where id = (select max(id) from public.task_flow_log where flow_id = v_id);
    return v_id;
  end if;
  if v_old.conditions is distinct from v_cond then v_changes := v_changes || 'which files changed'::text; end if;
  if v_old.steps is distinct from v_steps then v_changes := v_changes || ('steps changed (' || jsonb_array_length(v_steps) || ')'); end if;
  if cardinality(v_changes) > 0 then
    update public.task_flows set conditions = v_cond, steps = v_steps, updated_by = v_uid, updated_at = now() where id = p_id;
    insert into public.task_flow_log (flow_id, flow_name, action, detail, by_id)
      values (p_id, (select name from public.task_flows where id = p_id), 'changed', array_to_string(v_changes, '; '), v_uid);
  end if;
  return p_id;
end $function$

