CREATE OR REPLACE FUNCTION public.set_template_agent_roles(p_code text, p_roles text[])
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare clean text[] := array(select distinct r from unnest(coalesce(p_roles, '{}')) r order by r); tid uuid; title text;
begin
  if not private.is_admin() then raise exception 'Only an Admin or Super admin can change who may complete a task.' using errcode = 'P0001'; end if;
  if not clean <@ array['Buyer Agent', 'Listing Agent']::text[] then raise exception 'Only Buyer Agent or Listing Agent can be allowed.' using errcode = 'P0001'; end if;
  select id, task_templates.title into tid, title from public.task_templates where code = p_code order by version desc limit 1;
  if tid is null then raise exception 'Template not found.' using errcode = 'P0001'; end if;
  update public.task_templates set agent_roles = clean where code = p_code;
  perform private.log_activity(null, 'template.delegation', 'template', tid, title || ': agents who may complete it for their client: ' || coalesce(nullif(array_to_string(clean, ', '), ''), 'none'));
  return clean; end $function$

CREATE OR REPLACE FUNCTION public.set_template_due_anchor(p_code text, p_anchor text, p_due_days integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare n int;
begin
  if not private.is_admin() then raise exception 'Only an Admin or Super admin can change a task template.' using errcode = '42501'; end if;
  if p_anchor not in ('opened', 'contract', 'closing') then raise exception 'Due dates count from opened, contract, or closing.' using errcode = '22023'; end if;
  if p_due_days is null or p_due_days = 0 or p_due_days < -90 or p_due_days > 90 then raise exception 'Due days must be from -90 to 90, not zero.' using errcode = '22023'; end if;
  update public.task_templates set due_anchor = p_anchor, due_days = p_due_days
  where code = p_code and active and retired_at is null;
  get diagnostics n = row_count;
  if n = 0 then raise exception 'Task template not found.' using errcode = 'P0002'; end if;
end $function$

