CREATE OR REPLACE FUNCTION public.task_board(p_file_status text DEFAULT 'All'::text)
 RETURNS TABLE(id uuid, deal_id uuid, title text, description text, assigned_role text, status text, due_date date, completed_at timestamp with time zone, completed_by uuid, kind text, participant_id uuid, owner_profile_id uuid, template_code text, template_version integer, created_at timestamp with time zone, file_number text, street text, city text, state text, zip text, closing_date date, deal_status text, owner_name text, overdue boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  with board as (
    select t.id, t.deal_id, t.title, t.description, t.assigned_role, t.status, t.due_date, t.completed_at, t.completed_by,
           t.kind, t.participant_id, t.owner_profile_id, t.template_code, t.template_version, t.created_at,
           d.file_number, d.street, d.city, d.state, d.zip, d.closing_date, d.status as deal_status
    from public.tasks t
    join public.deals d on d.id = t.deal_id
    where coalesce(p_file_status, 'All') = 'All' or d.status = p_file_status
  ),
  names as (
    select n.deal_id, n.participant_id, n.owner_name
    from private.board_owner_names((
      select coalesce(array_agg(distinct b.deal_id), '{}'::uuid[]) from board b
    )) n
  )
  select board.id, board.deal_id, board.title, board.description, board.assigned_role, board.status, board.due_date,
         board.completed_at, board.completed_by, board.kind, board.participant_id, board.owner_profile_id,
         board.template_code, board.template_version, board.created_at,
         board.file_number, board.street, board.city, board.state, board.zip, board.closing_date, board.deal_status,
         names.owner_name,
         (board.status in ('todo', 'in_progress', 'blocked') and board.due_date is not null and board.due_date < private.office_today())
  from board
  left join names on names.deal_id = board.deal_id and names.participant_id = board.participant_id
  order by board.file_number, board.due_date nulls last, board.title
$function$

CREATE OR REPLACE FUNCTION public.task_grid(p_file_status text DEFAULT 'Open'::text)
 RETURNS TABLE(id uuid, deal_id uuid, title text, description text, assigned_role text, status text, due_date date, completed_at timestamp with time zone, completed_by uuid, kind text, participant_id uuid, owner_profile_id uuid, template_code text, template_version integer, created_at timestamp with time zone, file_number text, street text, city text, state text, zip text, closing_date date, deal_status text, owner_name text, overdue boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if not (private.is_processor() or private.is_admin()) then raise exception 'Only a Processor or Admin can open the task grid.' using errcode = 'P0001'; end if;
  return query select * from public.task_board(coalesce(p_file_status, 'Open'));
end $function$

CREATE OR REPLACE FUNCTION public.thread_invitees_list(p_threads uuid[])
 RETURNS TABLE(thread_id uuid, contact_id uuid, display_name text, role text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  select ti.thread_id, ti.contact_id,
         nullif(btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')), ''),
         (select dp.role from public.deal_participants dp where dp.deal_id = th.deal_id and dp.contact_id = ti.contact_id
            order by case when dp.role in ('Buyer Agent', 'Listing Agent') then 0 else 1 end, dp.role limit 1)
  from public.thread_invitees ti
  join public.threads th on th.id = ti.thread_id
  join public.contacts c on c.id = ti.contact_id
  where p_threads is not null and ti.thread_id = any (p_threads[1:200])
    and ti.thread_id in (select tp.thread_id from public.thread_participants tp
                         where tp.profile_id = (select private.effective_uid()) and tp.thread_id = any (p_threads[1:200]))
$function$

CREATE OR REPLACE FUNCTION public.thread_people(p_threads uuid[])
 RETURNS TABLE(profile_id uuid, display_name text, role text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
  with g as (select * from private.reader_gate()),
  want as (select th.id, th.deal_id from public.threads th where p_threads is not null and th.id = any (p_threads[1:200])),
  okdeal as (select d.deal_id from (select distinct deal_id from want) d cross join g
             where private.reader_can_deal(d.deal_id, g.uid, g.role, g.is_admin, g.contact_id, g.active)),
  t as (select w.id, w.deal_id from want w join okdeal o on o.deal_id = w.deal_id cross join g
        where g.is_processor or coalesce(g.role = 'Transaction Coordinator', false)
           or exists (select 1 from public.thread_participants tp where tp.thread_id = w.id and tp.profile_id = g.uid)),
  ids as (
    select tp.thread_id, tp.profile_id from public.thread_participants tp join t on t.id = tp.thread_id
    union
    select m.thread_id, m.author_id from public.messages m join t on t.id = m.thread_id where m.author_id is not null
  ),
  ppl as (select distinct on (ids.profile_id) ids.profile_id, t.deal_id from ids join t on t.id = ids.thread_id order by ids.profile_id, t.deal_id)
  select p.id,
         nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), ''),
         case when p.role = 'Outside user' then coalesce((
                select dp.role from public.deal_participants dp join public.contacts c on c.id = dp.contact_id
                where c.profile_id = p.id and dp.deal_id = ppl.deal_id order by dp.role limit 1), 'Outside user')
              else p.role end
  from ppl join public.profiles p on p.id = ppl.profile_id
$function$

