CREATE OR REPLACE FUNCTION public.wire_recipients(p_deal uuid)
 RETURNS TABLE(id uuid, first_name text, last_name text, role text, side text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$ BEGIN RETURN QUERY SELECT * FROM private.rpc_wire_recipients(p_deal); END; $function$

